window.LAW_DATA = {"id": "marafeat", "title": "قانون المرافعات المدنية والتجارية", "title_en": "CIVIL PROCEDURE", "cat": "إجراءات", "icon": "📋", "desc": "إجراءات التقاضي أمام المحاكم المدنية والتجارية من رفع الدعوى حتى التنفيذ.", "article_count": 526, "articles": [{"number": "1", "chapter": "كتاب تمهيدى", "text": "تسرى قوانين المرافعات على ما لم يكن فصل فيه من الدعاوى أو ما لم يكن تم من الإجراءات قبل تاريخ العمل بها ، ويستثنى من ذلك . 1 - القوانين المعدلة للاختصاص متى كان تاريخ العمل بها بعد أقفال باب المرافعة فى الدعوى . 2 - القوانين المعدلة للمواعيد متى كان الميعاد قد بدا قبل تاريخ العمل بها . 3 - القوانين المنظمة لطرق الطعن بالنسبة لما صدر من الأحكام قبل تاريخ العمل بها متى كانت هذه القوانين ملغية أو منشئة لطريق من تلك الطرق ."}, {"number": "2", "chapter": "كتاب تمهيدى", "text": "كل أجراء من إجراءات المرافعات تم صحيحا فى ظل قانون معمول به يبقى صحيحا ما لم ينص على غير ذلك . ولا يجرى ما يستحدث من مواعيد السقوط الا من تاريخ العمل بالقانون الذى استحدثها ."}, {"number": "3", "chapter": "كتاب تمهيدى", "text": "- \" لا تقبل أى دعوى ما لا يقبل أى طلب أو دفع استنادا لأحكام هذا القانون أو أى قانون آخر . لا يكون لصاحبة فيها مصلحة شخصية ومباشرة وقائمة يقرها القانون . ومع ذلك تكفى المصلحة المعتملة إذا كان الغرض من الطلب الاحتياط لدفع ضرر محدق أو الاستيثاق لحق يخشى زوال دليله عند النزاع فيه . وتقضى المحكمة من تلقاء نفسها ، فى أى حالة تكون عليها الدعوى ، بعدم القبول فى حالة عدم توافر الشروط المنصوص عليها فى الفقرتين السابقتين . ويجوز للمحكمة عند الحكم بعدم قبول الدعوى لانتفاء شرط المصلحة أن تحكم على المدعى بغرامة إجرائية لا تزيد عن خمسمائة جنية إذا تبينت أن المدعى قد أساء استعمال حقه فى التقاضى \" ."}, {"number": "3 مكررا", "chapter": "كتاب تمهيدى", "text": "- \" لا يسرى حكم المادة السابقة على سلطة النيابة العامة طبقا للقانون فى رفع الدعوى والتدخل فيها والطعن على أحكامها . كما لا يسرى أيضا على الأحوال التى يجيز فيها القانون رفع الدعوى أو الطعن أو التظلم من غير صاحب الحق فى رفعة حماية لمصلحة شخصية يقررها القانون \" ."}, {"number": "4", "chapter": "كتاب تمهيدى", "text": "إذا كان القانون الواجب التطبيق فى مسائل الأحوال الشخصية يحدد للخصم ميعاد لأتخاذ صفة كان له أن يطلب تأجيل الدعوى حتى ينقضى هذا الميعاد وذلك دون إخلال بحقه فى إبداء ما لديه من دفوع بعد انتهاء الأجل."}, {"number": "5", "chapter": "كتاب تمهيدى", "text": "إذا نص القانون على ميعاد حتمى لأتخاذ أجراء يحصل بالإعلان فلا يعتبر الميعاد مرعيا الا إذا تم إعلان الخصم خلاله ."}, {"number": "6", "chapter": "كتاب تمهيدى", "text": "كل إعلان أو تنفيذ يكون بواسطة المحضرين بناء على طلب الخصم أو قلم الكتاب أو أمر الحكمة ، ويقوم الخصوم أو وكلاؤهم بتوجيه الإجراءات وتقديم أوراقها للمحضرين لإعلانها أو تنفيذها ، كل هذا ما لم ينص على خلاف ذلك . ولا يسال المحضرون الا عن خطئهم فى القيام بوظائفهم."}, {"number": "7", "chapter": "كتاب تمهيدى", "text": "- \" لا يجوز إجراء أى إعلان أو تنفيذ قبل الساعة السابعة صباحا ولا بعد الساعة الثامنة مساء ولا فى أيام العطلة الرسمية ، الا فى حالات الضرورة وباذن كتابى من قاضى الأمور الوقتية \" ."}, {"number": "8", "chapter": "كتاب تمهيدى", "text": "- \" إذا تراءى للمحضر وجه للامتناع عن الاعلان كما لو تبين له اشتمال الورقة على بيانات مخالفة للنظام العام أو الآداب أو انه قد شابها غموض أو تجهيل او غير ذلك مما يتعذر معه إعلانها ، وجب عليه عرض الأمر فورا على قاضى الامور الوقتية ليأمر بعد سماع طالب الإعلان باعلان الورقة أو بعدم إعلانها أو بما فى إدخاله عليها من تغيير . وللطالب أن يتظلم من هذا الأمر إلى المحكمة الابتدائية فى غرفة المشورة لتفصل نهائيافى التظلم بعد سماع المحضر والطالب \" ."}, {"number": "9", "chapter": "كتاب تمهيدى", "text": "يجب أن تشتمل الأوراق التى يقوم المحضرون بإعلانها على البيانات الآتية : 1 - تاريخ اليوم والشهر والسنة والساعة التى حصل فيها الإعلان . 2 - اسم الطالب ولقبه ومهنته أو وظيفته وموطنه واسم من يمثله ولقبه ومهنته أو وظيفته وموطنه كذلك أن كان يعمل لغيره . 3 - اسم المحضر والمحكمة التى يعمل بها . 4 - اسم المعلن إليه ولقبه ومهنته أو وظيفته وموطنه فان لم يكن موطنه معلوما وقت الإعلان فاخر موطن كان له. 5 - أسم وصفة من سلمت إليه صورة الورقة وتوقيعه على الأصل بالاستلام. 6 - توقيع المحضر على كل من الأصل والصورة."}, {"number": "10", "chapter": "كتاب تمهيدى", "text": "تسلم الأوراق المطلوب إعلانها إلى الشخص نفسه أو فى موطنه ويجوز تسليمها فى الموطن المختار فى الأحوال التى يبينها القانون . وإذا لم يجد المحضر الشخص المطلوب إعلانه فى موطنه كان عليه أن يسلم الورقة إلى من يقرر انه وكيله أو انه يعمل فى خدمته أو انه من الساكنين معه من الازواج والأقارب والأصهار ."}, {"number": "11", "chapter": "كتاب تمهيدى", "text": "- \" إذا لم يجد المحضر من يصح تسليم الورقة إليه طبقا للمادة السابقة أو امتنع من وجده من المذكورين فيها عن التوقيع على الأصل بالاستلام أو عن استلام الصورة ، وجب عليه أن يسلمها فى اليوم ذاته إلى مأمور القسم أو المركز العمدة أو شيخ البلد الذى يقع موطن المعلن إليه فى دائرته حسب الأحوال وذلك توقيعه على الأصل بالاستلام . على المحضر خلال أربع وعشرين ساعة أن وجه إلى المعلن اليه فى موطنه الاصلى أو المختار كتابة مسجلا ، مرفقا به صورة اخرى من الورقة ، يخبره فيه الصورة سلمت إلى جهة الإدارة . ويجب على المحضر أن يبين ذلك كله فى حينه فى أصل الاعلان وصورتيه . ويعتبر الإعلان منتجا لاثاره من وقت تسليم الصورة إلى من سلمت إليه قانونا \" ."}, {"number": "12", "chapter": "كتاب تمهيدى", "text": "إذا أوجب القانون على الخصم تعيين موطن مختار فلم يفعل أو كان بيانه ناقصا أو غير صحيح جاز إعلانه فى قلم الكتاب بجميع الأوراق التى يصح إعلانه بها فى الموطن المختار . وإذا ألغى الخصم موطنه الأصلى أو المختار ولم يخبر خصمه بذلك صح إعلانه فيه ، وتسلم الصورة عند الاقتضاء إلى جهة الإدارة طبقا للمادة السابقة ."}, {"number": "13", "chapter": "كتاب تمهيدى", "text": "فيما عدا ما نص عليه فى توانين خاصة تسلم صورة الإعلان على الوجه الآتى : 1 - ما يتعلق بالدولة يسلم للوزراء ومديرى المصالح المختصة والمحافظين أو لمن يقوم مقامهم فيما عدا صحف الدعاوى وصحف الطعون والأحكام فتسلم الصورة إلى هيئة قضايا الدولة (5) أو فروعها بالأقاليم حسب الاختصاص المحلى لكل منها . 2 - ما يتعلق بالأشخاص العامة يسلم للنائب عنهاقانونا أو لمن يقوم قامه فيما عدا صحف الدعاوى وصحف الطعون والأحكام فتسلم الصورة إلى هينة قضايا الدولة (5) أو فروعها بالأقاليم حسب الاختصاص المحلى لكل منها . 3 - ما يتعلق بالشركات التجارية يسلم فى مركز إدارة الشركة لأحد الشركاء المتضامنين أو لرئيس مجلس الادارة وللمدير أو لمن يقوم مقامه فإن لم يكن للشركة مركز تسلم لواحد من هؤلاء لشخصه أو فى موطنه . 4 - ما يتعلق بالشركات المدنية والجمعيات والمؤسسات الخاصة وسائر الأشخاص الإعتبارية يسلم بمركز إدارتها للنائب عنها بمقتضى عقد انشائها أو نظامها أو لمن يقوم مقامه فإذا لم يكن لها مركز سلمت الصورة للنائب عنها لشخصه أو فى موطنه . 5 - ما يتعلق بالشركات الأجنبية التى لها فرع أو وكيل فى جمهورية مصر العربية يسلم إلى هذا الفرع أو الوكيل . 6 - ما يتعلق بأفراد القوات المسلحة ومن فى حكمهم يسلم بواسطة النيابة العامة إلى الإدارة القضائية المختصة بالقوات المسلحة. 7 - ما يتعلق بالمسجونين يسلم لمأمور السجن. 8 - ما يتعلق ببحارة السفن التجارية أو بالعاملين فيها يسلم للربان . 9 - ما يتعلق بالأشخاص الذين لهم موطن معلوم فى الخارج يسلم للنيابة العامة وعلى النيابة إرسالها لوزارة الخارجية لتوصيلها بالطرق الدبلوماسية ويجوز أيضا فى هذا الحالة وبشرط المعاملة بالمثل تسليم الصورة مباشرة لمقر البعثة الدبلوماسية للدولة التى يقع بها موطن المراد إعلانه كى تتولى توصيلها إليه. ويجب على المحضر خلال أربع وعشرين ساعة من تسليم الصورة للنيابة العامة المختصة أن يوجه إلى المعلن إليه فى موطنه المبين بالورقة وعلى نفقة الطالب كتابة موصى عليه بعلم الوصول يرفق به صورة اخرى ويخبره فيه أن الصورة المعلنة سلمت للنيابة العامة ويعتبر الإعلان منتجا لآثاره من وقت تسليم الصورة للنيابة العامة ما لم يكن مما يبدأ منه ميعاد فى حق المعلن إليه ، فلا يبدأ هذا الميعاد الا من تاريخ تسليم الصورة فى موطن المعلن إليه فى الخارج ، أو توقيعه على إيصال علم الوصول ، أو امتناعه عن استلام الصورة ، أو التوقيع على اصلها بالاستلام . ويصدر وزير العدل قرارا بقواعد تقدير نفقات الإرسال بالبريد وكيفية أدائها . 10 - إذا كان موطن المعلن إليه غير معلوم وجب أن تشتمل الورقة على آخر موطن معلوم له فى جمهورية مصر العربية أو فى الخارج وتسلم صورتها للنيابة . وفى جميع الحالات إذا لم يجد المحضر من يصح تسليم ، الورقة إليه أو امتنع المراد اعلانه أو من ينوب عنه عن التوقيع على اصلها بالاستلام أو عن استلام الصورة اثبت المحضر ذلك فى حينه فى الأصل والصورة وسلم الصورة للنيابة العامة."}, {"number": "14", "chapter": "كتاب تمهيدى", "text": "تحكم المحكمة بغرامة لا تقل عن مائة جنيها ولا تجاوز ربعمائة جنيها على طالب الإعلان إذا تعمد ذكر موطن غير صحيح للمعلن إليه بقصد عدم وصول الإعلان إليه ."}, {"number": "15", "chapter": "كتاب تمهيدى", "text": "إذا عين القانون للحضور أو لحصول الإجراء ميعادا مقدرا بالأيام أو الشهور أو بالسنين فلا يحسب منه يوم الإعلان أو حدوث الأمر المعتبر فى نظر القانون مجريا للميعاد ، اما إذا كان الميعاد مما يجب انقضاؤه قبل الإجراء فلا يجوز حصول الإجراء الا بعد انقضاء اليوم الأخير من الميعاد. وينقضى الميعاد بانقضاء اليوم الأخير منه إذا كان ظرفا يجب أن يحصل فيه الإجراء . وإذا كان الميعاد مقدرا بالساعات كان حساب الساعة التى يبدأ منها والساعة التى ينقضى بها على الوجه المتقدم. وتحسب المواعيد المعينة بالشهر أو بالسنة بالتقويم الشمسى ما لم ينص القانون على غير ذلك."}, {"number": "16", "chapter": "كتاب تمهيدى", "text": "إذا كان الميعاد معينا فى القانون للحضور أو لمباشرة أجراء فيه قلد عليه يوم لكل مسافة مقدارها خمسون كيلو مترا بين المكان الذى يجب الانتقال منه والمكان الذى يجب الانتقال إليه ، وما يزيد من الكسور على الثلاثين كيلو مترا يزداد له يوم على الميعاد . ولا يجوز أن يجاوز ميعاد المسافة أربعة أيام . ولكون ميعاد المسافة خمسة عشر يوما بالنسبة لمن يقع موطنه فى مناطق الحدود ."}, {"number": "17", "chapter": "كتاب تمهيدى", "text": "ميعاد المسافة لمن يكون موطنه فى الخارج ستون يوما. ويجوز بأمر من قاضى الأمور الوقتية إنقاص هذا الميعاد تبعا لسهولة المواصلات وظروف الاستعجال ويعلن هذا الأمر مع الورقة . ولا يعمل بهذا الميعاد فى حق من يعلن لشخصه فى الجمهورية اثناء وجوده بها انما يجوز لقاضى الأمور الوقتية أو للمحكمة عند نظر الدعوى أن تأمر بمد المواعيد العادية أو بإعتبارها ممتدة على الا يجاوز فى الحالين الميعاد الذى كان يستحقه لو أعلن فى موطنه فى الخارج ."}, {"number": "18", "chapter": "كتاب تمهيدى", "text": "إذا صادت آخر الميعاد عطلة رسمية امتد إلى أول يوم عمل بعدها ."}, {"number": "19", "chapter": "كتاب تمهيدى", "text": "يترتب البطلان على عدم مراعاة المواعيد والإجراءات المنصوص عليها فى المواد 6 ، 7 ، 8 ، 9 ، 10 ، 11 و 13 ."}, {"number": "20", "chapter": "كتاب تمهيدى", "text": "يكون الإجراء باطلا إذا نص القانون صراحة على بطلانه أو إذا شابه عيب لم تتحقق بسببه الغاية من الإجراء . ولا يحكم بالبطلان رغم النص عليه إذا ثبت تحقق الغاية من الإجراء ."}, {"number": "21", "chapter": "كتاب تمهيدى", "text": "لا يجوز أن يتمسك بالبطلان الا من شرع البطلان لمصلحته . ولا يجوز التمسك بالبطلان من الخصم الذى تسبب فيه ، وذلك كله فيما عدا الحالات التى يتعلق فيها البطلان بالنظام العام ."}, {"number": "22", "chapter": "كتاب تمهيدى", "text": "يزول البطلان إذا نزل عنه من شرع لمصلحته صراحة أو ضمنا وذلك فيما عدا الحالات التى يتعلق فيها البطلان بالنظام العام ."}, {"number": "23", "chapter": "كتاب تمهيدى", "text": "يجوز تصحيح الإجراء الباطل ولو بعد التمسك بالبطلان على أن يتم ذلك فى الميعاد المقرر قانونا لأتخاذ الإجراء ، فإذا لم يكن للإجراء ميعاد مقرر فى القانون حددت المحكمة ميعادا مناسبا لتصحيحه ولا يعقد بالإجراء الا من تاريخ تصحيحه ."}, {"number": "24", "chapter": "كتاب تمهيدى", "text": "إذا كان الإجراء باطلا وتوفرت فيه عناصر أجراء آخر فانه يكون صحيحا بإعتباره الإجراء الذى توفرت عناصره. وإذا كان الإجراء باطلا فى شق منه فإن هذا الشق وحده هو الذى يبطل . ولا يترتب على بطلان الإجراء بطلان الإجراءات السابقة عليه أو الإجراءات اللاحقة إذا لم تكن مبنية عليه."}, {"number": "25", "chapter": "كتاب تمهيدى", "text": "يجب أن يحضر مع القاضى فى الجلسات وفى جميع إجراءات الإثبات كاتب يحرر المحضر ويوقعه مع القاضى والا كان العمل باطلا ."}, {"number": "26", "chapter": "كتاب تمهيدى", "text": "لا يجوز للمحضرين ، ولا للكتبة ولا لغيرهم من أعوان القضاء أن يباشروا عملا يدخل فى حدود وظائفهم فى الدعاوى الخاصة بهم أو بأزواجهم أو أقابلهم أو أصهارهم للدرجة الرابعة والا كان هذا العمل باطلا ."}, {"number": "27", "chapter": "كتاب تمهيدى", "text": "قاضى الأمور الوقتية فى المحكمة الإبتدائية هو رئيسها أو من يقوم مقامة أو من يندب لذلك من قضاتها وفى محكمة المواد الجزئية هو قاضيها ."}, {"number": "28", "chapter": "الفصل الأول", "text": "تختص محاكم الجمهورية بنظر الدعاوى التى ترفع على المصرى ولو لم يكن له موطن أو محل اقامة فى الجمهورية وذلك فيما عدا الدعاوى العقارية المتعلقة بعقار واقع فى الخارج ."}, {"number": "29", "chapter": "الفصل الأول", "text": "تختص محاكم الجمهورية بنظر الدعاوى التى ترفع على الأجنبى . الذى له موطن أو محل أقامة فى الجمهورية وذلك فيما عدا الدعاوى العقارية المتعلقة بعقار واقع فى الخارج ."}, {"number": "30", "chapter": "الفصل الأول", "text": "تختص محاكم الجمهورية بنظر الدعاوى التى ترفع على الأجنبى الذى ليس له موطن أو محل أقامة فى الجمهورية وذلك فى الأحوال الآتية : 1 - إذا كان له فى الجمهورية موطن مختار . 2 - إذا كانت الدعوى متعلقة بمال موجود فى الجمهورية أو كانت متعلقة بإلتزام نشأ أو نفذ أوكان واجبا تنفيذه فيها أو كانت متعلقة بإفلاس اشهر فيها. 3 - إذا كانت الدعوى معارضة فى عقد زواج وكان العقد يراد إبرامه لدى موثق مصرى . 4 - إذا كانت الدعوى متعلقة بطلب فسخ الزواج أو بالتطليق أو بالانفصال وكانت مرفوعة من زوجة فقدت جنسية الجمهورية بالزواج مش كان لها موطن فى الجمهورية ، أو كانت الدعوى مرفوعة من زوجة لها موطن فى الجمهورية على زوجها الذى كان له موطن فيها متى كان الزوج قد هجر زوجته وجعل موطنه فى الخارج بعد قيام سبب الفسخ أو التطليق أو الانفصال أو كان قد ابعد عن الجمهورية . 5 - إذا كانت الدعوى متعلقة بطلب نفقة للام أو للزوجة متى كان لهما موطن فى الجمهورية أو للصغير المقيم فيها. 6 - إذا كانت الدعوى بشأن نسب صفير يقيم فى الجمهورية أو بسلب الولاية على نفسه أو الحد منها أو وقفها أو استردادها . 7 - إذا كانت الدعوى متعلقة بمسألة من مسائل الأحوال الشخصية وكان المدعى وطنيا أو كان أجنبيا له موطن فى الجمهورية ، وذلك إذا لم يكن للمدعى عليه موطن معروف فى الخارج أو إذا كان القانون الوطنى واجب التطبيق فى الدعوى . 8 - إذا كانت الدعوى متعلقة بمسألة من مسائل الولاية على المال مش كان للقاصر أو المطلوب الحجر عليه أو مساعدته قضائيا موطن أو محل أقامة فى الجمهورية أو إذا كان بها آخر موطن أو محل أقامة للغائب . 9 - إذا كان لأحد المدعى عليهم موطن أو محل أقامة فى الجمهورية ."}, {"number": "31", "chapter": "الفصل الأول", "text": "تختص محاكم الجمهورية بمسائل الإرث وبالدعاوى المتعلقة بالتركة متى كانت التركة قد افتتحت فى الجمهورية ، أو كان المورث مصريا أو كانت أموال التركة كلها او بعضها فى الجمهورية ."}, {"number": "32", "chapter": "الفصل الأول", "text": "تختص محاكم الجمهورية بالفصل فى الدعاوى ولو لم تكن داخلة فى اختصاصها طبقا للمواد السابقة إذا قبل الخصم ولايتها صراحة أو ضمنا ."}, {"number": "33", "chapter": "الفصل الأول", "text": "إذا رفعت بحاكم الجمهورية دعوى داخلة فى اختصاصها تكون هذه المحاكم مختصة بالفصل فى المسائل الأولية والطلبات العارضة على الدعوى الأصلية كما تختص بالفصل فى كل طلب يرتبط بهذه الدعوى ويقتضى حسن سير العدالة أن ينظر معها ."}, {"number": "34", "chapter": "الفصل الأول", "text": "تختص محاكم الجمهورية بالأمر بالإجراءات الوقتية والتحفظية التى تنفذ فى الجمهورية ولو كانت غير مختصة بالدعوى الأصلية ."}, {"number": "35", "chapter": "الفصل الأول", "text": "إذا لم يحضر المدعى عليه ولم تكن محاكم الجمهورية مختصة بنظر الدعوى طبقا للمواد السابقة تحكم المحكمة بعدم اختصاصها من تلقاء نفسها ."}, {"number": "36", "chapter": "الفصل الثانى", "text": "تقدر قيمة الدعوى بإعتبارها يوم رفع الدعوى ويدخل فى التقدير ما يكون مستحقا يومئذ من الفوائد والتعويضات والمصاريف وغيرها من الملحقات المقدرة القيمة ، وكذا طلب ما يستجد من الأجرة بعد رفع الدعوى إلى يوم الحكم فيها . وفى جميع الأحوال يعقد بقيمة البناء أو الغراس إذا طلبت إزالته . ويكون التقدير على أساس آخر طلبات الخصوم ."}, {"number": "37", "chapter": "الفصل الثانى", "text": "يراعى فى تقدير قيمة الدعوى ما يأتى : 1 - الدعاوى التى يرجع فى تقدير قيمتها إلى قيمة العقار يكون تقدير هذه القيمة بإعتبار خمسمائة مثل من قيمة الضريبة الأصلية المربوطة عليه إذا كان العقار مبنيا ، فإن كان من الأراضى يكون التقدير بإعتبار أربعمائة مثل من قيمة الضريبة الأصلية. فإذا كان العقار غير مربوط عليه ضريبة قدرت المحكمة قيمته . 2 - الدعاوى المتعلقة بملكية العقارات والمنازعات الموضوعية المتعلقة بالتنفيذ على العقار تقدر قيمتها بقيمة العقار. اما الدعاوى المتعلقة بحق ارتفاق فتقدر قيمتها بإعتبار ربع قيمة العقار المقرر عليه الحق . فإذا كانت متعلقة بحق انتفاع أو بالرقبة قدرت بإعتبار نصف قيمة العقار . 3 - إذا كانت الدعوى بطلب تقدير قيمة للحكر أو بزيادتها إلى قيمة معينة قدرت بالقيمة السنوية المطلوب تقديرها أو بقيمة الريادة فى سنة مضروبا كل منهما فى عشرين. 4 - دعاوى الحيازة تقدر قيمتها بقيمة الحق الذى قرر عليه الحيازة. 5 - إذا كانت الدعوى خاصة بايراد فتقدر عند المنازعة فى سند ترتيبه على أساس مرتب عشرين سنة إذا كان مؤبدا وعلى أساس مرتب عشر سنين أن كان لمدى الحياة. 6 - الدعاوى المتعلقة بالمحاصيل تقدر قيمتها على حسب أسعارها فى أسواقها العامة . 7 - إذا كانت الدعوى بطلب صحة عقد أو إبطاله أو فسخه تقدر قيمتها بقيمة المتعاقد عليه ، وبالنسبة لعقود البدل تقدر الدعوى بأكبر البدلين قيمة . 8 - إذا كانت الدعوى بطلب صحة عقد مستمر أو بإبطاله كان التقدير بإعتبار مجموع المقابل النقدى عن مدة العقد كلها . وإذا كانت بطلب فسخ العقد كان التقدير بإعتبار المقابل النقدى عن المدة الواردة فى العقد فإذا كان العقد قد نفذ فى جزء منه كان التقدير بإعتبار المدة الباقية . وإذا كانت الدعوى متعلقة بامتداد العقد كان التقدير بإعتبار المقابل النقدى للمدة التى قام النزاع على امتداد العقد إليها . 9 - إذا كانت الدعوى بين الدائن الحاجز والمدين بشأن صحة حجز منقول أو بطلانه تقدر بقيمة الدين المحجوز من اجله . وإذا كانت بين دائن ومدينه بشأن رهن حيازة أو حق امتياز أو رهن رسمى أو حق اختصاص تقدر بإعتبار قيمة الدين المضمون . فإذا كانت مقامة من الغير باستحقاقه للأموال المحجوزة أو المحملة بالحقوق المذكورة كان التقدير بإعتبار قيمة هذه الأموال . 10 - دعاوى صحة التوقيع ودعاوى التزوير الأصلية تقدر قيمتها بقيمة الحق المثبت فى الورقة المطلوب الحكم بصحة التوقيع عليها او بتزويرها ."}, {"number": "38", "chapter": "الفصل الثانى", "text": "إذا تضمنت الدعوى طلبات متعددة ناشئة عن سبب قانونى واحد كان التقدير بإعتبار قيمتها جملة ، فإن كانت ناشئة عن أسباب قانونية مختلفة كان التقدير بإعتبار قيمة كل منها على حدة . اما إذا تضمنت الدعوى طلبات تعتبر مندمجة فى الطلب الأصلى فتقدر قيمتها بقيمة هذا الطلب وحده ."}, {"number": "39", "chapter": "الفصل الثانى", "text": "إذا كانت الدعوى مرفوعة من واحد أو أكثر على واحد أو أكثر بمقتضى سبب قانونى واحد كان التقدير بإعتبار قيمة المدعى به دون التفات إلى نصيب كل منهم فيه ."}, {"number": "40", "chapter": "الفصل الثانى", "text": "إذا كان المطلوب جزع من حق قدرت الدعوى بقيمة هذا الجزء الا إذا كان الحق كله متنازعا فيه ولم يكن الجزء المطلوب باقيا منه فيكون التقدير بإعتبار قيمة الحق بأكمله ."}, {"number": "41", "chapter": "الفصل الثانى", "text": ". إذا كانت الدعوى بطلب غير قابل للتقدير بحسب القواعد المتقدمة اعتبرت قيمتها زائدة على مائتى ألف جنيه."}, {"number": "42", "chapter": "الفصل الثالث", "text": "تختص محكمة المواد الجزئية بالحكم ابتدائياً في الدعاوى المدنية والتجارية التي لا تجاوز قيمتها مائتى ألف جنيه ويكون حكمها انتهائياً إذا كانت قيمة الدعوى لا تجاوز ثلاثين ألف جنيه. وذلك مع عدم الإخلال بما للمحكمة الابتدائية من اختصاص آخر ينص عليه القانون."}, {"number": "43", "chapter": "الفصل الثالث", "text": "تختص محكمة المواد الجزئية كذلك بالحكم ابتدائياً مهما تكن قيمة الدعوى وانتهائياً إذا لم تجاوز قيمتها ثلاثين ألف جنيه فيما يلي: (1) الدعاوى المتعلقة بالانتفاع بالمياه وتطهير الترع والمساقى والمصارف. (2) دعاوى تعيين الحدود وتقدير المسافات فيما يتعلق بالمباني والأراضي والمنشآت الضارة إذا لم تكن الملكية أو الحق محل نزاع. (3) دعاوى قسمة المال الشائع. (4) الدعاوى المتعلقة بالمطالبة بالأجور والمرتبات وتحديدها. (5) دعاوى صحة التوقيع أيًا كانت قيمتها. (6) دعاوى تسليم العقارات إذا رفعت بصفة أصلية، ويتعين على المدعى إخطار ذوى الشأن من الملاك والحائزين وأصحاب الحقوق بالدعوى وذلك بورقة من أوراق المحضرين، وفي حالة عدم الاستدلال على أشخاصهم بعد إجراء التحريات الكافية يتم الإخطار عن طريق الوحدة المحلية المختصة بطريق اللصق في مكان ظاهر بواجهة العقار وفي مقر نقطة الشرطة الواقع في دائرتها العقار وفي مقر عمدة الناحية ولوحة الإعلانات في مقر الوحدة المحلية المختصة بحسب الأحوال، ولا تحكم المحكمة في الدعوى إلا بعد تمام الإخطار وتقديم المدعى المستندات التي تسانده في دعواه ولو سلم المدعى عليه بطلبات المدعى."}, {"number": "44", "chapter": "الفصل الثالث", "text": "لا يجوز أن يجمع المدعى فى دعوى الحيازة بينها وبين المطالبة بالحق والا سقط ادعاؤه بالحيازة . ولا يجوز أن يدفع المدعى عليه دعوى الحيازة بالاستناد إلى الحق ، ولا تقبل دعواه بالحق قبل الفصل فى دعوى الحيازة وتنفيذ الحكم الذى يصدر فيها الا إذا تخلى بالفعل عن الحيازة لخصمه . وكذلك لا يجوز الحكم فى دعاوى الحيازة على أساس ثبوت الحق أو نفيه ."}, {"number": "44 مكرر", "chapter": "الفصل الثالث", "text": "يجب على النيابة العامة - متى عرضت عليها - منازعة من منازعات الحيازة مدنية كانت ، أو جنائية ، أن تصدر فيها قرارا وقتيا مسببا واجب التنفيذ فورا بعد سماع أقوال أطراف النزاع وإجراءات التحقيقات اللازمة ويصدر القرار المشار إليه من عضو نيابة بدرجة رئيس نيابة على الأقل . وعلى النيابة العامة إعلان هذا القرار لذوى الشأن خلال ثلاثة أيام من تاريخ صدوره . وفى جميع الأحوال يكون التظلم من هذا القرار لكل ذى شأن أمام القاضى المختص بالأمور المستعجلة بدعوى ترفع بالإجراءات المعتادة فى ميعاد خمسة عشر يوما من يوم إعلانه بالقرار . ويحكم القاضى فى التظلم بحكم وقتى بتأييد القرار أو بتعديله أو بإلغائه ، وله بناء على طلب المتظلم أن يوقف تنفيذ القرار المتظلم منه إلى أن يفصل فى التظلم."}, {"number": "45", "chapter": "الفصل الثالث", "text": "يندب فى مقر المحكمة الإبتدائية قاض من قضاتها ليحكم بصفة مؤقتة ومع عدم المساس بالحق فى المسائل المستعجلة التى يخشى عليها من فوات الوقت . اما فى خارج دائرة المدينة التى بها مقر المحكمة الإبتدائية فيكون هذا الاختصاص لمحكمة المواد الجزئية . على أن هذا لا يمنع من اختصاص محكمة الموضوع أيضا بهذه المسائل إذا رفعت لها بطريق التبعية ."}, {"number": "46", "chapter": "الفصل الثالث", "text": "لا تختص محكمة المواد الجزئية بالحكم فى الطلب العارض أو الطلب المرتبط بالطلب الأصلى إذا كان بحسب قيمته أو نوعه لا يدخل فى اختصاصها . وإذا عرض عليها طلب من هذا القبيل جاز لها أن ، تحكم فى الطلب الأصلى وحده إذا لم يترتب على ذلك ضرر بسير العدالة والا وجب عليها أن تحكم من تلقاء نفسها بإحالة الدعوى الأصلية والطلب العارض أو المرتبط بحالتهما إلى المحكمة الابتدائية المختصة ويكون حكم الإحالة غير قابل للطعن ."}, {"number": "47", "chapter": "الفصل الثالث", "text": "تختص المحكمة الابتدائية بالحكم ابتدائيا في جميع الدعاوى المدنية والتجارية التي ليست من اختصاص محكمة المواد الجزئية ويكون حكمها انتهائياً إذا كانت قيمة الدعوى لا تجاوز مائتى ألف جنيه. وتختص كذلك بالحكم في قضايا الاستئناف الذي يرفع إليها عن الأحكام الصادرة ابتدائياً من محكمة المواد الجزئية أو من قاضى الأمور المستعجلة. كما تختص بالحكم في الطلبات الوقتية أو المستعجلة وسائر الطلبات العارضة وكذلك في الطلبات المرتبطة بالطلب الأصلي مهما تكن قيمتها أو نوعها."}, {"number": "48", "chapter": "الفصل الثالث", "text": "تختص محكمة الاستئناف بالحكم فى قضايا الإستئناف التى ترفع إليها عن الأحكام الصادرة إبتدائيا من المحاكم الابتدائية.وكذلك عن الأحكام الصادرة من المحاكم الجزئية فى الدعاوى المنصوص عليها فى البند السادس من المادة 43 من هذا القانون ."}, {"number": "49", "chapter": "الفصل الرابع", "text": "يكون الاختصاص للمحكمة التى يقع فى دائرتها موطن المدعى عليه ما لم ينص القانون على خلاف ذلك . فإن لم يكن للمدعى عليه موطن فى الجمهورية يكون الاختصاص للمحكمة التى يقع فى دائرتها محل أقامته. وإذا تعدد المدعى عليهم كان الاختصاص للمحكمة التى يقع فى دائرتها موطن أحدهم ."}, {"number": "50", "chapter": "الفصل الرابع", "text": "فى الدعاوى العينية العقارية ودعاوى الحيازة يكون الاختصاص للمحكمة التى يقع فى دائرتها العقار أو أحد أجزائه إذ كان واقعة فى دوائر محاكم متعددة . وفى الدعاوى الشخصية العقارية يكون الاختصاص للمحكمة التى يقع فى دائرتها العقار أو موطن المدعى عليه . وإستثناء من حكم المادة 108 من هذا القانون تختص المحكمة الجزئية الواقع فى دائرتها العقار دون غيرها بدعاوى تسليم العقارات ."}, {"number": "51", "chapter": "الفصل الرابع", "text": "فى الدعاوى الجزئية التى ترفع على الحكومة أو وحدات الإدارة المحلية أو الهيئات العامة أو المؤسسات العامة يكون الاختصاص للمحكمة التى يقع فى دائرتها مقر المحافظة ، مع مراعاة القواعد المتقدمة ."}, {"number": "52", "chapter": "الفصل الرابع", "text": "فى الدعاوى المتعلقة بالشركات أو الجمعيات القائمة أو التى فى درر التصفية أو المؤسسات الخاصة يكون الاختصاص للمحكمة التى يقع فى دائرتها مركز إداراتها سواء أكانت الدعوى على الشركة أو الجمعية أو المؤسسة أم من الشركة أو الجمعية أو المؤسسة على أحد الشركاء أو الأعضاء أم من شريك أو عضو على آخر . ويجوز رفع الدعوى إلى المحكمة التى يقع فى دائرتها فرع الشركة أو الجمعية أو المؤسسة وذلك فى المسائل المتصلة بهذا الفرع ."}, {"number": "53", "chapter": "الفصل الرابع", "text": "الدعاوى المتعلقة بالتركات التى ترفع قبل قسمة التركة من الدائن أو من بعض الورثة على بعض تكون من اختصاص المحكمة التى يقع فى دائرتها آخر موطن للمتوفى ."}, {"number": "54", "chapter": "الفصل الرابع", "text": "فى مسائل الإفلاس يكون الاختصاص للمحكمة التى قضت به ."}, {"number": "55", "chapter": "الفصل الرابع", "text": "فى المواد التجارية يكون الاختصاص لمحكمة المدعى عليه أو للمحكمة التى تم الاتفاق ونفذ كله أو بعضه فى دائرتها أو للمحكمة التى يجب تنفيذ الاتفاق فى دائرتها ."}, {"number": "56", "chapter": "الفصل الرابع", "text": "فى المنازعات المتعلقة بالتوريدات والمقاولات وأجرة المساكن وأجور العمال والصناع والإجراء يكون الاختصاص لمحكمة موطن المدعى عليه أو للمحكمة التى تم الاتفاق أو نفذ فى دائرتها متى كان فيها موطن المدعى."}, {"number": "57", "chapter": "الفصل الرابع", "text": "فى الدعاوى المتعلقة بالنفقات يكون الاختصاص للمحكمة التى يقع فى دائرتها موطن المدعى علبه أو موطن المدعى."}, {"number": "58", "chapter": "الفصل الرابع", "text": "فى المنازعات المتعلقة بطلب قيمة التأمين يكون الاختصاص للمحكمة التى يقع فى دائرتها موطن المستفيد أو مكان المال المؤمن عليه ."}, {"number": "59", "chapter": "الفصل الرابع", "text": "فى الدعاوى المتضمنة طلب أجراه وقتى يكون الاختصاص للمحكمة التى يقع فى دائرتها موطن المدعى عليه أو المحكمة المطلوب حصول الإجراء فى دائرتها وفى المنازعات المستعجلة المتعلقة بتنفيذ الأحكام والسندات يكون الاختصاص للمحكمة التى يجرى فى دائرتها التنفيذ ."}, {"number": "60", "chapter": "الفصل الرابع", "text": "تختص المحكمة التى تنظر الدعوى الأصلية بالفصل فى الطلبات العارضة . على انه يجوز للمدعى عليه فى طلب الضمان أن يتمسك بعدم اختصاص المحكمة إذا اثبت أن الدعوى الأصلية لم تقم الا بقصد جلبه أمام محكمة غير محكمته ."}, {"number": "61", "chapter": "الفصل الرابع", "text": "إذا لم يكن للمدعى عليه موطن ولا محل أقامة فى الجمهورية ولم يتيسر تعيين المحكمة المختصة على هو الأحكام المتقدمة يكون الاختصاص للمحكمة التى يقع فى دائرتها موطن المدعى أو محل إقامته فإن لم يكن له موطن ولا محل أقامة كان الاختصاص لمحكمة القاهرة"}, {"number": "62", "chapter": "الفصل الرابع", "text": "إذا اتفق على اختصاص محكمة معينة يكون الاختصاص لهذه المحكمة أو للمحكمة التى يقع فى دائرتها موطن المدعى عليه. على انه فى الحالات التى ينعى فيها القانون تخويل الاختصاص لمحكمة على خلاف حكم المادة ( 49 ) لا يجوز الاتفاقى مقدما على ما يخالف هذا الاختصاص."}, {"number": "63", "chapter": "الباب الثانى", "text": "ترفع الدعوى إلى المحكمة بناء على طلب المدعى بصحيفة تودع قلم كتاب المحكمة ما لم ينص القانون على غير ذلك . ويجب أن تشمل صحيفة الدعوى على البيانات الآتية : 1 - أسم المدعى ولقبه ومهنته أو وظيفته وموطنه واسم من يمثله ولقبه ومهنته أو وظيفته وصفته وموطنه . 2 - أسم المدعى عليه ولقبه ومهنته أو وظيفته وموطنه فإن لم يكن موطنه معلوما فآخر موطن كان له. 3 - تاريخ تقديم الصحيفة. 4 - المحكمة المرفوعة أمامها الدعوى. 5 - بيان موطن مختار للمدعى فى البلدة التى بها مقر المحكمة أن لم يكن له موطن فيها . 6 - وقائع الدعوى وطلبات المدعى وأسانيدها ."}, {"number": "64", "chapter": "الباب الثانى", "text": "يكون حضور الخصوم فى الدعاوى الجزئية التى ترفع ابتداء فى اليوم والساعة المحددين بصحيفة افتتاح الدعوى أمام مجلس صلح يتولى التوفيق بين الخصوم وذلك فيما عدا الدعاوى التى لا يجوز فيها الصلح والدعاوى المستعجلة ومنازعات التنفيذ والطلبات الخاصة بأوامر الأداء . ويشكل مجلس الصلح المشار إليه برياسة أحد وكلاء النائب العام ، ويعقد جلساته فى مقر محكمة المواد الجزئية المختصة بنظر النزاع ، وعليه أن ينتهى من مهمته فى مدى ثلاثين يوما لا يجوز مدها الا باتفاق الطرفين ولملة لا تجاوز ثلاثين يوما اخرى ، فإذا تم الصلح فى هذا الأجل ، اعد بذلك محضرا تكون له قوة السندات واجبة التنفيذ ، وإذا لم يتم الصلح فى الأجل المذكور احال الدعوى إلى المحكمة لنظرها فى جلسة يحددها . ويصدر بتنظيم هذا المجلس وبيان الإجراءات التى تتبع أمامه قرار من رئيس الجمهورية ويحدد وزير العدل بقرار منه المحاكم الجزئية التى تشكل مجالس الصلح بدائرتها . وإذا عرضت الدعاوى المشار إليها فى الفقرة الأولى على محكمة شكل مجلس صلح بدائرتها قبل عرضها على هذا المجلس وجب على المحكمة احالتها إليه ."}, {"number": "65", "chapter": "الباب الثانى", "text": "- \" يقيد قلم كتاب المحكمة صحيفة الدعوى إذا كانت مصحوبة بما يلى : 1 - ما يدل على سداد الرسوم المقررة قانونا أو إعفاء المدعى منها . 2 - صور من الصحيفة بقدر عدد المدعى عليهم فضلا عن صورتين لقلم الكتاب . 3 - أصول المستندات المؤيدة للدعوى أو صور منها تحت مسئولية المدعى ، وما يركن إليه من أدلة لاثبات دعواه . 4 - مذكرة شارحة للدعوى أو إقرار باشتمال صحيفة الدعوى على شرح كامل لها ، وصور من المذكرة أو الإقرار بقدر عدد المدعى عليهم . قلم الكتاب إثبات تاريخ طلب القيد فى جميع الاحوال ، وإذا رأى قلم الكتاب قيد صحيفة الدعوى - لعدم استيفاء المستندات والأوراق المبينة بالفقرة الاولى - قام بعرض الأمر على قاضى الأمور الوقتية ليفصل فيه فورا ، اما بتكليف الكتاب بقيد الدعوى ، او بتكليف طالبا قيدها باستيفاء ما نقص ، وذلك بعد سماع اقواله ورأى قلم الكتاب . فإذا قيدت صحيفة الدعوى تنفيذا لأمر القاضى - اعتبرت مقيدة من تاريخ تقديم طلب القيد . ويرسل قلم الكتاب إلى المدعى عليه خلال ثلاثة أيام كتابة موصى عليه بعلم الوصول ، مرفقا به صور من صحيفة الدعوى ومن المذكرة الشارحة أو الإقرار ، يخطره فيه بقيد الدعوى واسم المدعى وطلباته والجلسة المحددة لنظرها ، ويدعوه للاطلاع على ملف الدعوى وتقديم مستنداته ومذكرة بدفاعه . وعلى المدعى عليه ، فى جميع الدعاوى عدا المستعجلة والتى انقصى ميعاد الحضور فيها ، أن يودع قلم الكتاب مذكرة بدفاعه ويرفق بها جميع مستنداته ، أو صورا منها تحت مسئوليته قبل الجلسة المحددة لنظر الدعوى بثلاثة أيام على الأقل . ولا تقبل دعوى صحة التعاقد على حق من الحقوق العينية العقارية الا إذا اشهرت صحيفتها ."}, {"number": "66", "chapter": "الباب الثانى", "text": "ميعاد الحضور خمسة عشر يوما أمام المحكمة الإبتدائية ومحكمة الإستئناف وثمانية أيام أمام محاكم المواد الجزئية ، ويجوز فى حالة الضرورة نقص هذين الميعادين إلى ثلاثة أيام وإلى اربع وعشرين ساعة على التوالى . وميعاد الحضور فى الدعاوى المستعجلة أربع وعشرون ساعة ، ويجوز فى حالة الضرورة نقص هذا الميعاد وجعله من ساعة إلى ساعة بشرط أن يحصل الإعلان للخصم نفسه الا إذا كانت من الدعاوى البحرية . ويكون نقص المواعيد فى الأحوال المتقدمة بإذن من قاضى الأمور الوقتية وتعلن صورته للخصم مع صحيفة الدعوى ."}, {"number": "67", "chapter": "الباب الثانى", "text": "يقيد قلم الكتاب الدعوى فى يوم تقديم الصحيفة فى السجل الخاص بذلك بعد أن يثبت فى حضور المدعى أو من يمثله تاريخ الجلسة المحددة لنظرها فى أصل الصحيفة وصورها . وعلى قلم الكتاب فى اليوم التالى على أكثر أن يسلم أصل الصحيفة وصورها إلى قلم المحضرين لإعلانها ورد الأصل إليه . ومع ذلك يجوز فى غير دعاوى الاسترداد واشكالات التنفيذ ، أن يسلم للمدعى - متى طلب ذلك - اصل الصحيفة وصورها ليتولى تقديمها إلى قلم المحضرين لإعلانها ورد الأصل إلى المدعى ليقوم بإعادته إلى قلم الكتاب."}, {"number": "68", "chapter": "الباب الثانى", "text": "على قلم المحضرين أن يقوم بإعلان صحيفة الدعوى خلال ثلاثين يوما على الأكثر من تاريخ تسليمها به الا إذا كان قد حدد لنظر الدعوى جلسة تقع فى اثناء هذا الميعاد فعندئذ يجب أن يتم الإعلان قبل الجلسة ، وذلك كله مع مراعاة ميعاد الحضور . وتحكم المحكمة المرفوعة إليها الدعوى على من تسبب من العاملين بقلم الكتاب أو المحضرين بإهماله فى تأخير الإعلان بغرامة لا تقل عن عشرون جنيهات ولا تجاوز مائتى جنيه لا يكون الحكم بها قابلا لأى طعن. ولا تعتبر الخصومة منعقدة فى الدعوى الا بإعلان صحيفتها إلى المدعى عليه ما لم يحضر بالجلسة."}, {"number": "69", "chapter": "الباب الثانى", "text": "لا يترتب على عدم مراعاة الميعاد المقرر فى المادة السابقة بطلان اعلان صحيفة الدعوى . كذلك لا يترتب البطلان على عدم مراعاة مواعيد الحضور وذلك سير اخ بحق المعلن إليه فى التأجيل لاستكمال الميعاد ."}, {"number": "70", "chapter": "الباب الثانى", "text": "يجوز بناء على طلب المدعى عليه ، إعتبار الدعوى كان لم تكن إذا لم يتم تكليف المدعى عليه بالحضور فى خلال ثلاثة اشهر من تاريخ تقديم الصحيفة إلى قلم الكتاب ، وكان ذلك راجعا إلى فعل المدعى."}, {"number": "71", "chapter": "الباب الثانى", "text": "إذا ترك المدعى الخصومة أو تصالح مع خصمه فى الجلسة الأولى لنظر الدعوى وقبل بدء المرافعة فلا يستحق على الدعوى إلا ربع الرسم المسدد . وإذا انتهى النزاع صلحا أمام مجلس الصلح المشار إليه فى المادة 64 يرد كامل الرسم المسدد ."}, {"number": "72", "chapter": "الفصل الأول", "text": "فى اليوم المعين لنظر الدعوى يحضر الخصوم بأنفسهم أو يحضر عنهم من يوكلونه من المحامين وللمحكمة أن تقبل فى النيابة عنهم من يوكلونه من أزواجهم أو أقاربهم أو أصهارهم إلى الدرجة الثالثة."}, {"number": "73", "chapter": "الفصل الأول", "text": "يجب على الوكيل أن يقرر حضوره عن موكله وان يثبت وكالته عنه وفقا لأحكام قانون المحاماة وللمحكمة عند الضرورة أن ترضى للوكيل فى إثبات وكالته فى ميعاد تحدده على أن يتم ذلك فى جلسة المرافعة على أكثر ."}, {"number": "74", "chapter": "الفصل الأول", "text": "بمجرد صدور التوكيل من أحد الخصوم يكون موطن وكيله معتبرا فى إعلان الأوراق اللازمة لسير الدعوى فى درجة التقاضى الموكل هو فيها . وعلى الخصم الذى لا يكون له وكيل بالبلد الذى به مقر المحكمة أن يتخذ له موطنا فيه ."}, {"number": "75", "chapter": "الفصل الأول", "text": "التوكيل بالخصومة يخول الوكيل سلطة القيام بالأعمال والإجراءات اللازمة لرفع الدعوى ومتابعتها أو الدفاع فيها ، وأتخاذ الإجراءات التحفظية إلى أن يصدر الحكم فى موضوعها فى درجة التقاضى التى وكل فيها وإعلان هذا الحكم وقبض الرسوم والمصاريف . وذلك بغير إخلال بما أوجب فيه القانون تفويضا خاص . وكل قيد يرد فى سند التوكيل على خلاف ما تقدم لا يحتج به على الخصم الآخر."}, {"number": "76", "chapter": "الفصل الأول", "text": "لا يصح بغير تفويض خاص الإقرار بالحق المدعى به ولا التنازل عنه ولا الصلح ولا التحكيم فيه ولا قبول اليمين ولا توجيهها ولا ودها ولا ترك الخصومة ولا التنازل عن الحكم أو عن طريق من طرق الطعن فيه ولا رفع الحجز ولا ترك التأمينات مع بقاء الدين ولا الإدعاء بالتزوير ولا رد القاضى ولا مخاصمته ولا رد الخبير ولا العرض الفعلى ولا قبوله ولا أى تصرف آخر يوجب القانون فيه تفويضا خاصا ."}, {"number": "77", "chapter": "الفصل الأول", "text": "إذا تعدد الوكلاء جاز لاحدهم الانفراد بالعمل فى القضية ما لم يكن ممنوعا من ذلك بنص فى التوكيل ."}, {"number": "78", "chapter": "الفصل الأول", "text": "يجوز للوكيل أن ينيب غيره من المحامين أن لم يكن ممنوعا من الإنابة صراحة فى التوكيل ."}, {"number": "79", "chapter": "الفصل الأول", "text": "كل ما يقرره الوكيل بحضور موكله يكون بمثابة ما يقرره الموكل نفسه الا إذا نفاه اثناء نظر القضية فى الجلسة."}, {"number": "80", "chapter": "الفصل الأول", "text": "لا يحول اعتزال الوكيل أو عزله دود الإجراءات فى مواجهته الا إذا أعلن الخصم بتعيين بدله أو بعزم الموكل على مباشرة الدعوى بنفسه . ولا يجوز للوكيل أن يعتزل الوكالة فى وقت غير لائق."}, {"number": "81", "chapter": "الفصل الأول", "text": "لا يجوز لأحد القضاة ولا للنائب العام ولا لأحد من وكلائه ولا لأحد من العاملين بالمحاكم أن يكون وكيلا عن الخصوم فى الحضور أو المرافعة سواء أكان بالمشافهة أم بالكتابة أم بالإفتاء ولو كانت الدعوى مقامة أمام محكمة غير المحكمة التابع هو لها والا كان العمل باطلا . ولكن يجوز لهم ذلك عمن يمثلونهم قانونا وعن زوجاتهم وأصولهم وفروعهم إلى الدرجة الثانية ."}, {"number": "82", "chapter": "الفصل الثانى", "text": "إذا لم يحضر المدعى ولا المدعى عليه حكمت المحكمة فى الدعوى إذا كانت صالحة للحكم فيها والا قررت شطبها فإذا انقضى ستون يوما ولم يطلب أحد الخصوم السير فيها . أو لم يحضر الطرفان بعد السير فيها اعتبرت كان لم تكن . وتحكم المحكمة فى الدعوى إذا غاب المدعى أو المدعون أو بعضهم فى الجلسة الأولى وحضر المدعى عليه."}, {"number": "83", "chapter": "الفصل الثانى", "text": "إذا حضر المدعى عليه فى أية جلسة أو أودع مذكرة دفاعه اعتبرت الخصومة حضورية فى حقه ولو تخلف بعد ذلك. ولا يجوز للمدعى أن يبدى فى الجلسة التى تخلف فيها خصمه طلبات جديدة أو أن يعدل أو يزيد أو ينقص فى الطلبات الأولى كما لا يجوز للمدعى عليه أن يطلب فى غيبة المدعى الحكم عليه بطلب ما ."}, {"number": "84", "chapter": "الفصل الثانى", "text": "إذا تخلف المدعى عليه وحله فى الجلسة الأولى وكانت صحيفة الدعوى قد أعلنت لشخصه حكمت المحكمة فى الدعوى فإذا لم يكن قد أعلن لشخصه كان على المحكمة فى غير الدعاوى المستعجلة تأجيل نظر القضية إلى جلسة تالية يعلن المدعى بها الخصم الغائب ويعتبر الحكم فى الدعوى فى الحالتين حكما حضوريا . فإذا تعدد المدعى عليهم وكان البعض قد أعلن لشخصه والبعض الآخر لم يعلن لشخصه وتغيبوا جميعا أو تغيب من لم يعلن لشخصه وجب على المحكمة فى غير الدعاوى المستعجلة تأجيل نظر الدعوى إلى جلسة تالية يعلن المدعى بها من لم يعلن لشخصه من الغائبين . ويعتبر الحكم فى الدعوى حكما حضوريا فى حق المدعى عليهم جميعا . وفى تطبيق أحكام هذه المادة ، يعتبر إعلان الشخص الاعتبارى العام أو أن من فى مركز إدارته أو فى هيئة قضايا الدولة ، بحسب الأحوال إعلانا لشخصه ."}, {"number": "85", "chapter": "الفصل الثانى", "text": "\" إذا تبينت المحكمة عند غياب المدعى عليه بطلان اعلانه بالصحيفة وجب عليها تأجيل القضية إلى جلسة تالية يعلن لها اعلانا صحيحا بواسطة خصمه . فإذا كان البطلان راجعا إلى فعل المدعى وجب تغريمه بغرامة لا تقل عن خمسين جنيها ولا تجاوز خمسمائة جنيه \" ."}, {"number": "86", "chapter": "الفصل الثانى", "text": "إذا حضر الخصم الغائب قبل انتهاء الجلسة اعتبر كل حكم صدر عليه فيها كان لم يكن ."}, {"number": "87", "chapter": "الباب الرابع", "text": "للنيابة العامة رفع الدعوى فى الحالات التى ينص عليها القانون ويكون لها فى هذه الحالات ما للخصوم من حقوق ."}, {"number": "88", "chapter": "الباب الرابع", "text": "فيما عدا الدعاوى المستعجلة يجب على النيابة العامة أن تتدخل فى الحالات الآتية والا كان الحكم باطلا : 1 - الدعاوى التى يجوز لها أن ترفعها بنفسها. 2 - الطعون والطلبات أمام محكمة النقض وتحكمة تنازع الاختصاص. 3 - كل حالة اخرى ينص القانون على وجوب تدخلها فيها."}, {"number": "89", "chapter": "الباب الرابع", "text": "فيما عدا الدعاوى المستعجلة يجوز للنيابة العامة أن تتدخل فى الحالات الآتية : 1 - الدعاوى الخاصة بعديمى الأهلية وناقصيها والغائبين والمفقودين . 2 - الدعاوى المتعلقة بالأوقاف الخيرية والهبات والوصايا المرصدة للبر . 3 - عدم الاختصاص لانتفاء ولاية جهة القضاء . 4 - دعاوى رد القضاة وأعضاء النيابة ومخاصمتهم . 5 - الصلح الواقى من الإفلاس . 6 - الدعاوى التى ترى النيابة العامة التدخل فيها لتعلقها بالنظام العام أو الآداب . 7 - كل حالة أخرى ينص القانون على جواز تدخلها فيها."}, {"number": "90", "chapter": "الباب الرابع", "text": "يجوز للمحكمة فى أية حالة تكون عليها الدعوى أن تأمر بإرسال ملف القضية إلى النيابة العامة إذا عرضت فيها مسألة تتعلق بالنظام العام أو الآداب ويكون تدخل النيابة العامة فى هذه الحالة وجوبيا ."}, {"number": "91", "chapter": "الباب الرابع", "text": "تعتبر النيابة ممثلة فى الدعوى متى قدمت مذكرة برأيها فيها ولا يتعين حضورها الا إذا نص القانون على ذلك . وفى جميع الأحوال لا يتعين حضور النيابة عند النطق بالحكم ."}, {"number": "92", "chapter": "الباب الرابع", "text": "فى جميع الأحوال التى ينص فيها القانون على تدخل النيابة العامة ، يجب على قلم كتاب المحكمة أخبار النيابة كتابة بمجرد قيد الدعوى . فإذا عرضت اثناء نظر الدعوى مسألة مما تتدخل فيها النيابة ، فيكون إخطارها بناء على أمر من المحكمة ."}, {"number": "93", "chapter": "الباب الرابع", "text": "تمنح النيابة بناء على طلبها ميعاد سبعة أيام على الأقل لتقديم مذكرة بأقوالها . ويبدأ هذا الميعاد من اليوم الذى يرسل لها فيه ملف القضية مشتملا على مستندات الخصوم ومذكراتهم ."}, {"number": "94", "chapter": "الباب الرابع", "text": "يكون تدخل النيابة فى أية حالة كانت عليها الدعوى قبل اقفال باب المرافعة فيها ."}, {"number": "95", "chapter": "الباب الرابع", "text": "فى جميع الدعاوى التى تكون فيها النيابة طرفا منضما لا يجوز للخصوم بعد تقديم أقوالهم وطلباتهم أن يطلبوا الكلام ولا أن يقدموا مذكرات جديدة وإنما يجوز لهم أن يقدموا للمحكمة بيانا كتابيا لتصحيح الوقائع التى ذكرتها النيابة . ومع ذلك يجوز للمحكمة فى الأحوال الاستثنائية التى يرى فيها قبول مستندات جديدة أو مذكرات تكميلية أن تأذن فى تقديمها وفى إعادة المرافعة وتكون النيابة آخر من يتكلم ."}, {"number": "96", "chapter": "الباب الرابع", "text": "للنيابة العامة الطعن فى الحكم فى الأحوال لتى يوجب القانون أو يجيز تدخلها فيها إذا خالف الحكم قاعدة من قواعد النظام العام أو إذا نص القانون على ذلك."}, {"number": "97", "chapter": "الفصل الاول", "text": "\" تجرى المرافعة فى أول جلسة ، وإذا قدم المدعى أو المدعى عليه فى هذه الجلسة مستندات كان فى إمكانه تقديمه فى الميعاد المقرر فى المادة 65 من هذا القانون قبلته المحكمة إذا لم يترتب على ذلك تأجيل نظر الدعوى ، اما إذا ترتب على تقديمه تأجيل نظرها ورأت المحكمة قبوله تحقيقا للعدالة حكمت عليه بغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه على أن يكون التأجيل لمرة واحدة ولا تجاوز مدته أسبوعين \" . ومع ذلك يجوز لكل من المدعى والمدعى عليه ان يقدم مستندا ردا على دفاع خصمه أو طلباته العارضة."}, {"number": "98", "chapter": "الفصل الاول", "text": "لا يجوز تأجيل الدعوى أكثر من مرة بسبب واحد يرجع إلى أحد الخصوم على أن لا تجاوز فترة التأجيل ثلاثة أسابيع ."}, {"number": "99", "chapter": "الفصل الاول", "text": "تحكم المحكمة على من يتخلف من العاملين بها أو من الخصوم عن إيداع المستندات أو عن القيام بأى إجراء من إجراءات المرافعات فى الميعاد الذى حددته له المحكمة بغرامة لا تقل عن أربعون جنيها ولا تجاوز ربعمائة جنيه ويكون ذلك بقرار يثبت فى محضر الجلسة له ما للأحكام من قوة تنفيذية .ولا يقبل الطعن فيه بأى طريق ولكن للمحكمة أن تقبل المحكوم عدم الغرامة كلها أو بعضها إذا أبدى عنصرا مقبولا. \" ويجوز للمحكمة بدلا من الحكم على المدعى بالغرامة أن تحكم بوقف الدعوى لمدة لا تجاوز شهرا بعد سماع أقوال المدعى عليه . وإذا مضت مدة الوقف ولم يطلب المدعى السير فى دعواه خلال الخمسة عشر يوم التالية لانتهائها ، أو لم ينفذ ما أمرت به المحكمة حكمت المحكمة باعتبار الدعوى كأن لم تكن ."}, {"number": "100", "chapter": "الفصل الاول", "text": "تنفيذ أحكام الغرامات يكون بعد أخبار المحكوم عليه ككاب مسجل مصحوب بعلم الوصول من قلم الكتاب"}, {"number": "101", "chapter": "الفصل الثانى", "text": "تكون المرافعة علنية الا إذا رأت المحكمة من تلقاء نفسها او بناء على طلب أحد الخصوم أجراءها سرا محافظة على النظام العام أو مراعاة للآداب أو لحرمة الأسرة."}, {"number": "102", "chapter": "الفصل الثانى", "text": "يجب الاستماع إلى أقوال الخصوم المرافعة ، ولا تجوز مقاطعتهم الا إذا خرجوا عن موضوع الدعوى أو مقتضيات الدفاع ويكون المدعى عليه آخر من يتكلم ."}, {"number": "103", "chapter": "الفصل الثانى", "text": "للخصوم أن يطلبوا إلى المحكمة فى أية حالة تكون عليها الدعوى إثبات ما اتفقوا عليه فى محضر الجلسة ويوقع منهم أو من وكلائهم فإذا كانوا قد كتبوا ما اتفقوا عليه الحق الاتفاق المكتوب بمحضر الجلسة وأثبت محتواه فيه. ويكون لمحضر الجلسة فى الحالين قوة السند التنفيذى وتعطى صورته وفقا للقواعد المقررة لإعطاء صور الاحكام. ومع ذلك إذا كان طلب الخصوم يتضمن إثبات اتفاقهم على صحة التعاقد على حق من الحقوق العينية العقارية فلا يحكم بإلحاق ما اتفقوا عليه كتابة أو شفاهه بمحضر الجلسة الا إذا تم شهر الاتفاق المكتوب أو صورة رسمية من محضر الجلسة الذى اثبت فيه الاتفاق."}, {"number": "104", "chapter": "الفصل الثانى", "text": "\" ضبط الجلسة واداراتها منوطان برئيسها ، وله فى سبيل ذلك ومع مراعاة أحكام قانون المحاماة أن يخرج من قاعه الجلسة من يخل بنظامها ، فإن لم يمتثل وتمادى كان للمحكمة أن تحكم على الفور بحبسه أربعا وعشرين ساعة أو بتغريمه مائة جنيها ويكون حكمها بذلك نهائيا \" . فإذا كان الإخلال قد وقع ممن يؤدون وظيفة فى المحكمة كان لها أن توقع اثناء انعقاد الجلسة ما لرئيس المصلحة توقيعه من الجزاءات التأديبية . وللمحكمة إلى ما قبل انتهاء الجلسة أن ترجع عن الحكم الذى تصدره بناء على الفقرتين السابقتين ."}, {"number": "105", "chapter": "الفصل الثانى", "text": "للمحكمة ولو من تلقاء نفسها أن تأمر بمحو العبارات الجارحة أو المخالفة للآداب أو النظام العام من أية ورقة من أوراق المرافعات أو المذكرات."}, {"number": "106", "chapter": "الفصل الثانى", "text": "مع مراعاة أحكام قانون المحاماة يأمر رئيس الجلسة بكتابة محضر عن كل جريمة تقع اثناء انعقادها وبما يرى اتخاذه من إجراءات التحقيق ثم يأمر بإحالة الأوراق إلى النيابة لإجراء ما يلزم فيها . فإذا كانت الجريمة التى وقعت جناية أو جنحة كان له إذا اقتضت الحال أن يأمر بالقبض على من وقعت منه ."}, {"number": "107", "chapter": "الفصل الثانى", "text": "مع مراعاة أحكام قانون المحاماة للمحكمة أن محاكم من تقع منه اثناء انعقادها جنحة تعد على هيئتها أو على أحد أعضائها أو أحد العاملين بالمحكمة وتحكم عليه فورا بالعقوبة . وللمحكمة أيضا أن تحاكم من شهد زورا بالجلسة وتحكم عليه بالعقوبة المقررة لشهادة الزور . ويكون حكم المحكمة فى هذه الأحوال نافذا ولو حصل إستئناف ."}, {"number": "108", "chapter": "الفصل الأول", "text": "الدفع بعدم الاختصاص المحل والدفع بإحالة لدعوى إلى محكمة اخرى لقيام ذات النزاع أمامها أو للارتباط والدفع بالبطلان وسائر الدفوع المتعلقة بالإجراءات يجب ابداؤها معا قبل إبداء أى طلب أو دفاع فى الدعوى أو دفع بعدم القبول والا سقط الحق فيما لم يبد منها . ويسقط حق الطاعن فى هذه الدفوع إذا لم يبدها فى صحيفة لطعن . ويحكم فى هذه الدفوع على استقلال ما لم تأمر المحكمة لضمها إلى الموضوع وعندئذ تبين المحكمة ما حكمت به فى كل منها على حدة . ويجب إبداء جميع الوجوه التى يبنى عليها الدفع المتعلق بالإجراءات معا والا سقط الحق فيما لم يبد منها ."}, {"number": "109", "chapter": "الفصل الأول", "text": "الدفع بعدم اختصاص المحكمة لانتفاء ولايتها أو بسبب نوع الدعوى أو قيمتها تحكم به المحكمة من تلقاء نفسها. ويجوز الدفع به فى أية حالة كانت عليها الدعوى"}, {"number": "110", "chapter": "الفصل الأول", "text": "على المحكمة إذا قضت بعدم اختصاصها أن تأمر بإحالة الدعوى بحالتها إلى المحكمة المختصة ، وكان عدم الاختصاص متعلقة بالولاية ويجوز لها عندئذ تحكم بغرامة لا تجاوز ربعمائة جنيها . وتلتزم المحكمة المحال إليها الدعوى بنظرها ."}, {"number": "111", "chapter": "الفصل الأول", "text": "إذا اتفق الخصوم على التقاضى أمام محكمه غير المحكمة المرفوعة إليها الدعوى جاز للمحكمة أن تأمر بإحالة الدعوى إلى المحكمة التى اتفقوا عليها ."}, {"number": "112", "chapter": "الفصل الأول", "text": "إذا رفع النزاع ذاته إلى محكمتين وجب إبداء الدفع بالإحالة أمام المحكمة التى رفع إليها النزاع أخيرا للحكم فيه . وإذا دفع بالإحالة للارتباط جاز إبداء الدفع أمام أى من الحكمتين . وتلتزم المحكمة المحال إليها الدعوى بنظرها"}, {"number": "113", "chapter": "الفصل الأول", "text": "كلما حكمت المحكمة فى الأحوال المتقدمة بالإحالة كان عليها أن تحدد للخصوم الجلسة التى يحضرون فيها أمام المحكمة التى أحيلت إليها الدعوى وعلى قلم الكتاب أخبار الغائبين من الخصوم بذلك بكتاب مسجل مصحوب بعلم الوصول ."}, {"number": "114", "chapter": "الفصل الأول", "text": "بطلان صحف الدعاوى وإعلانها وبطلان أوراق التكليف بالحضور الناشئ عن عيب فى الإعلان أو فى بيان المحكمة أو فى تاريخ الجلسة يزول بحضور المعلن إليه فى الجلسة أو بإيداع مذكرة بدفاعه ."}, {"number": "115", "chapter": "الفصل الأول", "text": "الدفع بعدم قبول الدعوى يجوز ابداؤه فى أية حالة تكون عليها . \" وإذا رأت المحكمة أن الدفع بعدم قبول الدعوى لعيب فى صفة المدعى عليه قائم على أساس ، اجلت الدعوى لإعلان ذى الصفة ويجوز للمحكمة فى هذه الحالة الحكم على المدعى بغرامة لا تقل عن خمسين جنيها ولا جاوز مائتى جنيه . وإذا تعلق الأمر باحدى الوزارات أو الهيئات العامة أو د مصلحة من المصالح أو كشخص اعتبارى عام أو خاص فيكفى فى تحديد السنة أن يذكر أسم الجهة المدعى عليها فى صحيفة الدعوى."}, {"number": "116", "chapter": "الفصل الأول", "text": "الدفع بعدم جواز نظر الدعوى لسبق الفصل فيها تقضى به المحكمة من تلقاء نفسها."}, {"number": "117", "chapter": "الفصل الثانى", "text": "للخصم أن يدخل فى الدعوى من كان يصح اختصامه فيها عند رفعها ، ويكون ذلك بالإجراءات المعتادة لرفع الدعوى قبل يوم الجلسة مع مراعاة حكم المادة 66."}, {"number": "118", "chapter": "الفصل الثانى", "text": "للمحكمة ولو من تلقاء نفسها أن تأمر بإدخال من ترى إدخاله لمصلحة العدالة أو لإظهار الحقيقة . وتعين المحكمة ميعادا لا يجاوز ثلاثة أسابيع لحضور من تأمر بإدخاله ومن يقوم من الخصوم بإدخاله ويكون ذلك بالإجراءات المعتادة لرفع الدعوى."}, {"number": "119", "chapter": "الفصل الثانى", "text": "يجب على المحكمة فى المواد المدنية اجابة الخصم إلى طلب تأجيل الدعوى لإدخال ضامن فيها إذا كان الخصم قد كلف ضامنه الحضور خلال ثمانية أيام من تاريخ إعلانه بالدعوى أو قيام السبب الموجب للضمان أو إذا كانت الثمانية الأيام المذكورة لم تنقض قبل الجلسة المحددة لنظر الدعوى . وفيما عدا هذه الحالة يكون التأجيل لإدخال الضامن جوازيا للمحكمة ويراعى فى تقدير الأجل مواعيد الحضور ويكون إدخال الخصم للضامن بالإجراءات المعتاد لرفع الدعوى ."}, {"number": "120", "chapter": "الفصل الثانى", "text": "يقضى فى طلب الضمان وفى الدعوى الأصلية بحكم واحد كلما أمكن ذلك والا فصلت المحكمة فى طلب الضمان بعد الحكم فى الدعوى الأصلية ."}, {"number": "121", "chapter": "الفصل الثانى", "text": "إذا أمرت المحكمة بضم طلب الضمان إلى الدعوى الأصلية يكون الحكم الصادر على الضامن عند الاقتضاء حكما للمدعى الأصلى ولو لم يكن قد وجه إليه طلبات ويجوز لطالب الضمان أن يطلب إخراجه من الدعوى إذا لم يكن مطالبا بإلتزام شخصى ."}, {"number": "122", "chapter": "الفصل الثانى", "text": "إذا رأت المحكمة أن طلب الضمان لا أساس له جاز لها الحكم على مدعى الضمان بالتعويضات الناشئة عن تأخير الفصل فى الدعوى الأصلية."}, {"number": "123", "chapter": "الفصل الثالث", "text": "تقدم الطلبات العارضة من المسى أو من المدعى عليه إلى المحكمة بالإجراءات المعتادة لرفع الدعوى قبل يوم الجلسة أو كطلب يقدم شفاها فى الجلسة فى حضور الخصم ويثبت فى محضرها ولا تقل الطلبات العارضة بعد اقفال باب المرافعة ."}, {"number": "124", "chapter": "الفصل الثالث", "text": "للمدعى أن يقدم من الطلبات العارضة : 1 - ما يتضمن تصحيح الطلب الأصلى أو تعديل موضوعه لمواجهة ظروف طرأت أو تبينت بعد رفع الدعوى . 2 - ما يكون مكملا للطلب الأصلى أو مترتبا عليه أو متصلا به اتصالا لا يقبل التجزئة . 3 - ما يتضمن إضافة أو تغييرا فى سبب الدعوى مع بقاء موضوع الطلب الأصلى على حاله. 4 - طلب الأمر بإجراء تحفظى أو وقتى . 5 - ما تأذن المحكمة بتقديمه مما يكون مرتبطا بالطلب الأصلى ."}, {"number": "125", "chapter": "الفصل الثالث", "text": "للمدعى عليه أن يقدم من الطلبات العارضة : 1 - طلب المقاصة القضائية وطلب الحكم له بالتعويضات عن ضرر لحقه من الدعوى الأصلية أو من أجراء فيها . 2 - أى طلب يترتب على أجابته الا يحكم للمدعى بطلباته كلها او بعضها أو أن يحكم له بها مقيدة بقيد لمصلحة المدعى عليه . 3 - أى طلب يكون متصلا بالدعوى الأصلية اتصالا لا يقبل التجزئة. 4 - ما تأذن المحكمة بتقديمه مما يكون مرتبطا بالدعوى الأصلية."}, {"number": "126", "chapter": "الفصل الثالث", "text": "يجوز لكل ذى مصلحة أن يتدخل فى الدعوى منضما لأحد الخصوم أو طالبا الحكم لنفسه بطلب مرتبط بالدعوى . ويكون التدخل بالإجراءات المعتادة لرفع الدعوى قبل يوم الجلسة أو بطلب يقدم شفاها فى الجلسة فى حضورهم ويثبت فى محضرها ولا يقبل التدخل بعد اقفال باب لمرافعة ."}, {"number": "126 مكرر", "chapter": "الفصل الثالث", "text": "لا يقبل الطلب العارض أو طلب لتدخل إذا كان محله صحة التعاقد على حق من الحقوق العينية العقارية الا إذا تم شهر صحيفة هذا الطلب أو صورة رسمية من محضر الجلسة الذى اثبت فيه ."}, {"number": "127", "chapter": "الفصل الثالث", "text": "تحكم المحكمة فى كل نزاع يتعلق بقبول الطلبات العارضة أو التدخل ولا يترتب على الطلبات العارضة أو التدخل إرجاء الحكم فى الدعوى الأصلية متى كانت صالحة للحكم . وتحكم المحكمة فى موضوع الطلبات العارضة أو فى طلبات التدخل مع الدعوى الأصلية كلما أمكن ذلك والا استبقت الطلب العارض أو طلب التدخل للحكم فيه بعد تحقيقه ."}, {"number": "128", "chapter": "الفصل الأول وقف الخصومة", "text": "يجوز وقف الدعوى لمنا . على اتفاق الخصوم على عدم السير فيها مدة لا تزيد على ثلاثة اشهر من تاريخ إقرار المحكمة لاتفاقهم ولكن لا يكون لهذا الوقف أثر فى . أى ميعاد حتمى يكون القانون قد حدده لإجراء ما . وإذا لم تعجل الدعوى فى ثمانية الأيام التالية لنهاية لأجل اعتبر المدعى تاركا دعواه والمستأنف تاركا استئذانه"}, {"number": "129", "chapter": "الفصل الأول وقف الخصومة", "text": "فى غير الأحوال التى نص فيهما القانون على وقف الدعوى وجويا أو جوازا يكون للمحكمة أن تأمر بوقفها كلما رأت تعليق حكمها فى موضوعها على الفصل فى مسألة اخرى يتوقف عليها الحكم . وبمجرد زوال سبب الوقف يكون للخصوم تعجيل الدعوى."}, {"number": "130", "chapter": "الفصل الثانى", "text": "ينقطع سير الخصومة حكم القانون بوفاة أحد الخصوم ، أو بفقده أهلية الخصومة ، أو بزوال صفة من كان يباشر الخصومة عنه النائب ، الا إذا كانت الدعوى قد تهيأت للحكم فى موضوعها . ومع ذلك إذا طلب أحد الخصوم اجلا لإعلان من يقوم مقام الخصم الذى محقق فى شأنه سبب الانقطاع ، وجب على المحكمة - قبل أن تقضى بانقطاع سير الخصومة - أن تحلفه بالإعلان خلال أجل تحدده له ، فإذا لم يقم به خلال هذا الأجل دون عذر ، قضت المحكمة بانقطاع سير الخصومة منذ تحقق سببه . ولا تنقطع الخصومة بوفاة وكيل الدعوى ولا بزوال وكالته بالتنحى أو بالعزل وللمحكمة أن تمنح اجلا مناسبا للخصم الذى توفى وكيله أو انقضت وكالته إذا كان قد بادر فعين له وكيلا جديدا خلال الخمسة عشر يوما التالية لانقضاء الوكالة الأولى ."}, {"number": "131", "chapter": "الفصل الثانى", "text": "تعتبر الدعوى مهيأة للحكم فى موضوعها متى كان الخصوم قد ابلوا أقوالهم وطلباتهم الختامية فى جلسة المرافعة قبل الوفاة ، أو فقد أهلية الخصومة ، أو زوال الصفة ."}, {"number": "132", "chapter": "الفصل الثانى", "text": "يترتب على انقطاع الخصومة وقف جميع مواعيد المرافعات التى كانت جارية فى حق الخصوم وبطلان جميع الإجراءات التى تحمل اثناء الانقطاع ."}, {"number": "133", "chapter": "الفصل الثانى", "text": "تستأنف الدعوى سيرها بصحيفة تعلن إلى من يقوم مقام الخصم الذى توفى أو فقد أهليته للخصومة أو زالت صفته ، بناء على طلب الطرف الأخر ، بصحيفة تعلن إلى هذا الطرف بناء على طلب أولئك . و كذلك تستأنف الدعوى سيرها إذا حضر الجلسة التى كانت محددة لنظرها و أرث المتوفى ، أو من يقوم مقام من فقد أهلية الخصومة ، أو مقام من زالت عنه الصفة و باشر السير فيها"}, {"number": "134", "chapter": "الفصل الثانى", "text": "لكل ذى مصلحة من الخصوم فى حالة عدم السير فى الدعوى بفعل المدعى أو أمتناعه أن يطلب الحكم بسقوط الخصومة متى أنقضت ستة شهور من أخر إجراء صحيح من إجراءات التقاضى ."}, {"number": "135", "chapter": "الفصل الثانى", "text": "لا تبدأ مدة سقوط الخصومة فى حالات الإنقطاع إلا من اليوم الذى قام فيه من يطلب الحكم بسقوط الخصومة بإعلان ورثة خصمه الذى توفى ، أو من قام مقام من فقد أهليته للخصومة أو مقام من زالت صفته بوجود الدعوى بينه و بين خصمه الأصلى"}, {"number": "136", "chapter": "الفصل الثانى", "text": "يقدم طلب الحكم بسقوط الخصومة إلى المحكمة المقامة أمامها الدعوى المطلوب أسقاط الخصومة فيها بالأوضاع المعتادة لرفع الدعوى . و يجوز التمسك بسقوط الخصومة فى صورة دفع إذا عجل المدعى دعواه بعد إنقضاء المدة المنصوص عليها فى المادة 134 من هذا القانون ."}, {"number": "137", "chapter": "الفصل الثانى", "text": "يترتب على الحكم بسقوط الخصومة سقوط الأحكام الصادرة فيها بإجراء الأثبات ، و إلغاء جميع إجراءات الخصومة بما فى ذلك رفع الدعاوى و لكنه لا يسقط الحق فى أصل الدعوى و لا فى الأحكام القطعية الصادرة فيها و لا فى الإجراءات السابقة لتلك الأحكام أو الإقرارات الصادرة من الخصوم أو الإيمان التى حلفوها . على أن هذا السقوط لا يمنع الخصوم من أن يتمسكوا بإجراءات التحقيق و أعمال الخبرة التى تمت ما لم تكن باطلة فى ذاتها"}, {"number": "138", "chapter": "الفصل الثانى", "text": "متى حكم بسقوط الخصومة فى الأستئناف اعتبرالحكم المستأنف انتهائياً فى جميع الأحوال . و متى حكم بسقوط الخصومة فى الألتماس إعادة النظر قبل الحكم بقبول الألتماس سقط طلب الألتماس نفسه ، أما بعد الحكم بقبول الألتماس فتسرى القواعد السالفة الخاصة بالأستئناف أو بأول درجة حسب الأحوال"}, {"number": "139", "chapter": "الفصل الثانى", "text": "تسرى المدة المقررة لسقوط الخصومة فى حق جميع الأشخاص و لو كانوا عديمى الأهلية أو ناقصيها ."}, {"number": "140", "chapter": "الفصل الثانى", "text": "فى جميع الأحوال تنقضى الخصومة بمضى سنتين على أخر إجراء صحيح فيها و مع ذلك لا يسرى حكم الفقرة السابقة على الطعن بطريق النقض ."}, {"number": "141", "chapter": "الفصل الثانى", "text": "يكون ترك الخصومة بإعلان من التارك لخصمه على يد محضر أو ببيان صريح فى مذكرة موقعة من التارك أو من وكيله مع إطلاع خصمه عليها أو بأبدائه شفوياً فى الجلسة و إثباته فى المحضر ."}, {"number": "142", "chapter": "الفصل الثانى", "text": "لا يتم الترك بعد إبداء المدعى عليه طلباته إلا بقبوله و مع ذلك لا يلتفت لأعتراضه على الترك إذا كان قد دفع بعدم أختصاص المحكمة ، أو بإحالة القضية إلى محكمة أخرى ، أو ببطلان صحيفة الدعوى أو طلب غير ذلك مما يكون القصد منه منع المحكمة من المضى فى سماع الدعوى ."}, {"number": "143", "chapter": "الفصل الثانى", "text": "يترتب على ترك إلغاء جميع إجراءات الخصومة بما فى ذلك رفع الدعوى و الحكم على التارك بالمصاريف ، و لكن لا يمس ذلك الحق المرفوعة به الدعوى ."}, {"number": "144", "chapter": "الفصل الثانى", "text": "إذا نزل الخصم مع قيام الخصومة عن إجراء أو ورقة المرافعات صراحة أو ضمناً أعتبر الإجراء أو الورقة كأن لم يكن ."}, {"number": "145", "chapter": "الفصل الثانى", "text": "الـنزول عـن الحكـم يستتبـع الـنزول عـن الحـق الثـابـت بــه ."}, {"number": "146", "chapter": "الباب الثامن", "text": "-- يكون القاضى غير صالح لنظر الدعوى ممنوعاً من سماعها و لو لم يرد أحد من الخصوم فى الأحوال الآتية : 1 - إذا كان قريباً أو صهراً لأحد الخصوم إلى الدرجة الرابعة . 2 - إذا كان له أو لزوجته خصومة قائمة مع أحد الخصوم فى الدعوى و مع زوجته . 3 - إذا كان وكيلاً لأحد الخصوم فى أحد أعماله الخصوصية وصياً عليه أو مظنونة وراثته له ، أو كانت له صلة قرابة أو مصاهرة للدرجة الرابعة بوصى أحد الخصوم أو بالقيم عليه أو بأحد أعضاء مجلس إدارة الشركة المختصمة أو بأحد مديريها و كان لهذا العضو أو المدير مصلحة شخصية فى الدعوى . 4 - إذا كان له أو لزوجته أو لأحد أقاربه أو أصهاره على عمود النسب أو لمن يكون هو وكيلاً عنه أو وصياً أو قيماً عليه مصلحة الدعوى القائمة . 5 - إذا كان قد أفتى أو ترافع عن أحد الخصوم فى الدعوى أو كتب فيها و لو قبل أشتغاله بالقضاء ، أو كان قد سبق نظرها قاضيها أو خبيراً أو محكماً ، أو كان قد أدى شهادة فيها ."}, {"number": "146", "chapter": "الباب الثامن", "text": "-- يكون القاضى غير صالح لنظر الدعوى ممنوعاً من سماعها و لو لم يرد أحد من الخصوم فى الأحوال الآتية : 1 - إذا كان قريباً أو صهراً لأحد الخصوم إلى الدرجة الرابعة . 2 - إذا كان له أو لزوجته خصومة قائمة مع أحد الخصوم فى الدعوى و مع زوجته . 3 - إذا كان وكيلاً لأحد الخصوم فى أحد أعماله الخصوصية وصياً عليه أو مظنونة وراثته له ، أو كانت له صلة قرابة أو مصاهرة للدرجة الرابعة بوصى أحد الخصوم أو بالقيم عليه أو بأحد أعضاء مجلس إدارة الشركة المختصمة أو بأحد مديريها و كان لهذا العضو أو المدير مصلحة شخصية فى الدعوى . 4 - إذا كان له أو لزوجته أو لأحد أقاربه أو أصهاره على عمود النسب أو لمن يكون هو وكيلاً عنه أو وصياً أو قيماً عليه مصلحة الدعوى القائمة . 5 - إذا كان قد أفتى أو ترافع عن أحد الخصوم فى الدعوى أو كتب فيها و لو قبل أشتغاله بالقضاء ، أو كان قد سبق نظرها قاضيها أو خبيراً أو محكماً ، أو كان قد أدى شهادة فيها ."}, {"number": "147", "chapter": "الباب الثامن", "text": "يقع باطلاً عمل القاضى أو قضاؤه فى الأحوال المنتظمة الذكر و لو تم بأتفاق الخصوم . و إذا وقع هذا البطلان فى حكم صدر من محكمة النقض جاز للخصم أن يطلب منها إلغاء الحكم و إعادة نظر الطعن أمام دائرة أخرى ."}, {"number": "148", "chapter": "الباب الثامن", "text": "يجوز رد القاضى لأحد الأسباب الآتية : 1 - إذا كان له او لزوجته دعوى مماثلة للدعوى التى ينظرها ، أو إذا وجدت لأحدهما خصومة مع أحد الخصوم ، أو لزوجته بعد قيام الدعوى المطروحة على القاضى ما لم تكن هذه الدعوى قد أقيمت بقصد رده عن نظر الدعوى المطروحة . 2 - إذا كان لمطلقته التى له منها ولد أو لأحد أقاربه أو أصهاره على عمود النسب خصومة قائمة أمام القضاء مع أحد الخصوم فى الدعوى أو مع زوجته ما لك تكن هذه الخصومة قد أقيمت بعد قيام الدعوى المطروحة على القاضى بقصد رده . 3 - إذا كان أحد الخصوم خادماً له ، أو كان هو قد اعتاد مؤاكلة أحد الخصوم أو مساكنته . أو كان تلقى منه هدية قبيل رفع الدعوى أو بعده . 4 -إذا كان بينه و بين أحد الخصوم عداوة أو مودة يرجح معها عدم استطاعته الحكم بغير ميل"}, {"number": "149", "chapter": "الباب الثامن", "text": "على القاضى فى الأحوال المذكورة فى المادة السابقة أن يخبر المحكمة فى غرفة المشورة أو رئيس المحكمة الأبتدائية -على حسب الأحوال - بسبب الرد القائم به و ذلك للإذن له بالتنحى . و يثبت هذا كله فى محضر خاص يحفظ بالمحكمة ."}, {"number": "150", "chapter": "الباب الثامن", "text": "يجوز للقاضى فى غير أحوال الرد المذكورة ، إذا أستشعر الحرج من نظر الدعوى لأى سبب ، أن يعرض أمر تنحيه على المحكمة فى غرفة المشورة ، أو على رئيس المحكمة للنظر فى إقراراه على التنحى ."}, {"number": "151", "chapter": "الباب الثامن", "text": "يجب تقديم طلب الرد قبل تقديم أى دفع أو دفاع و إلا سقط الحق فيه . فإذا كان الرد فى حق قاض منتدب لأجراء من إجراءات الأثبات فيقدم الطلب خلال ثلاثة أيام من يوم ندبه إذا كان قرارالندب صادراً فى حضور طالب الرد ، فإن كان صادراً فى غيبته تبدأ الأيام الثلاثة من يوم إعلانه به . و يجوز طلب الرد إذا حدثت أسبابه بعد المواعيد المقررة ، أو إذا أثبت طالب الرد أنه لم يعلم إلا بعد مضى تلك المواعيد ."}, {"number": "152", "chapter": "الباب الثامن", "text": "لا يقبل طلب الرد بعد إقفال باب المرافعة فى الدعوى ، أو ممن سبق له طلب رد نفس القاضى فى ذات الدعوى و لا يترتب على طلبات الرد فى الحالتين وقف الدعوى المنصوص عليه فى المادة 162 من هذا القانون . و يسقط حق الخصم فى طلب الرد إذا لم يحصل التقرير به قبل إقفال باب المرافعة فى طلب رد سابق مقدم فى الدعوى أخطر بالجلسة المحددة لنظره متى كانت أسباب الرد قائمة حتى إقفال باب المرافعة ."}, {"number": "153", "chapter": "الباب الثامن", "text": "يحصل الرد بتقرير يكتب بقلم كتاب المحكمة التى يتبعها القاضى المطلوب رده ، يوقعه الطالب نفسه ، أو وكيله المفوض فيه بتوكيل خاص يرفق بالتقرير ،و يجب أن يشتمل الرد على أسبابه و أن يرفق به ما قد يوجد من أوراق أو مستندات مؤيدة له . \" وعلى طالب الرد أن يودع عند التقرير بالرد ثلاثمائة جنيه على سبيل الكفالة ، ويجب على قلم الكتاب تحديد جلسة فى موعد لا يجاوز سبعة أيام من تاريخ تقديم الطلب ويوقع طالب الرد بما يفيد علمه بالجلسة \" . . و تختص بنظر طلب رد المستشار بمحكمة الأستئناف ، أو بمحكمة النقض ، دائرة بمحكمة الأستئناف أو بمحكمة النقض ، حسب الأحوال ، غير الدائرة التى يكون المطلوب رده عضوا فيها . ."}, {"number": "154", "chapter": "الباب الثامن", "text": "إذا كان الرد واقعاً فى حق قاضى جلس أول مرة لسماع الدعوى بحضور الخصوم جاز الرد بمذكرة تسلم لكاتب الجلسة . و على طالب الرد تأييد الطلب بقلم الكتاب فى اليوم نفسه أو فى اليوم التالى و إلا سقط الحق فيه"}, {"number": "155", "chapter": "الباب الثامن", "text": "يجب على قلم كتاب المحكمة رفع تقرير الرد إلى رئيسها مرفقاً به بيان بما قدم من طلبات رد فى الدعوى و ما تم فيها ، و ذلك كله خلال أربع و عشرين ساعة ، و على الرئيس أن يطلع القاضى المطلوب رده على التقرير فوراً ، و أن يرسل صورة منه إلى النيابة ."}, {"number": "156", "chapter": "الباب الثامن", "text": "على القاضى المطلوب رده أن يجيب بالكتابة على وقائع الرد و أسبابه خلال الأربعة أيام التالية لأطلاعه . و إذا كانت الأسباب تصلح قانوناً للرد و لم يجب عليها القاضى المطلوب رده فى الميعاد المحدد ، أو أعترف بها فى أجابته ، أصدر رئيس المحكمة أمراً بتنحيه ."}, {"number": "157", "chapter": "الباب الثامن", "text": "فى غير الأحوال المنصوص عليها فى المادة السابقة تتخذ الإجراءات التالية : (1) إذا كان المطلوب رده أحد قضاة المحاكم الجزئية ، أو الأبتدائية قام رئيس المحكمة الأبتدائية بإرسال الأوراق إلى رئيس محكمة الأستئناف المختصة فى اليوم التالى لأنقضاء الميعاد ، و يتولى رئيس المحكمة المختصة بنظر الرد وفقاً لأحكام المادة 153 تعيين الدائرة التى تنظر الطلب و تحديد الجلسة التى ينظر فيها .(ب) يقوم قلم الكتاب المختص بإخطار باقى الخصوم فى الدعوى الأصلية بالجلسة المحددة لنظر طلب الرد ، و ذلك لتقديم ما قد يكون لديهم من طلبات رد طبقاً لنص الفقرة الأخيرة من المادة 152 . (ج) \" تقوم الدائرة التى تنظر طلب الرد بتحقيق الطلب فى غرفة المشورة ثم تحكم فيه فى موعد لا يجاوز شهرا من تاريخ التقرير ، وذلك بعد سماع أقوال طالب الرد ، وملاحظات القاضى عند الاقتضاء أو إذا طلب ذلك ، وممثل النيابة إذا تدخلت فى الدعوى . لا يجوز فى تحقيق طلب الرد استجواب القاضى ، ولا توجيه اليمين إليه \" (د) يتلى الحكم الصادر فى طلب الرد مع أسبابه فى جلسة علنية ، و لا يقبل طلب رد أحد مستشارى المحكمة التى تنظر طلب الرد ، و لا يترتب على تقديمه وقف نظر طلب الرد . و فى جميع الأحوال لا يجوز الطعن فى الحكم الصادر برفض طلب الرد لا مع الطعن فى الحكم الصادر فى الدعوى الأصلية ."}, {"number": "158", "chapter": "الباب الثامن", "text": "إذا كان القاضى المطلوب رده منتدباً من محكمة أخرى أمر رئيس المحكمة بإرسال تقرير الرد و مستنداته إلى المحكمة التابع هو لها لتطلعه عليها و تتلقى جوابه عنها ثم تعيدها إلى المحكمة الأولى لتتبع فى شأنه الأحكام المقررة فى المواد السابقة ."}, {"number": "158 مكررا", "chapter": "الباب الثامن", "text": "ً -- على رئيس المحكمة فى حالة تقديم طلبات رد قبل إقفال باب المرافعة فى طلب رد سابق ، أن يحيل هذه الطلبات إلى الدائرة ذاتها المنظور أمامها ذلك الطلب لتقضى فيها جميعاً بحكم واحد و دون التقيد بأحكام المادتين 156 ، 158 ."}, {"number": "159", "chapter": "الباب الثامن", "text": "- \" تحكم المحكمة عند رفض طلب الرد ، أو سقوط الحق فبه ، أو عدم قبوله ، أو إثبات التنازل عنه ، على طالب الرد بغرامة لا تقل عن ربعمائة ولا تزيد على ربعمائة جنيه ومصادرة الكفالة ، وفى حالة ما إذا كان الرد مبينا على الوجه الرابع من المادة 148 من هذا القانون يجوز ابلاغ الغرامة إلى ستةآلاف جنيه \" . فى كل الأحوال تتعدد الغرامة بتعدد القضاة المطلوب ردهم . و يعفى طالب الرد من الغرامة فى حالة التنازل عن الطلب فى الجلسة الأولى أو إذا كان التنازل بسبب تنحى القاضى المطلوب رده أو نقله أو إنتهاء خدمته ."}, {"number": "160", "chapter": "الباب الثامن", "text": "ملغاة بالقانون رقم 23 لسنة 1992 ."}, {"number": "161", "chapter": "الباب الثامن", "text": "ملغاة بالقانون رقم 23 لسنة 1992 ."}, {"number": "162", "chapter": "الباب الثامن", "text": "يترتب على تقديم طلب الرد وقف الدعوى الأصلية إلى أن يحكم فيه ، و مع ذلك يجوز لرئيس المحكمة ندب قاضى بدلا من طلب رده ."}, {"number": "162 مكررا", "chapter": "الباب الثامن", "text": "ً -- إذا قضى برفض طلب الرد أو سقوط الحق فيه أو عدم قبوله أو بإثبات التنازل عنه ، لا يترتب على تقديم أى طلب رد أخر وقف الدعوى الأصلية ومع ذلك يجوز للمحكمة التى تنظر طلب الرد أن تأمر بناء على طلب أحد ذوى الشأن بوقف السير فى الدعوى الأصلية ، و يسرى فى هذه الحالة حكم ال مادة السابقة ."}, {"number": "163", "chapter": "الباب الثامن", "text": "تتبع القواعد و الإجراءات المتقدمة عند رد عضو النيابة إذا كانت طرفاً منضماً لسبب من الأسباب المنصوص عليها فى المادتين 146 ، 148 ."}, {"number": "164", "chapter": "الباب الثامن", "text": "لا يجوز طلب رد جميع قضاة أو مستشارى المحكمة أو بعضهم بحيث لا يبقى من عددهم من يكفى للحكم فى الدعوى الأصلية أو طلب الرد ."}, {"number": "165", "chapter": "الباب الثامن", "text": "إذا رفع القاضى دعوى تعويض على طالب الرد أو قدم ضده بلاغاً لجهة الأختصاص زالت صلاحيته للحكم فى الدعوى و تعين عليه أن يتنحى عن نظرها ."}, {"number": "166", "chapter": "الفصل الأول", "text": "تكون المداولة فى الأحكام سراً بين القضاة مجتمعين ."}, {"number": "167", "chapter": "الفصل الأول", "text": "لايجوز أن يشترك فى المداولة غير القضاة الذين سمعوا المرافعة و إلا كان الحكم باطلاً ."}, {"number": "168", "chapter": "الفصل الأول", "text": "لا يجوز للمحكمة أثناء المداولة أن تسمع أحد الخصوم أو وكيله إلا بحضور خصمه ،أو أن تقبل أوراقاً أو مذكرات من أحد الخصوم دون إطلاع الخصم الأخر عليها و إلا كان العمل باطلاً ."}, {"number": "169", "chapter": "الفصل الأول", "text": "تصدر الأحكام بأغلبية الآراء فإذا لم تتوفرالأغلبية و تشعبت الآراء لأكثرمن رأيين وجب أن ينضم الفريق الأقل عدداً أو الفريق الذى يضم أحدث القضاة لأحد الرأيين الصادرين من الفريق الأكثر عدداً و ذلك بعد أخذ الآراء مرة ثانية ."}, {"number": "170", "chapter": "الفصل الأول", "text": "يجب أن يحضرالقضاة الذين أشتركوا فى المداولة تلاوة الحكم ، فإذا حصل لأحدهم مانع وجب أن يوقع مسودة الحكم ."}, {"number": "171", "chapter": "الفصل الأول", "text": "يجوز للمحكمة عقب إنتهاء المرافعة أن تنطق بالحكم فىالجلسة و يجوز لها تأجيل إصداره إلى جلسة أخرى قريبة تحددها . و إذا صرحت المحكمة بتقديم مذكرات خلال فترة حجز الدعوى للحكم ، وجب عليها تحديد ميعاد للمدعى عليه لتبادلها ، بإعلانها ، أو بإيداعها قلم الكتاب من أصل و صور بعدد الخصوم أو وكلائهم ، بحسب الأحوال ، و صورة إضافية ترد للمودع بعد التأشيرعليها من قلم الكتاب بأستلام الأصل و الصور و تاريخ ذلك .و يقوم قلم الكتاب بتسليم الصور لذوى الشأن بعد توقيعهم على الأصل بالأستلام ، و لا يجوز سحب المستندات من الملف إذا طعن فى الحكم ، أو قبل إنقضاء مواعيد الطعن ، ما لم يأمر رئيس المحكمة بغيرذلك ."}, {"number": "172", "chapter": "الفصل الأول", "text": "إذا أقتضت الحال تأجيل إصدار الحكم مرة ثانية صرحت المحكمة بذلك فى الجلسة مع تعيين اليوم الذى يكون فيه النطق به و بيان أسباب التأجيل فى ورقة الجلسة و فى المحضر، و لا يجوز لها تأجيل إصدار الحكم بعدئذ إلا مرة واحدة ."}, {"number": "173", "chapter": "الفصل الأول", "text": "لايجوز فتح باب المرافعة بعد تحديد جلسة النطق بالحكم إلا بقرار تصرح به المحكمة فى الجلسة و لا يكون ذلك إلا لأسباب جديدة تبين فى ورقة الجلسة و فى المحضر ."}, {"number": "174", "chapter": "الفصل الأول", "text": "ينطق القاضى بالحكم بتلاوة منطوقة أو بتلاوة منطوقة مع أسبابه و يكون النطق به علانية و إلا كان الحكم باطلاً ."}, {"number": "174 مكررا", "chapter": "الفصل الأول", "text": "ً -- يعتبرالنطق بالأحكام التى تصدر أثناء سيرالدعوى و لا تنتهى بها الخصومة و قررات فتح باب المرافعة فيها إعلاناً للخصوم الذين حضروا إحدى الجلسات أو قدموا مذكرة بدفاعهم و ذلك ما لم ينقطع تسلسل الجلسات لأى سبب من الأسباب بعد حضورهم أو تقديمهم للمذكرة ، فعندئذ يقوم قلم الكتاب بإعلان الخصوم بالحكم أو القرار المذكور بكتاب مسجل مصحوب بعلم الوصول ."}, {"number": "175", "chapter": "الفصل الأول", "text": "يجب فى جميع الأحوال أن تودع مسودة الحكم المشتملة على اسبابه موقعة من الرئيس و من القضاة عند النطق بالحكم و إلا كان الحكم باطلاً ، و يكون المتسبب فى البطلان ملزماً بالتعويضات إن كان لها وجه ."}, {"number": "176", "chapter": "الفصل الأول", "text": "يجب أن تشتمل الأحكام على الأسباب التى بنيت عليها و إلا كانت باطلة ."}, {"number": "177", "chapter": "الفصل الأول", "text": "تحفظ مسودة الحكم المشتملة على منطوقه و اسبابه بالملف و لا تعطى منها صورة ، و لكن يجوز للخصوم الأطلاع عليها إلى حين إتمام نسخة الحكم الأصلية ."}, {"number": "178", "chapter": "الفصل الأول", "text": "يجب أن يبين فى الحكم المحكمة التى أصدرته و تاريخ إصداره و مكانه و ما إذا كان صادراً فى مادة تجارية أو مسألة مستعجلة أو أسماء القضاة الذين سمعوا المرافعة ، و أشتركوا فى الحكم و حضروا تلاوته و عضو النيابة الذى أبدى رأيه فى القضية إن كان ، و أسماء الخصوم و ألقابهم و صفاتهم و موطن كل منهم و حضورهم و غيابهم . كما يجب أن يشتمل الحكم على عرض مجمل لوقائع الدعوى ثم طلبات الخصوم ، و خلاصة موجزة لدفوعهم و دفاعهم الجوهرى ، و رأى النيابة ثم تذكربعد ذلك أسباب الحكم و منطوقه . و القصور فى أسباب الحكم الواقعية و النقص أو الخطأ الجسيم فى أسماء الخصوم و صفاتهم ، و كذا عدم بيان أسماء القضاة الذين أصدروا الحكم يترتب عليه بطلان الحكم ."}, {"number": "179", "chapter": "الفصل الأول", "text": "يوقع رئيس الجلسة و كاتبها نسخة الحكم الأصلية المشتملة على وقائع الدعوى و الأسباب و المنطوق و تحفظ فى ملف الدعوى و ذلك خلال أربع و عشرين ساعة من إيداع المسودة فى القضايا المستعجلة و سبعة أيام فى القضايا الأخرى و إلا كان المتسبب فى التأخير ملزماً بالتعويضات"}, {"number": "180", "chapter": "الفصل الأول", "text": "يصوغ إعطاء صورة بسيطة من نسخة الحكم الأصلية لمن يطلبها و لو لم يكن له شأن فى الدعوى و ذلك بعد دفع الرسم المستحق ."}, {"number": "181", "chapter": "الفصل الأول", "text": "تختم صورة الحكم التى يكون التنفيذ بموجبها بخاتم المحكمة و يوقعها الكاتب بعد أن يزيلها بالصيغة التنفيذية و لا تسلم إلا للخصم الذى تعود عليه منفعة من تنفيذ الحكم و لاتسلم له إلا إذا كان الحكم جائز تنفيذه ."}, {"number": "182", "chapter": "الفصل الأول", "text": "إذا امتنع قلم الكتاب من إعطاء الصورة التنفيذية الأولى جاز لطالبها أن يقدم عريضة بشكواه إلى قاضى الأمور الوقتية بالمحكمة التى أصدرت الحكم ليصدر أمره فيها طبقاً للإجراءات المقررة فى باب الأوامر على العرائض ."}, {"number": "183", "chapter": "الفصل الأول", "text": "لا يجوز تسليم صورة تنفيذية ثانية لذات الخصم إلا فى حالة ضياع الصورة الأولى و تحكم المحكمة التى أصدرت الحكم فى المنازعات المتعلقة بتسليم الصورة التنفيذية الثانية عند ضياع الأولى بناء على صحيفة تعلن من أحد الخصوم إلى خصمه الأخر ."}, {"number": "184", "chapter": "الفصل الثانى", "text": "يجب على المحكمة عند إصدار الحكم الذى تنتهى الخصومة أمامها أن تحكم من تلقاء نفسها فى مصاريف الدعوى و يحكم بمصاريف الدعوى على الخصم المحكوم عليه فيها و يدخل فى حساب المصاريف مقابل أتعاب المحاماة . و إذا تعدد المحكوم عليهم جاز الحكم بقسمة المصاريف بينهم بالتساوى أو بنسبة مصلحة كل منهم فى الدعوى على حساب ما تقدره المحكمة و لا يلزمون بالتضامن فى المصاريف إلا إذا كانوا متضامنين فى أصل التزامهم المقضى فيه ."}, {"number": "185", "chapter": "الفصل الثانى", "text": "للمحكمة أن تحكم بإلزام الخصم الذى كسب الدعوى بالمصاريف كلها أو بعضها إذا كان الحق مسلماً به من المحكوم عليه ، أو إذا كان المحكوم له قد تسبب فى إنفاق مصاريف لا فائدة فيها أو كان قد ترك خصمه على جهل بما كان فى يده من المستندات القاطعة فى الدعوى أو بمضمون تلك المستندات ."}, {"number": "186", "chapter": "الفصل الثانى", "text": "إذا أخفق كل من الخصمين فى بعض الطلبات جاز الحكم بأن يتحمل كل خصم ما دفعه من المصاريف أو بتقسيم المصاريف بينهما على حسب ما تقدره المحكمة فى حكمها ، كما يجوز لها أن تحكم بها جميعاً على أحدهما ."}, {"number": "187", "chapter": "الفصل الثانى", "text": "يحكم بمصاريف التدخل على المتدخل إذا كانت له طلبات مستقلة و حكم بعدم قبول تدخله أو برفض طلباته ."}, {"number": "188", "chapter": "الفصل الثانى", "text": "يجوز للمحكمة أن تحكم بالتعويضات مقابل النفقات الناشئة عن دعوى أو دفاع قصد بهما الكيد . و مع عدم الإخلال بحكم الفقرة السابقة يجوز للمحكمة عند إصدار الحكم الفاصل فى الموضوع أن تحكم بغرامة لا تقل عن أربعين جنيها و لا تجاوز ربعمائة جنيه على الخصم الذى يتخذ إجراء أو يبدى طلباً أو دفعاً أو دفاعاً بسوء نية ."}, {"number": "189", "chapter": "الفصل الثانى", "text": "تقدر مصاريف الدعوى فى الحكم إن أمكن و إلا قدرها رئيس الهيئة التى أصدرت الحكم بأمر على عريضة يقدمها المحكوم له و يعلم هذا الأمر للمحكوم عليه بها . و لا يسرى على هذا الأمر السقوط المقرر فى المادة 200 ."}, {"number": "190", "chapter": "الفصل الثانى", "text": "يجوز لكل من الخصوم أن يتظلم من الأمر المشار إليه فى المادة السابقة و يحصل التظلم أمام المحضر عند إعلان أمر التقدير أو بتقرير فى قلم كتاب المحكمة التى أصدرت الحكم و ذلك خلال ثمانية الأيام التالية لإعلان الأمر ، و يحدد المحضر أو قلم الكتاب على حسب الأحوال اليوم الذى ينظر فيه التظلم أمام المحكمة فى غرفة المشورة و يعلن الخصوم بذلك قبل اليوم المحدد بثلاث ايام ."}, {"number": "191", "chapter": "الفصل الثالث", "text": "تتولى المحكمة تصحيح ما يقع من حكمها من أخطاء مادية بحتة كتابية أو حسابية و ذلك بقرار تصدره من تلقاء نفسها أو بناء على طلب أحدى الخصوم من غير مرافعة و يجرى كاتب المحكمة هذا التصحيح على نسخة الحكم الأصلية و يوقعه هو و رئيس الجلسة . و يجوز الطعن فى القرار الصادر بالتصحيح إذا تجاوزت المحكمة فى حقها المنصوص عليه فى الفقرة السابقة و ذلك بطرق الطعن الجائزة فى الحكم موضوع التصحيح أما القرار الذى يصدر برفض التصحيح فلا يجوز الطعن فيه على أستقلال ."}, {"number": "192", "chapter": "الفصل الثالث", "text": "يجوز للخصوم أن يطلبوا إلى المحكمة التى أصدرت الحكم تفسير ما وقع فى منطوقه من غموض أو إبهام و يقدم الطلب بالأوضاع المعتادة لرفع الدعوى . و يعتبر الحكم الصادر بالتفسير متمما من كل الوجوه للحكم الذى يفسره ، و يسرى عليه ما يسرى على هذا الحكم من القواعد الخاصة بطرق الطعن العادية و الغير عادية ."}, {"number": "193", "chapter": "الفصل الثالث", "text": "إذا أغفلت المحكمة فى بعض الطلبات الموضوعية جاز لصاحب الشأن أن يعلن خصمه بصحيفة للحضور أمامها لنظر هذا الطلب و الحكم فيه ."}, {"number": "194", "chapter": "الباب العاشر", "text": "فى الأحوال التى ينص فيها القانون على أن يكون للخصم وجه فى استصدار أمر ، يقدم عريضة بطلبه إلى قاضى الأمور الوقتية بالمحكمة المختصة ، أو إلى رئيس الهيئة التى تنظر الدعوى ، و تكون هذه العريضة من نسختين متطابقتين و مشتملة على وقائع الطلب و أسانيده ، و تعين موطن مختار للطالب فى البلدة التى بها مقر المحكمة و تشفع بها المستندات المؤيدة لها . ."}, {"number": "195", "chapter": "الباب العاشر", "text": "يجب على القاضى أن يصدر أمره بالكتابة على أحدى نسختى العريضة فى اليوم التالى لتقديمها على الأكثر . و لا يلزم ذكر الأسباب التى بنى عليها الأمر إلا إذا كان مخالفاً لأمر سبق صدوره فعندئذ يجب ذكر الأسباب التى أقتضت إصدار الأمر الجديد و إلا كان باطلاً ."}, {"number": "196", "chapter": "الباب العاشر", "text": "يجب على قلم الكتاب تسليم الطالب النسخة الثانية من عريضته مكتوباً عليها صورة الأمر و ذلك فى اليوم التالى لصدوره على الأكثر ."}, {"number": "197", "chapter": "الباب العاشر", "text": "لذوى الشأن ، الحق فى التظلم إلى المحكمة المختصة ، إلا إذا نص القانون على خلاف ذلك . - \" ويكون التظلم بالإجراءات المعتادة لرفع الدعوى أمام محكمة خلال عشره ايام من تاريخ صدور الأمر بالرفض أو من تاريخ البدء فى تنفيذ الأمر أو إعلانه بحسب الاحوال . وتحكم المحكمة فيه بإصدار الأمر أو بتأييد لأمر الصادر أو بتعديله أو بالغائه \" . و يجب أن يكون التظلم مسبباً و إلا كان باطلاً ."}, {"number": "198", "chapter": "الباب العاشر", "text": "يجوز رفع التظلم تبعاً للدعوى الأصلية فى أية حال تكون عليها أو أثناء المرافعة بالجلسة ."}, {"number": "199", "chapter": "الباب العاشر", "text": "لذوى الشأن ، بدلاً من التظلم للمحكمة المختصة الحق فى التظلم منه لنفس القاضى الآمر ، بالإجراءات المعتادة لرفع الدعوى ، و لا يمنع من ذلك قيام الدعوى الأصلية أمام المحكمة . و يحكم القاضى فى التظلم بتأييد الأمر أو بتعديله أو بإلغائه و يكون حكمه قابلاً لطرق الطعن المقررة للأحكام ."}, {"number": "200", "chapter": "الباب العاشر", "text": "يسقط الأمر الصادر على عريضة إذا لم يقدم للتنفيذ خلال ثلاثين يوماً من تاريخ صدوره و لا يمنع هذا السقوط من استصدار أمر جديد ."}, {"number": "201", "chapter": "الباب الحادى عشر", "text": "أستثناء من القواعد العامة فى رفع الدعاوى ابتداء تتبع الأحكام الواردة فى المواد التالية ، إذا كان حق الدائن ثابتاً بالكتابة و حال الأداء ، و كان كل ما يطالب به ديناً من النقود معين المقدار ، أو منقولاً معيناً بذاته أو بنوعه أو مقداره . و تتبع هذه الأحكام إذا كان صاحب الحق دائناً بورقة تجارية و أقتصر رجوعه على الساحب أو المحرر أو القابل أو الضامن الإحتياطى لأحدهم . أما إذا أراد الرجوع على غير هؤلاء وجب عليه أتباع القواعد العامة فى رفع الدعوى ."}, {"number": "202", "chapter": "الباب الحادى عشر", "text": "على الدائن أن يكلف المدين أولا بالوفاء بميعاد خمسة أيام على الأقل ثم يستصدر أمراً بالأداء من قاضى محكمة المواد الجزئية التابع لها موطن المدين أو رئيس الدائرة بالمحكمة الأبتدائية حسب الأحوال و ذلك ما لم يقبل المدين أختصاص محكمة أخرى بالفصل فى النزاع و يكفى فى التكليف بالوفاء أن يحصل بكتاب مسجل مع علم الوصول و يقوم برتستو عدم الدفع مقام هذا التكليف ."}, {"number": "203", "chapter": "الباب الحادى عشر", "text": "يصدر الأمر بالأداء بناء على عريضة يقدمها الدائن أو وكيله يرفق بها سند الدين و ما يثبت حصول التكليف بوفائه و يبقى هذا السند فى قلم الكتاب إلى أن يمضى ميعاد التظلم . و يجب أن تحرر العريضة من نسختين متطابقتين و أن تشتمل على وقائع الطلب و أسانيده و أسم المدين كاملاً و محل اقامته و ترفق بها المستندات المؤيدة لها و أن يعين الطالب فيها موطناً مختاراً له فى دائرة اختصاص المحكمة فإن كان مقيماً خارج هذه الدائرة تعين عليه أتخاذ موطن مختار فى البلدة التى بها مقر المحكمة . و يجب أن يصدر الأمر على أحدى نسختي العريضة خلال ثلاثة أيام على الأكثر من تقديمها و أن يبين المبلغ الواجب أداؤه من أصل و فوائد أو ما أمر بأدائه من منقول حسب الأحوال ، و كذا المصاريف ."}, {"number": "204", "chapter": "الباب الحادى عشر", "text": "إذا رأى القاضى ألا يجيب الطالب إلى كل طلباته كان عليه أن يمتنع عن إصدار الأمر و أن يحدد جلسة لنظر الدعوى أمام المحكمة مع تكليف الطالب بإعلان خصمه إليها . و لا يعتبر رفض شمول الأمر بالنفاذ رفضاً لبعض الطلبات فى حكم الفقرة السابقة ."}, {"number": "205", "chapter": "الباب الحادى عشر", "text": "يعلن المدين لشخصه أو فى موطنه بالعريضة و بالأمر الصادر ضده بالأداء . و تعتبر العريضة و الأمر الصادر عليها بالأداء كأن لم تكن إذا لم يتم إعلانها للمدين خلال ثلاثة أشهر من تاريخ صدور الأمر ."}, {"number": "206", "chapter": "الباب الحادى عشر", "text": "يجوز للمدين التظلم من الأمر خلال عشرة أيام من تاريخ إعلانه إليه و يحصل التظلم أمام محكمة المواد الجزئية أو أمام المحكمة الأبتدائية حسب الأحوال و تراعى فيه الأوضاع المقررة لصحيفة أفتتاح الدعوى .و يجب أن يكون التظلم مسبباً و إلا كان باطلاً . و يبدأ ميعاد أستئناف الأمر إن كان قابلاً له من تاريخ فوات ميعاد التظلم منه أو من تاريخ أعتبار التظلم كأن لم يكن . و يسقط الحق فى التظلم من الأمر إذا طعن فيه مباشرة بالأستئناف ."}, {"number": "207", "chapter": "الباب الحادى عشر", "text": "يعتبر المتظلم فى حكم المدعى و تراعى عند نظر التظلم القواعد و الإجراءات المتبعة أمام محكمة الدرجة الأولى . و إذا تخلف المتظلم عن الحضورفى الجلسة الأولى لنظر التظلم تحكم المحكمة من تلقاء نفسها بأعتبار التظلم كأن لم يكن ."}, {"number": "208", "chapter": "الباب الحادى عشر", "text": "لايقبل من الدائن طلب الأمر بالأداء إلا إذا كانت عريضته مصحوبة بما يدل على أداء الرسم كاملاً . على أنه فى أحوال الحجز المنصوص عليها فى الفقرة الأولى من المادة 210 يحصل من الدائن ربع الرسم عند طلب توقيع الحجز و الباقى عند طلب الأمر بالأداء ."}, {"number": "209", "chapter": "الباب الحادى عشر", "text": "تسرى على أمر الأداء و على الحكم الصادر فىالتظلم منه الأحكام الخاصة بالنفاذ المعجل حسب الأحول التى بينها القانون ."}, {"number": "210", "chapter": "الباب الحادى عشر", "text": "إذا أراد الدائن فى حكم المادة 201حجز ما يكون لمدينه لدى الغير و فى الأحوال التى يجوز فيها للدائن استصدار أمر من القاضى بالحجز التحفظى يصدرأمر الحجز من القاضى المختص بإصدار الأمر بالأداء و ذلك استثناء من أحكام المواد 275 ،319 ، 327 . و على الدائن خلال ثمانية الأيام التالية لتوقيع الحجز أن يقدم طلب الأداء و صحة إجراءات الحجز إلى القاضى المذكور ، و إلا اعتبر الحجز كأن لم يكن . و فى حالة التظلم من أمر الحجز لسبب يتصل بأصل الحق يمتنع إصدار الأمر بالأداء و تحدد جلسة لنظر الدعوى وفقاً للمادة 204 ."}, {"number": "211", "chapter": "الفصل الأول", "text": "لا يجوز الطعن فى الأحكام إلا من المحكوم عليه و لا يجوز ممن قبل الحكم أو ممن قضى له بكل طلباته ما لم ينص القانون على غير ذلك ."}, {"number": "212", "chapter": "الفصل الأول", "text": "لا يجوز الطعن فى الأحكام التى تصدر أثناء سير الدعوى و لا تنتهى بها الخصومة إلا بعد صدور الحكم المنهى للخصومة كلها ، و ذلك عدا الأحكام الوقتية و المستعجلة و الصادرة بوقف الدعوى و الأحكام القابلة للتنفيذ الجبرى ، و الأحكام الصادرة بعدم الأختصاص و الإحالة إلى المحكمة المختصة ، و فى الحالة الأخيرة يجب على المحكمة المحالة إليها الدعوى أن توقفها حتى يفصل فى الطعن ."}, {"number": "213", "chapter": "الفصل الأول", "text": "- \" يبدأ ميعاد الطعن فى الحكم من تاريخ صدوره ما لم من القانون على غير ذلك . ويبدأ هذا الميعاد من تاريخ إعلان الحكم إلى المحكوم عليه فى الأحوال التى يكون فيها قد تخلف عن الحضور فى جميع الجلسات المحددة لنظر الدعوى ولم يقدم مذكرة بدفاعه أمام المحكمة ولا أمام الخبير ، وكذلك إذا تخلف عن الحضور ولم يقدم مذكرة إلى المحكمة ولا إلى الخبير فى جميع الجلسات التالية لتعجيل الدعوى بعد وقف السير فيها لأى سبب من الأسباب \" . كما يبدأ الميعاد من تاريخ إعلان الحكم إذا حدث سبب من أسباب إنقطاع الخصومة و صدر الحكم دون إختصام من يقوم مقام الخصم الذى توفى أو فقد أهليته للخصومة أو زالت صفته . و يكون إعلان الحكم لشخص المحكوم عليه أو فى موطنه الأصلى . و يجرى الميعاد فى حق من أعلن الحكم ."}, {"number": "214", "chapter": "الفصل الأول", "text": "يكون إعلان الطعن لشخص الخصم أو فى موطنه و يجوز إعلانه فى الموطن المختار فى ورقة إعلان الحكم . و إذا كان المطعون ضده هو المدعى ، و لم يكن قد بين فى صحيفة إفتتاح الدعوى موطنه الأصلى ، جاز إعلانه بالطعن فى موطنه المختار المبين فى هذه الصحيفة ."}, {"number": "215", "chapter": "الفصل الأول", "text": "يترتب على عدم مراعاة مواعيد الطعن فى الأحكام سقوط الحق فى الطعن . و تقضى المحكمة بالسقوط من تلقاء نفسها ."}, {"number": "216", "chapter": "الفصل الأول", "text": "يقف ميعاد الطعن بموت المحكوم عليه أو يفقد أهليته للتقاضى أو بزوال صفة من كان يباشر الخصومة عنه و لا يزول الوقف إلا بعد إعلان الحكم إلى من يقوم مقام الخصم الذى توفى أو فقد أهليته للتقاضى أو زالت صفته و إنقضاء المواعيد التى يحددها قانون بلد المتوفى لأتخاذ صفة الوارث إن كان ."}, {"number": "217", "chapter": "الفصل الأول", "text": "إذا توفى المحكوم له أثناء ميعاد الطعن جاز لخصمه رفع الطعن و إعلانه إلى ورثته جملة دون ذكر أسمائهم وصفاتهم و ذلك فى أخر موطن كان لمورثهم . و متى تم رفع الطعن و إعلانه على الوجه المتقدم وجبت إعادة إعلانه لجميع الورثة بأسمائهم وصفاتهم لأشخاصهم أو فى موطن كل منهم قبل الجلسة المحددة لنظر الطعن أو فى الميعاد الذى تحدده المحكمة لذلك ."}, {"number": "218", "chapter": "الفصل الأول", "text": "- فيما عدا الأحكام الخاصة بالطعون التى ترفع من النيابة العامة لا يفيد من الطعن إلا من رفعه و لا يحتج به إلا على من رفع عليه . على أنه إذا كان الحكم صادراً فى موضوع غير قابل للتجزئة أو فى إلتزام بالتضامن أو فى دعوى يوجب القانون فيها إختصام أشخاص معينين جاز لمن فوت ميعاد الطعن من المحكوم عليهم أو قبل الحكم أن يطعن فيه أثناء نظر الطعن المرفوع فى الميعاد من أحد زملائه منضماً إليه فى طلباته فإن لم يفعل أمرت المحكمة الطاعن بإختصامه فى الطعن و إذا رفع الطعن على أحد المحكوم لهم فى الميعاد وجب إختصام الباقين و لو بعد فواته بالنسبة لهم . كذلك يفيد الضامن و طالب الضمان من الطعن المرفوع من أيهما فى الحكم الصادر فى الدعوى الأصلية إذا أتخذ دفاعها فيها . و إذا رفع طعن على أيهما جاز إختصام الأخر فيه ."}, {"number": "219", "chapter": "الفصل الثانى", "text": "للخصوم فى غير الأحوال المستثناة بنص القانون أن يستأنفوا أحكام محاكم الدرجة الأولى الصادرة فى أختصاصها الأبتدائى . و يجوز الأتفاق و لو قبل رفع الدعوى على أن يكون حكم محكمة الدرجة الأولى إنتهائياً ."}, {"number": "220", "chapter": "الفصل الثانى", "text": "يجوز أستئناف الأحكام الصادرة فى المواد المستعجلة أيا كانت المحكمة التى أصدرتها ."}, {"number": "221", "chapter": "الفصل الثانى", "text": "يجوز أستئناف الأحكام الصادرة بصفة إنتهائية من محاكم الدرجة الأولى بسبب مخالفة قواعد الأختصاص المتعلقة بالنظام العام ، أو وقوع بطلان فى الحكم ، أو بطلان فى الإجراءات أثر فى الحكم . \" وعلى المستأنف فى هذه الأحوال أن يودع خزانة المحكمة الاستئنافية عند تقديم الاستئناف على سبيل الكفالة مائة جنيه ، ويكفى ايداع أمانة واحدة فى حالة تعدد الطاعنين إذا اقاموا طعنهم بصحيفة واحدة ولو اختلفت أسباب الطعن . ويعفى من ايداع الكفالة من اعفى من أداء الرسوم القضائية و لا يقبل قلم الكتاب صحيفة الطعن إذا لم تصحب بما يثبت هذا الإيداع ، و تصادر الكفالة بقوة القانون متى حكم بعدم جواز الأستئناف لعدم مخالفة قواعد الأختصاص أو لأنتفاء البطلان"}, {"number": "222", "chapter": "الفصل الثانى", "text": "و يجوز أيضاً أستئناف جميع الأحكام الصادرة فى حدود النصاب الأنتهائى إذا كان الحكم صادراً على خلاف حكم سابق لم يحز قوة الأمر المقضى . و فى هذه الحالة يعتبر الحكم السابق مستأنفاً بقوة القانون إذا لم يكن قد صار إنتهائياً عند رفع الأستئناف ."}, {"number": "223", "chapter": "الفصل الثانى", "text": "تقدر قيمة الدعوى فيما يتعلق بنصاب الأستئناف وفقاً لأحكام المواد من 36 إلى 41 ، لا تحتسب فى هذا التقدير الطلبات غير المتنازع فيها و لا المبالغ المعروضة عرضاً فعلياً ."}, {"number": "224", "chapter": "الفصل الثانى", "text": "إذا قدم المدعى عليه طلبا عارضا كان التقدير على أساس الأكبر قيمة من الطلبين : الأصلى أو العارض . و مع ذلك إذا كان موضوع الطلب العارض تعويضات عن رفع الدعوى الأصلية أو عن طريق السلوك فيها فتكون العبرة بقيمة الطلب الأصلى وحده ."}, {"number": "225", "chapter": "الفصل الثانى", "text": "يكون التقدير بمراعاة القواعد المتقدمة على أساس أخر طلبات للخصوم أمام محكمة الدرجة الأولى ."}, {"number": "226", "chapter": "الفصل الثانى", "text": "جميع الأحكام الصادرة قبل الفصل فى موضوع الدعوى يراعى فى تقدير نصاب أستئنافها قيمة الدعوى ."}, {"number": "227", "chapter": "الفصل الثانى", "text": "ميعاد الأستئناف أربعون يوما ما لم ينص القانون على غير ذلك . و يكون الميعاد خمسة عشر يوما فى المواد المستعجلة أيا كانت المحكمة التى أصدرت الحكم . و يكون ميعاد الأستئناف ستين يوما بالنسبة للنائب العام أو من يقوم مقامه ."}, {"number": "228", "chapter": "الفصل الثانى", "text": "إذا صدر الحكم بناء على غش وقع من الخصم أو بناء على ورقة مزورة أو بناء على شهادة زور أو بسبب عدم إظهار ورقة قاطعة فى الدعوى أحتجزها الخصم فلا يبدأ ميعاد أستئنافه إلا من اليوم الذى ظهر فيه الغش أو الذى أقر فيه بالتزوير فاعله أو حكم بثبوته أو الذى حكم فيه على شاهد الزور أو اليوم الذى ظهرت فيه الورقة التى أحتجزت ."}, {"number": "229", "chapter": "الفصل الثانى", "text": "أستئناف الحكم المنهى للخصومة يستتبع حتما أستئناف جميع الأحكام التى سبق صدورها فى القضية ما لم تكن قد قبلت صراحة و ذلك مع مراعاة ما نصت عليه المادة 232 . و أستئناف الحكم الصادر فى الطلب الأحتياطى يستتبع حتما أستئناف الحكم الصادر فى الطلب الأصلى و فى هذه الحالة يجب أختصام المحكوم له فى الطلب الأصلى و لو بعد فوات الميعاد ."}, {"number": "230", "chapter": "الفصل الثانى", "text": "يرفع الأستئناف بصحيفة تودع قلم كتاب المحكمة المرفوع إليها الأستئناف وفقا للأوضاع المقررة لرفع الدعوى و يجب أن تشتمل الصحيفة على بيان الحكم المستأنف و تاريخه و أسباب الأستئناف و الطلبات و إلا كانت باطلة ."}, {"number": "231", "chapter": "الفصل الثانى", "text": "على قلم كتاب المحكمة المرفوع إليها الأستئناف أن يطلب ضم ملف الدعوى الأبتدائية فى اليوم التالى لليوم الذى يرفع فيه الأستئناف . و على قلم كتاب المحكمة التى أصدرت الحكم أن ترسل ملف الدعوى خلال عشرة أيام على الأكثر من تاريخ طلبه و ينقص هذا الميعاد إلى ثلاثة أيام فى الدعوى المستعجلة ، و تحكم المحكمة الأستئنافية على من يهمل فى طلب ضم الملف أو فى أرساله فى الميعاد بغرامة لا تقل عن عشرين جنيها و لا تجاوز مائتى جنيه بحكم غير قابل للطعن ."}, {"number": "232", "chapter": "الفصل الثانى", "text": "الأستئناف ينقل الدعوى بحالتها التى كانت عليها قبل صدور الحكم المستأنف بالنسبة لما رفع عنه الأستئناف فقط ."}, {"number": "233", "chapter": "الفصل الثانى", "text": "يجب على المحكمة أن تنظر الأستئناف على أساس ما يقدم لها من أدلة و دفوع و أوجه دفاع جديدة و ما كان قد قدم من ذلك إلى محكمة الدرجة الأولى ."}, {"number": "234", "chapter": "الفصل الثانى", "text": "يجب على المحكمة إذا ألغت الحكم الصدر فى الطلب الأصلى أن يعيد القضية إلى محكمة الدرجة الأولى لتفصل فى الطلبات الإحتياطية ."}, {"number": "235", "chapter": "الفصل الثانى", "text": "لا تقبل الطلبات الجديدة فى الأستئناف و تحكم المحكمة من تلقاء نفسها بعدم قبولها . و مع ذلك يجوز أن يضاف إلى الطلب الأصلى الأجور و الفوائد و المرتبات و سائر الملحقات التى تستحق بعد تقديم الطلبات الختامية أمام محكمة الدرجة الأولى و ما يزيد من التعويضات بعد تقديم هذه الطلبات . و كذلك يجوز مع بقاء موضوع الطلب الأصلى على حاله تغيير سببه و الإضافة إليه . و يجوز للمحكمة أن تحكم بالتعويضات إذا كان الأستئناف قد قصد به الكيد ."}, {"number": "236", "chapter": "الفصل الثانى", "text": "لا يجوز فى الأستئناف إدخال من لم يكن خصماً فى الدعوى الصادر فيها الحكم المستأنف ما لم ينص القانون على غير ذلك . و لا يجوز التدخل فيه إلا ممن يطلب الأنضمام إلى أحد الخصوم ."}, {"number": "237", "chapter": "الفصل الثانى", "text": "يجوز للمستأنف عليه إلى ما قبل إقفال باب المرافعة أن يرفع أستئنافا مقابلا بالإجراءات المعتادة أو بمذكرة مشتملة على أسباب أستئنافه . فإذا رفع الأستئناف المقابل بعد مضى ميعاد الأستئناف أو بعد قبول الحكم قبل رفع الأستئناف الأصلى اعتبر أستئنافا فرعيا يتبع الأستئناف الأصلى و يزول بزواله ."}, {"number": "238", "chapter": "الفصل الثانى", "text": "تحكم المحكمة فى جميع الأحوال بقبول ترك الخصومة فى الأستئناف إذا نزل المستأنف عن حقه أو كان ميعاد الأستئناف قد أنقضى وقت الترك ."}, {"number": "239", "chapter": "الفصل الثانى", "text": "الحكم بقبول ترك الخصومة فى الأستئناف الأصلى يستتبع الحكم ببطلان الأستئناف الفرعى و تلزم المحكمة بمصاريفه من ترى إلزامه بها من الخصوم بناء على ما تتبينه من ظروف الدعوى و أحوالها ."}, {"number": "240", "chapter": "الفصل الثانى", "text": "تسرى على الأستئناف القواعد المقررة أمام محكمة الدرجة الأولى سواء فيما يتعلق بالإجراءات أو بالأحكام ما لم يقض القانون بغير ذلك ."}, {"number": "241", "chapter": "الفصل الثالث", "text": "للخصوم أن يلتمسوا إعادة النظر فى الأحكام الصادرة بصفة إنتهائية فى الأحوال الآتية : 1 - إذا وقع من الخصم غش كان من شأنه التأثير فى الحكم . 2 - إذا حصل بعد الحكم إقرار بتزوير الأوراق التى بنى عليها أو قضى بتزويرها . 3 - إذا كان الحكم قد بنى على شهادة شاهد قضى بعد صدوره بأنها مزورة . 4 - إذا حصل الملتمس بعد صدور الحكم على أوراق قاطعة فى الدعوى كان خصمه قد حال دون تقديمها . 5 -إذا قضى الحكم بشئ لم يطلبه الخصوم أو بأكثر مما طلبوا . 6 - إذا كان منطوق الحكم مناقضا بعضه لبعض . 7 - إذا صدر الحكم على شخص طبيعى أو أعتبارى لم يكن ممثلا تمثيلا صحيحا فى الدعوى و ذلك فيما عدا حالة النيابة الأتفاقية . 8 - لمن يعتبر الحكم الصادر فى الدعوى حجة عليه و لم يكن قد أدخل أو تدخل فيها بشرط إثبات غش من كان يمثله أو تواطئه أو إهماله الجسيم ."}, {"number": "242", "chapter": "الفصل الثالث", "text": "ميعاد الألتماس أربعون يوما . و لا يبدأ فى الحالات المنصوص عليها فى الفقرات الأربع الأولى من ال مادة السابقة إلا من اليوم الذى ظهر فيه الغش أو الذى أقر فيه بالتزوير فاعله أو حكم بثبوته أو الذى حكم فيه على شاهد الزور أو اليوم الذى ظهرت فيه الورقة المحتجزة . و يبدأ الميعاد فى الحالة المنصوص عليها فى الفقرة السابعة من اليوم الذى يعلن فيه الحكم إلى من يمثل المحكوم عليه تمثيلا صحيحا . و يبدأ الميعاد فى الحالة المنصوص عليها فى الفقرة السابعة من اليوم الذى ظهر فيه الغش أو التواطؤ أو الأهمال الجسيم ."}, {"number": "243", "chapter": "الفصل الثالث", "text": "يرفع الألتماس أمام المحكمة التى أصدرت الحكم بصحيفة تودع قلم كتابها وفقا للأوضاع المقررة لرفع الدعوى . و يجب أن تشتمل صحيفته على بيان الحكم الملتمس فيه و تاريخه و أسباب الألتماس و إلا كانت باطلة . \" ويجب على رافع الالتماس فى الحالتين المنصوص عيهما فى البندين 7 ، 8 من المادة 241 من هذا القانون أن يودع خزانة المحكمة مبلغ مائتى جنيه على سبيل الكفالة ، و لا يقبل قلم الكتاب صحيفة الالتماس إذا لم تصحب بما يثبت هذا الإيداع . ويعفى من ايداع الكفالة من اعفى من أداء الرسوم القضائية \" . و يجوز أن تكون المحكمة التى تنظر الألتماس مؤلفة من نفس القضاة الذين أصدروا الحكم ."}, {"number": "244", "chapter": "الفصل الثالث", "text": "لا يترتب على رفع اللتماس وقف تنفيذ الحكم و مع ذلك يجوز للمحكمة التى تنظر الألتماس أن تأمر بوقف التنفيذ متى طلب ذلك و كان يخشى من التنفيذ وقوع ضرر جسيم يتعذر تداركه . و يجوز للمحكمة عندما تأمر بوقف التنفيذ أن توجب تقديم كفالة أو تأمر بما تراه كفيلا بصيانة حق المطعون عليه ."}, {"number": "245", "chapter": "الفصل الثالث", "text": "تفصل المحكمة أولا فى جواز قبول ألتماس إعادة النظر ثم تحدد جلسة للمرافعة فى الموضوع دون حاجة إلى إعلان جديد على أنه يجوز لها أن تحكم فى قبول الألتماس وفى موضوع بحكم واحد إذا كان الخصوم قد قدموا أمامها طلباتهم فى الموضوع . و لا تعيد المحكمة النظر إلا فى الطلبات التى تناولها الألتماس ."}, {"number": "246", "chapter": "الفصل الثالث", "text": "إذا حكم برفض الألتماس فى الحالات المنصوص عليها فى الفقرات الست الأولى من المادة 241 يحكم على الملتمس بغرامة لا تقل عن مائة وعشرون جنيها و لا تجاوز ربعمائة جنيه و إذا حكم برفض الألتماس فى الحالتين المنصوص عليهما فى الفقرتين الأخيرتين تقضى المحكمة بمصادرة الكفالة كلها أو بعضها . و فى جميع الأحوال يجوز الحكم بالتعويضات إن كان لها وجه ."}, {"number": "247", "chapter": "الفصل الثالث", "text": "الحكم الذى يصدر برفض الألتماس أو الحكم الذى يصدر فى موضوع الدعوى بعد قبوله لا يجوز الطعن فى أيهما بالألتماس ."}, {"number": "248", "chapter": "الفصل الرابع", "text": "للخصوم أن يطعنوا أمام محكمة النقض في الأحكام الصادرة من محاكم الاستئناف إذا كانت قيمة الدعوى تجاوز خمسمائة ألف جنيه أو كانت غير مقدرة القيمة، وذلك في الأحوال الآتية: 1 - إذا كان الحكم المطعون فيه مبنيًا على مخالفة للقانون أو خطأ في تطبيقه أو في تأويله. 2 - إذا وقع بطلان في الحكم أو بطلان في الإجراءات أثر في الحكم."}, {"number": "249", "chapter": "الفصل الرابع", "text": "للخصوم أن يطعنوا أمام محكمة النقض فى أى حكم إنتهائى - أيا كانت المحكمة التى أصدرته - فصل فى نزاع خلافا لحكم أخر سبق أن صدر بين الخصوم أنفسهم و حاز قوة الأمر المقضى ."}, {"number": "250", "chapter": "الفصل الرابع", "text": "للنائب العام أن يطعن بطريق النقض لمصلحة القانون فى الأحكام الإنتهائية - أيا كانت المحكمة التى أصدرتها - إذا كان الحكم مبنيا على مخالفة للقانون أو خطأ فى تطبيقه أو فى تأويله و ذلك فى الأحوال الآتية :- 1 - الأحكام التى لا يجيز القانون للخصوم الطعن فيها . 2 - الأحكام التى فوت الخصوم ميعاد الطعن فيها أو نزلوا فيها عن الطعن . و يرفع هذا الطعن بصحيفة يوقعها النائب العام و تنظر المحكمة الطعن فى غرفة المشورة بغير دعوة الخصوم ، و لا يفيد الخصوم من هذا الطعن ."}, {"number": "251", "chapter": "الفصل الرابع", "text": "لا يترتب على الطعن بطريق النقض وقف تنفيذ الحكم و مع ذلك يجوز لمحكمة النقض أن تأمر بوقف تنفيذ الحكم مؤقتا إذا طلب ذلك فى صحيفة الطعن و كان يخشى من التنفيذ وقوع ضرر جسيم يتعذر تداركه . و يعين رئيس المحكمة بناء على عريضة من الطاعن جلسة لنظر هذا الطلب يعلن الطاعن خصمه بها و بصحيفة الطعن و تبلغ للنيابة . ويجوز للمحكمة إعتبار الطلب كأن لم يكن إذا لم يتم إعلان الخصم بالجلسة المحددة وكان ذلك راجعا إلى فعل الطاعن . و يجوز للمحكمة عندما تأمر بوقف التنفيذ أن توجب تقديم كفالة أو تأمر بما تراه كفيلا بصيانة حق المطعون عليه و ينسحب الأمر الصادر بوقف تنفيذ الحكم على إجراءات التنفيذ التى أتخذها المحكوم له بناء على الحكم المطعون فيه تاريخ طلب وقف التنفيذ . و إذا رفض الطلب أو إعتبر كأن لم يكن ألزم الطاعن بمصروفاته . و على المحكمة إذا أمرت بوقف التنفيذ أن تحدد جلسة لنظر الطعن أمامها فى ميعاد لا يجاوز ستة أشهر و إحالة ملف الطعن إلى النيابة لتودع مذكرة برأيها خلال الأجل الذى تحدده لها ."}, {"number": "252", "chapter": "الفصل الرابع", "text": "ميعاد الطعن بطريق النقض ستون يوما . و لا يسرى هذا الميعاد على الطعن الذى يرفعه النائب العـــــام لمصلحـــة القانـــون وفقا لحكم المادة 250 ."}, {"number": "253", "chapter": "الفصل الرابع", "text": "يرفع الطعن بصحيفة تودع قلم كتاب محكمة النقض أو المحكمة التى أصدرت الحكم المطعون فيه و يوقعها محام مقبول أمام محكمة النقض . فإذا كان الطعن مرفوعا من النيابة العامة وجب أن يوقع صحيفته رئيس نيابة على الأقل . و تشتمل الصحيفة علاوة على البيانات المتعلقة بأسماء الخصوم و صفاتهم و موطن كل منهم على بيان الحكم المطعون فيه و تاريخه و بيان الأسباب التى بنى عليها الطعن و طلبات الطاعن فإذا لم يحصل الطعن على هذا الوجه كان باطلا و تحكم المحكمة من تلقاء نفسها ببطلانه . و لا يجوز التمسك بسبب من أسباب الطعن غير التى ذكرت فى الصحيفة ، و مع ذلك فالأسباب المبنية على النظام العام يمكن التمسك بها فى أى وقت ،و تأخذ المحكمة بها من تلقاء نفسها . إذا أبدى الطاعن سببا للطعن سببا للطعن بالنقض فيما يتعلق بحكم سابق على صدور الحكم المطعون فيه فى ذات الدعوى أعتبر الطعن شاملا للحكم السابق ما لم يكن قد قبل صراحة ."}, {"number": "254", "chapter": "الفصل الرابع", "text": "يجب على الطاعن أن يودع خزانة المحكمة التى تقدم إليها صحيفة الطعن على سبيل الكفالة مبلغ مائتين وخمسون جنيها إذا كان الحكم المطعون فيه صادرا من محكمة أستئناف أو مائة وخمسون جنيها إذا كان صادرا من محكمة أبتدائية أو جزئية . و يكفى إيداع أمانة واحدة فى حالة تعدد الطاعنين إذا أقاموا طعنهم بصحيفة واحدة و لو أختلفت أسباب الطعن . و لا يقبل قلم الكتاب صحيفة الطعن إذا لم تصحب بما يثبت هذا الإيداع و يعفى من أداء الرسوم ."}, {"number": "255", "chapter": "الفصل الرابع", "text": "يجب على الطاعن أن يودع قلم كتاب المحكمة وقت تقديم الصحيفة صورا منها بقدر عدد المطعون ضدهم و صورة لقلم الكتاب و سند رسمى بتوكيل المحامى الموكل فى الطعن، كما يجب عليه أن يودع فى ذات الوقت : أولا : صورة رسمية أو الصورة المعلنة للحكم المطعون فيه وأخرى من الحكم الإبتدائى إذا كان الحكم المطعون فيه قد أحال إليه فى أسبابه وإلا حكم بعدم قبول الطعن . ثانيا : المستندات التى تؤيد الطعن ، فإذا كانت مقدمة فى طعن آخر فيكفى أن يقدم الطاعن مايدل على ذلك ، وللمحكمة أن تتخذ ماتراه فى سبيل الإطلاع على هذه المستندات ، وعلى قلم كتاب المحكمة التى أصدرت الحكم المطعون فيه أو الحكم الإبتدائى بحسب الأحوال أن يسلم دون المطالبة برسوم لمن يشاء من الخصوم خلال سبعة ايام على الأكثر ما يطلبه من صور الأحكام أو المستندات أو الأوراق مذيلة يعبارة \" صورة لتقديمها إلى محكمة النقض \" وذلك دون إخلال بحق قلم الكتاب فى المطالبة بعد ذلك بما يكون مستحقاعلى القضية أو على أصل الأوراق من رسوم . ويجوز لمحكمة النقض أن تأمر بضم ملف القضية الصادر فيها الحكم المطعون فيه . وإذا كانت صحيفة الطعن قد أودعت قلم كتاب المحكمة التى أصدرت الحكم ، فيجب على قم كتابها إرسال جميع أوراق الطعن إلى محكمة النقض فى اليوم التالى لإيداع الصحيفة ."}, {"number": "256", "chapter": "الفصل الرابع", "text": "يقيد قلم كتاب محكمة النقض فى يوم تقديم الصحيفة أو وصولها إليه فى السجل الخاص بذلك . و عليه فى اليوم التالى على الأكثر أن يسلم أصل الصحيفة و صورها إلى قلم المحضرين لإعلانها ورد الأصل إلى قلم الكتاب . و على قلم المحضرين أن يقوم بإعلان صحيفة الطعن خلال ثلاثين يوما على الأكثر من تاريخ تسليمها إليه ، و لا يترتب على عدم مراعاة هذا الميعاد بطلان إعلان صحيفة الطعن ."}, {"number": "257", "chapter": "الفصل الرابع", "text": "تحكم محكمة النقض بغرامة لا تقل عن ثلاثين جنيها و لا تجاوز مائتى جنيه على من يتخلف من العاملين بأقلام الكتاب أو المحضرين عن القيام بأى إجراء من الإجراءات المقررة فى المادتين السابقتين فى المواعيد المحددة لها."}, {"number": "258", "chapter": "الفصل الرابع", "text": "- إذا بدأ للمدعى عليه فى الطعن أن يقدم دفاعا فعليه أن يودع قلم كتاب محكمة النقض فى ميعاد خمسة عشر يوما من تاريخ إعلانه بصحيفة الطعن مذكرة بدفاعه مشفوعة بسند توكيل المحامى الموكل عنه و بالمستندات التى يرى تقديمها . فإن فعل ذلك كان لرافع الطعن أيضا فى ميعاد خمسة عشر يوما من إنقضاء الميعاد المذكور أن يودع قلم الكتاب مذكرة مشفوعة بالمستندات التى يرى تقديمها مؤيدة للرد . و فى حالة تعدد المدعى عليهم يكون لكل منهم عند الإقتضاء أن يودع فى ميعاد الخمسة عشر يوما الأخيرة مذكرة بالرد على المذكرة المقدمة من المدعى عليهم الأخرين مشفوعة بسند توكيل المحامى الموكل عنه . فإذا أستعمل الطاعن حقه فى الرد كان للمدعى عليهم أن يودعوا فى ميعاد خمسة عشر يوما مذكرة بملاحظاتهم على هذا الرد ."}, {"number": "259", "chapter": "الفصل الرابع", "text": "يجوز للمدعى عليهم فى الطعن قبل إنقضاء الميعاد المنصوص عليه فى الفقرة الأولى من المادة السابقة أن يدخلوا فى الطعن أى خصم فى القضية التى صدر فيها الحكم المطعون فيه لم يوجه إليه الطعن ، و يكون إدخاله بإعلانه الطعن . و لمن أدخل أن يودع قلم كتاب محكمة النقض فى ميعاد خمسة عشر يوما من تاريخ إعلانه مذكرة بدفاعه مشفوعة بالمستندات التى يرى تقديمها و فى هذه الحالة لا تسرى مواعيد الرد المنصوص عليها فى الفقرات الثانية و الثالثة و الرابعة من المادة السابقة إلا بعد إنقضاء الخمسة عشر يوما المذكورة ."}, {"number": "260", "chapter": "الفصل الرابع", "text": "يجوز لكل خصم فى القضية التى صدر فيها الحكم المطعون فيه لم يعلنه أن يتدخل فى قضية الطعن ليطلب الحكم برفض الطعن و يكون تدخله بإيداع مذكرة بدفاعه قلم الكتاب قبل إنقضاء الميعاد المحدد فى الفقرة الأولى من المادة 258 مشفوعة بالمستندات التى تؤيده ."}, {"number": "261", "chapter": "الفصل الرابع", "text": "المذكرات و حوافظ المستندات التى تودع بأسم الخصم يجب أن تكون من أصل و صور بقدر عدد خصومه و أن تكون موقعه من محاميه المقبول أمام محكمة النقض ."}, {"number": "262", "chapter": "الفصل الرابع", "text": "لا يجوز لقلم الكتاب لأى سبب أن يقبل مذكرات أو أوراق بعد إنقضاء المواعيد المحددة لها و إنما يجب عليه أن يحرر محضراً يثبت فيه تاريخ تقديم الورقة و اسم من قدمها و صفته و سبب عدم قبولها ."}, {"number": "263", "chapter": "الفصل الرابع", "text": "بعد إنقضاء المواعيد المنصوص عليها فى المواد السابقة يرسل قلم الكتاب ملف الطعن إلى النيابة العامة . و على النيابة العامة أن تودع مذكرة برأيها فى أقرب وقت مراعية فى ذلك ترتيب الطعون فى السجل ، ما لم تر الجمعية العمومية لمحكمة النقض تقديم نظر أنواع من الطعون قبل دورها . و بعد أن تودع النيابة مذكرة برأيها يعين رئيس المحكمة المستشار المقرر ، و يعرض الطعن على المحكمة فى غرفة المشورة فإذا رأت أن الطعن غير جائز أو غير مقبول لسقوطه ، أو لبطلان إجراءاته ، أو لإقامته على غير الأسباب المبينة فى المادتين 248 ، 249 أو على أسباب تخالف ما استقر عليه قضاؤها أمرت بعدم قبوله بقرار يثبت فى محضر الجلسة مع إشارة موجزة لسببه ، و ألزمت الطاعن بالمصروفات فضلا عن مصادرة الكفالة . و إذا رأت المحكمة أن الطعن جدير بالنظر حددت جلسة لنظره ، و يجوز لها فى هذه الحالة أن تستبعد من الطعن ما لا يقبل من الأسباب أمام محكمة النقض ، و أن تقصر نظره على باقى الأسباب مع إشارة موجزة إلى سبب الأستبعاد . و فى جميع الأحوال لا يجوز الطعن فى القرار الصادر من المحكمة بأى طريق ."}, {"number": "264", "chapter": "الفصل الرابع", "text": "يخطر قلم الكتاب محامى الخصوم الذين أودعوا مذكراتهم بتاريخ الجلسة المحددة قبل إنعقادها بخمسة عشر يوما على الأقل و ذلك بكتاب موصى عليه ، و تدرج القضية فى جدول الجلسة . و يعلق الجدول فى قلم الكتاب قبل الجلسة بخمسة عشر يوما على الأقل و يبقى معلقا طوال المدة المذكورة ."}, {"number": "265", "chapter": "الفصل الرابع", "text": "تحكم المحكمة فى الطعن بغير مرافعة بعد أن يتلو المستشار المقرر تقريرا يلخص فيه أسباب الطعن و الرد عليها و يحصر نقط الخلاف التى تنازعها الخصوم دون إبداء الرأى فيها ."}, {"number": "266", "chapter": "الفصل الرابع", "text": "إذا رأت المحكمة ضرورة المرافعة الشفوية فلها سماع محامى الخصوم و النيابة العامة و فى هذه الحالة لا يؤذن للخصوم أن يحضروا بأنفسهم أمام محكمة النقض من غير محام معهم . و ليس للخصوم الذين لم تودع بأسمهم مذكرات ، الحق فى أن ينيبوا عنهم محاميا فى الجلسة . و لا يجوز إبداء أسباب شفهية فى الجلسة غير الأسباب التى سبق للخصوم بيانها فى الأوراق و ذلك دون إخلال بحكم الفقرة الثالثة من المادة 253 ."}, {"number": "267", "chapter": "الفصل الرابع", "text": "يجوز للمحكمة أستثناء أن ترخص لمحامى الخصوم و للنيابة فى إيداع مذكرات تكميلية إذا رأت بعد إطلاعها على القضية أنه لا غنى عن ذلك و حينئذ تؤجل القضية لجلسة أخرى و تحدد المواعيد التى يجب إيداع تلك المذكرات فيها ."}, {"number": "268", "chapter": "الفصل الرابع", "text": "إذا قبلت المحكمة الطعن تنقض الحكم المطعون فيه كله أو بعضه و تحكم فى المصروفات ."}, {"number": "269", "chapter": "الفصل الرابع", "text": "إذا كان الحكم المطعون فيه قد نقض لمخالفة قواعد الأختصاص تقتصر المحكمة على الفصل فى مسألة الأختصاص ، وعند الإقتضاء تعين المحكمة المختصة التى يجب التداعى إليها بإجراءات جديدة . فإذا كان الحكم قد نقض لغير ذلك من الأسباب تحيل القضية إلى المحكمة التى أصدرت الحكم المطعون فيه لتحكم فيها من جديد بناء على طلب الخصوم ، و فى هذه الحالة يتحتم على المحكمة التى أحيلت إليها القضية أن تتبع حكم محكمة النقض فى المسألة القانونية التى فصلت فيها المحكمة و يجب ألا يكون من بين أعضاء المحكمة التى أحيلت إليها القضية أحد القضاة الذين أشتركوا فى إصدار الحكم المطعون فيه . و مع ذلك إذا حكمت المحكمة بنقض الحكم المطعون فيه و كان الموضوع صالحا للفصل فيه أو كان الطعن للمرة الثانية و رأت المحكمة نقض الحكم المطعون فيه وجب عليها أيا كان سبب النقض أن تحكم فى الموضوع ."}, {"number": "269", "chapter": "الفصل الرابع", "text": "إذا كان الحكم المطعون فيه قد نقض لمخالفة قواعد الأختصاص تقتصر المحكمة على الفصل فى مسألة الأختصاص ، وعند الإقتضاء تعين المحكمة المختصة التى يجب التداعى إليها بإجراءات جديدة . فإذا كان الحكم قد نقض لغير ذلك من الأسباب تحيل القضية إلى المحكمة التى أصدرت الحكم المطعون فيه لتحكم فيها من جديد بناء على طلب الخصوم ، و فى هذه الحالة يتحتم على المحكمة التى أحيلت إليها القضية أن تتبع حكم محكمة النقض فى المسألة القانونية التى فصلت فيها المحكمة و يجب ألا يكون من بين أعضاء المحكمة التى أحيلت إليها القضية أحد القضاة الذين أشتركوا فى إصدار الحكم المطعون فيه . و مع ذلك إذا حكمت المحكمة بنقض الحكم المطعون فيه و كان الموضوع صالحا للفصل فيه أو كان الطعن للمرة الثانية و رأت المحكمة نقض الحكم المطعون فيه وجب عليها أن تحكم فى الموضوع ."}, {"number": "270", "chapter": "الفصل الرابع", "text": "إذا قضت محكمة النقض بعدم قبول الطعن أو رفضه أو بعدم جواز نظره حكمت على رافعه بالمصاريف فضلا عن مصادرة الكفالة كلها أو بعضها . و إذا رأت أن الطعن أريد به الكيد فلها أن تحكم بالتعويض للمدعى عليه فى الطعن ."}, {"number": "271", "chapter": "الفصل الرابع", "text": "يترتب على نقض الحكم إلغاء جميع الأحكام ، أيا كانت الجهة التى أصدرتها و الأعمال اللاحقة للحكم المنقوض متى كان الحكم أساسا لها . و إذا كان الحكم لم ينقض إلا فى جزء منه بقى نافذا فيما يتعلق بالأجزاء الأخرى ما لم تكن مترتبة على الجزء المنقوض ."}, {"number": "272", "chapter": "الفصل الرابع", "text": "لا يجوز الطعن فى أحكام محكمة النقض بأى طريق من طرق الطعن ."}, {"number": "273", "chapter": "الفصل الرابع", "text": "تسرى على قضايا الطعون أمام محكمة النقض القواعد و الإجراءات الخاصة بنظام الجلسات كما تسرى عليها القواعد الخاصة بالأحكام فيما لا يتعارض مع نصوص هذا الفصل ."}, {"number": "274", "chapter": "الفصل الاول", "text": "يجرى التنفيذ تحت اشراف إدارة للتنفيذ تنشأ بمقر كل محكمة إبتدائية ويجوز بقرار من وزير العدل إنشاء فروع لها بدائرة محكمة جزئية . ويرأس إدرة التنفيذ قاض بمحكمة الإستئناف ، ويعاونه عدد كاف من قضاتها يندبهم وزير العدل بعد موافقة مجلس القضاء الأعلى ، وقضاة من المحاكمالإبتدائية بدرجة رئيس محكمة على الأقل ، تخترهم الجمعية العامة للمحكمة . ويلحق بالإدارة عدد كاف من معاونى التنفيذ والموظفين يحدد بقرار من وزير العدل قواعد إختيارهم وتنظيم شئونهم . ولمدير إدارة التنفيذ أو من يعاونه من قضاتها إصدار القرارات والأوامرالمتعلقة بالتنفيذ ، ويكون التظلم من هذه القرارات والأوامر بعريض ترفع لمدير إدارة التنفيذ ، ويعتبر القرار الصادر منه فى التظلم نهائيا . ويصدر بتنظيم إدارة التنفيذ قرار من وزير العدل ."}, {"number": "274", "chapter": "الفصل الاول", "text": "يجرى التنفيذ تحت اشراف قاضى للتنفيذ كل محكمة جزئية من بين قضاة المحكمة الابتدائية ويعاونه فى ذلك عدد كاف من المحضرين وتتبع أمامه الإجراءات المقررة أمام المحكمة الجزئية ما لم ينص القانون خلاف ذلك ."}, {"number": "275", "chapter": "الفصل الاول", "text": "يختص قاضى التنفيذ دون غيره بالفصل فى جميع منازعات التنفيذ الموضوعية والوقتية أيا كانت قيمتها ، ويفصل قاضى التنفيذ فى منازعات التنفيذ الوقتية بوصفه قاضيا للأمور المستعجلة ."}, {"number": "275", "chapter": "الفصل الاول", "text": "يختص قاضى التنفيذ دون غيره بالفصل فى جميع منازعات التنفيذ الموضوعية والوقتية أيا كانت قيمتها ، كما يختص بإصدار القرارات والأوامر المتعلقة بالتنفيذ . يفصل قاضى التنفيذ فى منازعات التنفيذ الوقتية بوصفه قاضيا للأمور المستعجلة ."}, {"number": "276", "chapter": "الفصل الاول", "text": "يكون الاختصاص عند التنفيذ على المنقول لدى المدين لمحكمة التنفيذ التى يقع المنقول فى دائرتها ، وفى حجز ما للمدين لدى الغير لمحكمة موطن المحجوز لديه . ويكون الاختصاص عند التنفيذ على العقار للمحكمة التى يقع العقار فى دائرتها فإذا تناول التنفيذ عقارات تقع فى دوائر محاكم متعددة كان الاختصاص لاحداها ."}, {"number": "277", "chapter": "الفصل الاول", "text": "وتستأنف أحكام قاضى التنفيذ فى المنازعات الوقتية والموضوعية أيا كانت قيمتها أمام المحكمة الابتدائية ."}, {"number": "277", "chapter": "الفصل الاول", "text": "وتستأنف أحكام قاضى التنفيذ فى المنازعات الموضوعية إلى المحكمة الابتدائية إذا زادت قيمة النزاع على الفى جنيها ولم تتجاوز عشرة آلاف جنيه ،والى محكمة الإستئناف إذا زادت على ذلك. وتستأنف أحكامه فى المنازعات الوقتية إلى المحكمة الابتدائية ."}, {"number": "278", "chapter": "الفصل الاول", "text": "يعد بكل إدارة تنفيذ سجل خاص تقيد فيه طلبات التنفيذ التى تقدم إلى مدير إدارة التنفيذ ، وينشا لكل طلب ملف تودع به جميع الأوراق المتعلقة بهذه الطلبات . ويعرض الملف على مدير إدارة التنفيذ أو أى من قضاتها عقب كل أجراء ويثبت به ما يصدره من قرارات وأوامر ، ومايصدره قاضى التنفيذ من أحكام ."}, {"number": "278", "chapter": "الفصل الاول", "text": "يعد بالمحكمة جدول خاص تقيد فيه طلبات التنفيذ ، وينشا لكل طلب ملف تودع به جميع الأوراق المتعلقة بهذه الطلبات . ويعرض الملف على قاض التنفيذ عتب كل أجراء ويثبت به ما يصدره من قرارات وأوامر وأحكام ."}, {"number": "279", "chapter": "الفصل الاول", "text": "يجرى التنفيذ بواسطة معاونى التنفيذ وهم ملزمون بناء على طلب ذى الشأن متى سلم السند التنفيذى لإدارة التنفيذ . فإذا امتنع معاون التنفيذ عن القيام بأى أجراء من إجراءات التنفيذ كان لصاحب الشأن أن يرفع الأمر بعريضة إلى مدير إدارة التنفيذ . فإذا وقعت مقاومة أو تعد على معاون التنفيذ وجب عليه أن يتخذ جميع الوسائل التحفظية ووله فى سبيل ذلك – بعد عرض الأمر على مدير إدارة التنفيذ – أن يطلب معونة القوة العمة والسلطة المحلية ."}, {"number": "279", "chapter": "الفصل الاول", "text": "يجرى التنفيذ بوساطة المحضرين وهم ملزمون بإجرائه بناء على طلب ذى الشأن متى سلمهم السند التنفيذى . فإذا امتنع المحضر عن القيام بأى أجراء من إجراءات التنفيذ كان لصاحب الشأن أن يرفع الأمر بعريضة إلى قاضى التنفيذ . فإذا وقعت مقاومة أو تعد على المحضر وجب عليه أن يتخذ جميع الوسائل التحفظية وان يطلب معونة القوة العامة والسلطة المحلية ."}, {"number": "280", "chapter": "الفصل الثانى", "text": "لا يجوز التنفيذ الجبرى الا بسند تنفيذى اقتضاء لحق محقق الوجود ومعين المقدار وحال الأداء. والسندات التنفيذية هى الأحكام والأوامر والمحررات الموثقة ومحاضر الصلح التى تصدق عليها المحاكم أو مجالس الصلح والأوراق الأخرى التى يعطيها القانون هذه الصفة. ولا يجوز التنفيذ فى غير الأحوال المستثناة بنص فى القانون الا بموجب صورة من السند التنفيذى عليها صيغة التنفيذ التالية \" وعلى الجهة التى يناط بها التنفيذ أن تبادر إليه متى طلب منها وعلى السلطات المختصة أن تعين على أجرائه باستعمال القوة متى طلب إليها ذلك \" ."}, {"number": "281", "chapter": "الفصل الثانى", "text": "يجب أن يسبق التنفيذ إعلان السند التنفيذى لشخص المدين أو فى موطنه الأصلى والا كان باطلا . ويجب ان يشتمل هذا الإعلان على تكليف المدين الوفاء وبيان المطلوب وتعيين موطن مختار لطالب التنفيذ فى البلدة التى بها مقر محكمة التنفيذ المختصة ويجب عند الشروع فى تنفيذ عقد رسمى كفتح اعتماد ان يعلن معه مستخرج بحساب المدين من واقع دفاتر الدائن التجارية. ولا يجوز إجراء التنفيذ الا بعد مضى يوم على الأقل من إعلان السند التنفيذى ."}, {"number": "282", "chapter": "الفصل الثانى", "text": "على المحضر عند إعلان السند التنفيذى أو عند قيامه بالتنفيذ قبض الدين عند عرضه عليه مع إعطاء المخالصة وذلك دون حاجة إلى تفويض خاص ."}, {"number": "283", "chapter": "الفصل الثانى", "text": "من حل قانونا أو اتفاقا محل الدائن فى حقه حل محله فيما اتخذ من إجراءات التنفيذ ."}, {"number": "284", "chapter": "الفصل الثانى", "text": "إذا توفى المدين أو فقد أهليته أو زالت صفة من يباشر الإجراءات بالنيابة عنه قبل البدء فى التنفيذ أو قبل إتمامه فلا يجوز التنفيذ قبل ورثته أو من يقوم مقامه الا بعد مضى ثمانية أيام من تاريخ إعلانهم بالسند التنفيذى . ويجوز قبل انقضاء ثلاثة اشهر من تاريخ وفاة المدين أن تعلن الأوراق المتعلقة بالتنفيذ إلى ورثته جملة فى آخر موطن كان لمورثهم بغير بيان أسمائهم وصفاتهم"}, {"number": "285", "chapter": "الفصل الثانى", "text": "لا يجوز للغير أن يؤدى المطلوب بموجب السند التنفيذى ولا أن يجبر على أدائه الا بعد إعلان المدين بالعزم على هذا التنفيذ قبل وقوعه بثمانية أيام على الأقل."}, {"number": "286", "chapter": "الفصل الثانى", "text": "يجوز للمحكمة فى المواد المستعجلة أو فى الأحوال التى يكون فيها التأخير ضارا أن تأمر بتنفيذ الحكم بموجب مسودته بغير إعلانه وفى هذه الحالة يسلم الكاتب المسودة للمحضر وعلى المحضر أن يردها بمجرد الانتهاء من التنفيذ."}, {"number": "287", "chapter": "الفصل الثالث", "text": "لا يجوز تنفيذ الأحكام جبرا مادام الطعن فيها بالإستئناف جائزا الا إذا كان النفاذ المعجل منصوصا عليه فى القانون أو مأمورا به فى الحكم. ومع ذلك يجوز بمقتضاه اتخاذ الإجراءات التحفظية ."}, {"number": "288", "chapter": "الفصل الثالث", "text": "النفاذ المعجل بغير كفالة واجب بقوة القانون للأحكام الصادرة فى المواد المستعجلة أيا كانت المحكمة التى أصدرتها ، وللأوامر الصادرة على العرائض ، وذلك ما لم ينص الحكم أو الأمر على تقديم كفالة."}, {"number": "289", "chapter": "الفصل الثالث", "text": "النفاذ المعجل واجب بقوة القانون للأحكام الصادرة فى المواد التجارية ، وذلك بشرط تقديم كفالة ."}, {"number": "290", "chapter": "الفصل الثالث", "text": "يجوز الأمر بالنفاذ المعجل بكفالة أو بغير كفالة فى الأحوال الآتية : 1 - الأحكام الصادرة بأداء النفقات والأجور والمرتبات . 2 - إذا كان الحكم قد صدر تنفيذا لحكم سابق حائز لقوة الأمر المقتضى أو مشمول بالنفاذ المعجل بغير كفالة أو كان مبنيا على سند رسمى لم يطعن فيه بالتزوير وذلك متى كان المحكوم عليه خصما فى الحكم السابق أو طرفا فى السند . 3 - إذا كان المحكوم عليه قد أقر بنشأة الإلتزام . 4 - إذا كان الحكم مبنيا على سند عرفى لم يجحده المحكوم عليه . 5 - إذا كان الحكم صادرا لمصلحة طالب التنفيذ فى منازعة متعلقة به . 6 - إذا كان يترتب على تأخير التنفيذ ضرر جسيم بمصلحة المحكوم له."}, {"number": "291", "chapter": "الفصل الثالث", "text": "يجوز التظلم أمام المحكمة الإستئنافية من وصف الحكم وذلك بالإجراءات المعتادة لرفع الدعوى ويكون ميعاد الحضور ثلاثة أيام . ويجوز إبداء هذا التظلم فى الجلسة أثناء . نظر الإستئناف المرفوع عن الحكم . ويحكم فى التظلم مستقلا عن الموضوع."}, {"number": "292", "chapter": "الفصل الثالث", "text": "يجوز فى جميع الأحوال للمحكمة المرفوع إليها الإستئناف أو التظلم أن تأمر بناء على طلب ذى الشأن بوقف النفاذ المعجل إذا كان يخشى وقوع ضرر جسيم من التنفيذ وكانت أسباب الطعن فى الحكم أو الأمر يرجح معها الغاؤه. ويجوز للمحكمة عندما تامر بوقف التنفيذ أن توجب تقديم كفالة أو تأمر بما تراه كفيلا بصيانة حق المحكوم له."}, {"number": "293", "chapter": "الفصل الثالث", "text": "فى الأحوال التى لا يجوز فيها تنفيذ الحكم أو الأمر الا بكفالة ، يكون للملزم بها الخيار بين أن يقدم كفيلا مقتدرا ، أو أن يودع خزانة المحكمة من النقود أو الأوراق المالية ما فيه الكفاية وبين أن يقبل إيداع ما يحصل من التنفيذ خزانة المحكمة أو تسليم الشئ المأمور بتسليمه فى الحكم أو الأمر إلى حارس مقتدر ."}, {"number": "294", "chapter": "الفصل الثالث", "text": "يكون إعلان خيار الملزم بالكفالة اما على يد محضر بورقة مستقلة واما ضمن إعلان السند التنفيذى أو ورقة التكليف بالوفاء . ويجب فى جميع الأحوال أن يتضمن إعلان الخيار تعيين موطن مختار لطالب التنفيذ تعلن إليه فيه الأوراق المتعلقة بالمنازعة فى الكفالة ."}, {"number": "295", "chapter": "الفصل الثالث", "text": "لذى الشأن خلال الثلاثة أيام التالية لهذا الإعلان أن ينازع فى اقتدار الكفيل أو الحارس أو فى كفاية ما يودع على أن يتم إعلان دعوى المنازعة خلال هذا الميعاد بتكليف الخصم بالحضور أمام قاضى التنفيذ المختص ويكون حكمه فى المنازعة إنتهائيا . وإذا لم تقدم المنازعة فى الميعاد أو قدمت ورفضت أخذ على الكفيل فى قلم الكتاب التعهد بالكفالة أو على الحارس قبوله الحراسة ، ويكون المحضر المشتمل على تعهد الكفيل بمثابة سند تنفيذى قبله بالتزامات المترتبة على تعهده."}, {"number": "296", "chapter": "الفصل الرابع", "text": "الأحكام والأوامر الصادرة فى بلد أجنبى يجوز الأمر بتنفيذها بنفس الشروط المقررة فى قانون ذلك البلد لتنفيذ الأحكام والأوامر المصرية فيه ."}, {"number": "297", "chapter": "الفصل الرابع", "text": "يقدم طلب الأمر بالتنفيذ إلى المحكمة الابتدائية التى يراد التنفيذ فى دائرتها وذلك بالأوضاع المعتادة لرفع الدعوى ."}, {"number": "298", "chapter": "الفصل الرابع", "text": "لا يجوز الأمر بالتنفيذ الا بعد التحقيق مما يأتى : 1 - أن محاكم الجمهورية غير مختصة بالمنازعة التى صدر فيها الحكم أو الأمر وان المحاكم الأجنبية التى أصدرته مختصة بها طبقا لقواعد الاختصاص القضائى الدولى المقررة فى قانونها . 2 - أن الخصوم فى الدعوى التى صدر فيها الحكم قد كلفوا الحضور ومثلوا تمثيلا صحيحا . 3 - أن الحكم أو الأمر حاز فى الأمر المقضى طبقا لقانون المحكمة التى أصدرته . 4 - أن الحكم أو الأمر لا يتعارض مع حكم أم أمر سبق صدوره من محاكم الجمهورية ولا يتضمن ما يخالف النظام العام أو الآداب فيها ."}, {"number": "299", "chapter": "الفصل الرابع", "text": "تسرى أحكام المواد السابقة على أحكام المحكمين الصادرة فى بلد أجنبى ، ويجب أن يكون الحكم صادرا فى مسألة يجوز التحكيم فيها طبقا لقانون الجمهورية ."}, {"number": "300", "chapter": "الفصل الرابع", "text": "السندات الرسمية المحررة فى بلد أجنبى يجوز الأمر بتنفيذها بنفس الشروط المقررة فى قانون ذلك البلد لتنفيذ السندات الرسمية للتنفيذ المحررة فى الجمهورية . ويطلب الأمر بالتنفيذ بعريضة تقدم لقاضى التنفيذ الذى يراد التنفيذ فى دائرة اختصاصه . ولا يجوز الأمر بالتنفيذ الا بعد التحقق من توافر الشروط المطلوبة لرسمية السند وقابليته لقانون البلد الذى تم فيه ومن خلوه مما يخالف النظام العام أو الآداب فى الجمهورية ."}, {"number": "301", "chapter": "الفصل الرابع", "text": "العمل بالقواعد المنصوص عليها فى المواد السابقة لا يخل بأحكام المعاهدات المعقودة أو التى تعقد بين الجمهورية وبين غيرها من الدول فى هذا الشأن ."}, {"number": "302", "chapter": "الفصل الخامس", "text": "يجوز فى أية حالة كانت عليها الإجراءات قبل إيقاع البيج إيداع مبلغ من النقود مساو للديون المحجوز من اجلها الفوائد والمصاريف يخصص للوفاء بها دون غيرها ويترتب على هذا الإيداع زاول الحجز عن الأموال المحجوزة وانتقاله إلى المبلغ المودع . وإذا وقعت بعد ذلك حجوز جديدة على المبلغ المودع فلا يكون لها أثر فى حق من خصص لهم المبلغ المودع."}, {"number": "303", "chapter": "الفصل الخامس", "text": "يجوز للمحجوز عليه أن يطلب بصفة مستعجلة من قاضى التنفيذ فى أية حالة تكون عليها الإجراءات تقدير مبلغ يودعه خزانة المحكمة على ذمة الوفاء للحاجز ، ويترتب على هذا الإيداع زاول الحجز من الأموال المحجوزة وانتقاله إلى المبلغ المودع . ويصبح المبلغ المودع مخصصا للوفاء بمطلوب الحاجز عند الإقرار له به أو الحكم له بثبوته."}, {"number": "304", "chapter": "الفصل الخامس", "text": "إذا كانت قيمة الحق المحجوز من اجله لا تتناسب مع قيمة الأموال المحجوز عليها ، جاز للمدين أن يطلب من قاضى التنفيذ الحكم بصفة مستعجلة بقصر الحجز على بعض منه الأموال ويكون ذلك بدعوى ترفع وفقا للإجراءات المعتادة ويخصم فيها الدائنون الحاجزون ."}, {"number": "305", "chapter": "الفصل الخامس", "text": "لا يجوز الحجز على ما يلزم المدين وزوجه وأقاربه وأصهاره على عمود النسب المقيمين معه فى معيشة واحدة من الفراش والثياب وكذلك ما يلزمهم من الغذاء لمدة شهر ."}, {"number": "306", "chapter": "الفصل الخامس", "text": "لا يجوز الحجز على الأشياء الآتية الا لاقتضاء ثمنها أو مصاريف صيانتها أو نفقة مقررة : 1 - ما يلزم المدين من كتب وأدوات ومهمات لمزاولة مهنته أو حرفته بنفسه . 2 - إناث الماشية اللازمة لانتفاع المدين فى معيشته هو وما يلزم لغذاء هذه الماشية لمدة شهر."}, {"number": "307", "chapter": "الفصل الخامس", "text": "لا يجوز الحجز على ما يحكم به القضاء مع المبالغ المقررة أو المرتبة مؤقتا للنفقة أو للصرف منها فى غرض معين ولا على الأموال الموهوبة أو الموصى بها لتكون نفقة الا بمقدار الربع وفاء لدين نفقة مقررة."}, {"number": "308", "chapter": "الفصل الخامس", "text": "الأموال الموهوبة أو الموصى بها مع اشتراط عدم جواز الحجز عليها لا يجوز حجزها من دائنى الموهوب له او الموصى له الذين نشأ دينهم قل الهبة أو الوصية الا لدين نفقة مقررة وبالنسبة المبينة فى ال مادة السابقة ."}, {"number": "309", "chapter": "الفصل الخامس", "text": "لا يجوز الحجز على الأجور والمرتبات الا بمقدار الربع وعند التزاحم يخصص نصفه لوفاء دين النفقة المقررة والنصف الآخر لما عداه من الديون ."}, {"number": "310", "chapter": "الفصل الخامس", "text": "إذا وقع الحجز على ثمار أو محصولات أو غيرها من المنقولات التى يتعين تسليما إلى الدولة أو احدى الهيئات العامة أو المؤسسات العامة أو الوحدات الاقتصادية التابعة لها وجب على الحارس على هذه المنقولات أن يقدم إلى من يتسلمها صور محاضر الحجوز الموقعة عليها ، وينتقل الحجز بتسليم المنقول ومحضر حجزه إلى الثمن الذى يستحقه المدين وذلك دون أى إجراء آخر ."}, {"number": "311", "chapter": "الفصل الخامس", "text": "لا يجوز للمدين ولا للقضاة الذين نظروا بأى وجه من الوجوه إجراءات التنفيذ أو المسائل المتفرعة عنها ولا للمحامين الوكلاء عمن يباشر الإجراءات أو المدين أن يتقدموا للمزايدة بأنفسهم أو بطريق تسخير غيرهم ، والا كان البيع باطلا ."}, {"number": "312", "chapter": "الفصل السادس", "text": "إذا عرض عند التنفيذ أشكال وكان والمطلوب فيه أجراء فلمعاون التنفيذ أن يوقف التنفيذ أو أن يمضى فيه على سبيل الاحتياط مع تكليف الخصوم فى الحالتين الحضور أمام قاضى التنفيذ ولو بميعاد ساعة وفى منزله عند الضرورة ويكفى إثبات حصول هذا التكيف فى المحضر فيما يتعلق برافع الاشكال وفى جميع الاحوال لا يجوز أن يتم التنفيذ قبل أن يصدر القاضى حكمه. وعلى معاون التنفيذ أن يحرر صورا من محضره بقدر عدد الخصوم وصورة لقلم الكتاب يرفق بها أوراق التنفيذ والمستندات التى يقدمها إليه المستشكل وعلى قلم الكتاب قيد الاشكال يوم تسليم الصورة إليه فى السجل الخاص بذلك. ويجب اختصام الطرف الملتزم فى السند التنفيذى فى الاشكال إذا كان مرفوعا من غيره سواء بإبدائه امام معاون التنفيذ على النحو المبين فى الفقرة الأولى أو بالإجراءات المعتادة لرفع الدعوى فإذا لم يختصم فى الاشكال وجب على المحكمة أن تكلف المستشكل باختصامه فى ميعاد تحدده له ، فإن لم ينفذ ما أمرت به المحكمة جاز الحكم بعدم قبول الاشكال . ولا يترتب على تقديم أى أشكال آخر وقف التنفيذ ما لم يحكم قاضى التنفيذ بالوقف . ولا يسرى حكم الفقرة السابقة على أول أشكال يقيمه الطرف الملتزم فى السند التنفيذى إذا لم يكن قد اختصم فى الاشكال السابق ."}, {"number": "313", "chapter": "الفصل السادس", "text": "لا يترتب على العرض الحقيقى وقف التنفيذ إذا كان العرض محل نزاع. ولقاضى التنفيذ أن يأمر بوقف التنفيذ مؤقتا مع إيداع المعروض أو مبلغ أكثر منه يعينه."}, {"number": "314", "chapter": "الفصل السادس", "text": "إذا تغيب الخصوم وحكم القاضى بشطب الاشكال زال الأثر الواقف للتنفيذ المترتب على رفعه."}, {"number": "315", "chapter": "الفصل السادس", "text": "إذا خسر المستشكل دعواه جاز الحكم عليه بغرامة لا تقل عن مائتى جنيها ولا تزيد على ثمانمائة جنيها وذلك مع عدم الإخلال بالتعويضات أن كان لها وجه."}, {"number": "316", "chapter": "الفصل الاول", "text": "للدائن أن يوقع الحجز التحفظى منقولات مدينه فى الأحوال الآتية : 1 - إذا كان حاملا لكمبيالة أو سند تحت الاذن وكان المدين تاجر له توقيع على الكمبيالة أو السند يلزمه بالوفاء بحسب قانون التجارة. 2 - فى كل حالة يخشى فيها فقد الدائن لضمان حقه"}, {"number": "317", "chapter": "الفصل الاول", "text": "لمؤجر العقار أن يوقع فى مواجهة المستأجر أو المستأجر من الباطن الحجز التحفظى على المنقولات والثمرات والمحصولات الموجودة بالعين المؤجرة وذلك ضمانا لحق الامتياز المقرر له قانونا . ويجوز له بذلك أيضا إذا كانت تلك المنقولات والثمرات والمحصولات قد نقلت بدون رضائه من العين المؤجرة ما لم يكن قد مضى على نقلها ثلاثون يوما ."}, {"number": "318", "chapter": "الفصل الاول", "text": "لمالك المنقول أن يوقع الحجز التحفظى عليه عند حائزه ."}, {"number": "319", "chapter": "الفصل الاول", "text": "لا يوقع الحجز التحفظى فى الأحوال المتقدمة الا اقتضاء لحق محقق الوجود وحال الأداء . وإذا لم يكن كيد الدائن سند تنفيذى أو حكم غير واجب النفاذ أو كان دينه غير معين المقدار ، فلا يوقع الحجز الا بأمر من قاضى التنفيذ يأذن فيه بالحجز ويقدر دين الحاجز تقديرا مؤقتا . ويطلب الأمر بعريضة مسببة ، ويجب فى الحالة المذكورة فى المادة السابقة أن تشتمل العريضة على بيان واف للمنقولات المطلوب حجزها . وللقاضى قبل إصدار أمره أن يجرى تحقيقا مختصرا إذا لم تكفه المستندات المؤيدة للطلب ويجوز أن يكون أمره بتوقيع الحجز بعد مهله لا تزيد على ثلاثة أيام من تاريخ هذا الأمر للمطلوب الحجز عليه إلا فى الحالة المذكورة فى المادة السابقة . وإذا كانت الدعوى مرفوعة بالحق من قبل أمام المحكمة المختصة جاز طلب الاذن بالحجز من رئيس الهيئة التى تنظر الدعوى ."}, {"number": "320", "chapter": "الفصل الاول", "text": "يتبع فى الحجز التحفظى على المنقولات القواعد والإجراءات المنصوص عليها فى الفصل الاول من الباب الثالث من هذا الكتاب عدا ما تعلق منها بتحديد يوم البيع . ويجب أن يعلن الحاجز إلى المحجوز عليه محضر الحجز والأمر الصادر به إذا لم يكن قد أعلن به من قبل وذلك خلال ثمانية أيام على الأكثر من تاريخ توقيعه والا اعتبر كأن لم يكن . وفى الاحوال التى يكون فيها الحجز بأمر من قاضى التنفيذ يجب على الحاجز خلال ثمانية أيام المشار إليها فى الفقرة السابقة أن يرفع أمام المحكمة المختصة الدعوى بثبوت الحق وصحة الحجز وإلا أعتبر الحجز كان لم يكن."}, {"number": "321", "chapter": "الفصل الاول", "text": "إذا كانت الدعوى بالحق مرفوعة من قبل أمام محكمة أخرى قدمت دعوى صحة الحجز إلى نفس المحكمة لتنظر فيهما معا."}, {"number": "322", "chapter": "الفصل الاول", "text": "إذا حكم بصحة الحجز تتبع الإجراءات المقررة للبيع فى الفصل الاول من الباب الثالث أو يجرى التنفيذ بتسليم المنقول فى الحالة المشار إليها فى المادة 318."}, {"number": "323", "chapter": "الفصل الاول", "text": "إذا وقع مؤجر العقار الحجز على منقولات المستأجر من الباطن طبقا للمادة 317 فإن إعلان الحجز لهذا المستأجر يعتبر أيضا بمثابة حجز تحت يده على الاجرة . وإذا كان المستأجر الأصلى غير ممنوع من التأجير من الباطن جاز للمستأجر أن يطلب رفع الحجز على منقولاته مع بقاء الحجز تحت يده على الأجرة ."}, {"number": "324", "chapter": "الفصل الاول", "text": "إذا حكم ببطلان الحجز التحفظى أو بإلغائه لانعدام أساسه جاز الحكم على الحاجز بغرامة لا تجاوز ثمانمائة جنيها فضلا عن التعويضات للمحجوز عليه"}, {"number": "325", "chapter": "الفصل الثانى", "text": "يجوز لكل دائن بدين محقق الوجود حال الأداء أن يحجز ما يكون لمدينه لدى الغير من المنقولات أو الديون ولو كانت مؤجلة أو معلقة على شرط . ويتناول الحجز كل دين ينشأ للمدين فى ذمة المحجوز لديه إلى وقت التقرير بما فى ذمته ما لم يكن موقعا على دين بذاته ."}, {"number": "326", "chapter": "الفصل الثانى", "text": "لا يجوز للحاجز أن يضم لدينه من الفوائد التى لم تحل أكثر من فائدة سنة واحدة ولا أن يضم إليه فى مقابل المصاريف أكثر من عشر مبلغ الدين على الا يجاوز ذلك العشر أربعين جنيها ."}, {"number": "327", "chapter": "الفصل الثانى", "text": "إذا لم يكن بيد الدائن سند تنفيذى أو كان دينه غير معين المقدار فلا يجوز الحجز الا بأمر من قاضى التنفيذ يأذن فيه بالحجز ويقدر دين الحاجز تقديرا مؤقتا وذلك بناء على عريضة يقدمها طالب الحجز . ومع ذلك فلا حاجة إلى هذا الاذن إذا كان بيد الدائن حكم ولو كان غير واجب النفاذ متى كان الدين الثابت به معين المقدار ."}, {"number": "328", "chapter": "الفصل الثانى", "text": "يحصل الحجز بدون حاجة إلى إعلان سابق إلى المدين بموجب ورقة من أوراق المحضرين تعلن إلى المحجوز لديه وتشتمل على البيانات الآتية : 1 - صورة الحكم أو السند الرسمى الذى يوقع الحجز بمقتضاه أو اذن القاضى بالحجز أو أمره بتقدير الدين . 2 - بيان أصل المبلغ المحجوز من اجله وفوائده والمصاريف . 3 - نهى المحجوز لديه عن الوفاء بما فى يده إلى المحجوز عليه أو تسليمه اياه مع تعيين المحجوز عليه تعيينا نافيا لكل جهالة . 4 - تعيين موطن مختار للحاجز فى البلدة بها مقر محكمة المواد الجزئية التابع لها موطن المحجوز لديه . 5 - تكليف المحجوز لديه بالتقرير بما فى ذمته خلال خمسة عشر يوما . وإذا لم تشتمل الورقة على البيانات الواردة فى البنود( 1 ) و( 2 ) و( 3 ) كان الحجز باطلا . ولا يجوز لقلم المحضرين إعلان ورقة الحجز الا إذا أودع الحاجز خزانة محكمة المواد الجزئية التابع لها موطن المحجوز لديه أو لحسابها مبلغا كافيا لأداء رسم محضر التقرير بما فى الذمة ويؤثر بالإيداع على اصل الإعلان وصورته ."}, {"number": "329", "chapter": "الفصل الثانى", "text": "إذا كان الحجز تحت يد محصلى الأموال العامة أو الأمناء عليها وجب أن يكون إعلانه لأشخاصهم."}, {"number": "330", "chapter": "الفصل الثانى", "text": "إذا كان المحجوز لديه مقيمة خارج الجمهورية وجب أعلن الحجز لشخصه أو فى موطنه فى الخارج بالأوضاع المقررة فى البلد الذى يقيم فيه ."}, {"number": "331", "chapter": "الفصل الثانى", "text": "إذا كان للمحجوز لديه عدة فروع فلا ينتج الحجز أثره الا بالنسبة إلى الفرع الذى عينه الحاجز ."}, {"number": "332", "chapter": "الفصل الثانى", "text": "يكون إبلاغ الحجز إلى المحجوز عليه بنفس ورقة الحجز بعد اعلانها إلى المحجوز لديه مع تعيين موطن مختار للحاجز فى البلدة التى بها مقر المحكمة الواقع بدائرتها موطن المحجوز عليه . ويجب إبلاغ الحجز خلال ثمانية الأيام التالية لإعلانه إلى المحجوز لديه والا اعتبر الحجز كان لم يكن ."}, {"number": "333", "chapter": "الفصل الثانى", "text": "فى الأحوال التى يكون فيها الحجز بأمر من قاضى التنفيذ يجب على الحاجز خلال ثمانية أيام المشار إليها فى المادة السابقة أن يرفع أمام المحكمة المختصة الدعوى بثبوت الحق وصحة الحجز والا اعتبر الحجز كان لم يكن . وإذا كانت دعوى الدين مرفوعة من قبل أمام محكمة اخرى قدمت دعوى صحة الحجز إلى نفس المحكمة لتنظر فيهما معا ."}, {"number": "334", "chapter": "الفصل الثانى", "text": "إذا اختصم المحجوز لديه فى دعوى صحة الحجز فلا يجوز له أن يطلب إخراجه منها ولا يكون الحكم فيها حجة عليه الا فيما يتعلق بصحة إجراءات الحجز ."}, {"number": "335", "chapter": "الفصل الثانى", "text": "يجوز للمحجوز عليه أن يرفع الدعوى بطلب رفع الحجز أمام قاضى التنفيذ الذى يتبعه ولا يحتج على المحجوز لديه برفع هذه الدعوى الا إذا أبلغت إليه ، ويترتب على إبلاغ المحجوز لديه بالدعوى منعه من الوفاء للحاجز الا بعد الفصل فيها ."}, {"number": "336", "chapter": "الفصل الثانى", "text": "الحجز لا يوقف إستحقاق الفوائد على المحجوز لديه ولا يمنعه من الوفاء ولو كان الحجز مدعى ببطلانه ، كما لا يمنع المحجوز عليه من مطالبته بالوفاء . ويكون الوفاء بالإيداع فى خزانة المحكمة التابع لها المحجوز لديه ."}, {"number": "337", "chapter": "الفصل الثانى", "text": "يبقى الحجز على المبالغ التى تودع خزانة المحكمة تنفيذا لحكم المادة السابقة وعلى قلم الكتاب أخبار الحاجز والمحجوز عليه بحصول الإيداع فى ظرف ثلاثة أيام وذلك بكتاب مسجل مصحوب بعلم وصول . ويجب أن يكون الإيداع مقترنا ببيان موقع من المحجوز لديه بالحجوز التى وقعت تحت يده وتواريخ اعلانها وأسماء الحاجزين والمحجوز عليه وصفاتهم وموطن كل منهم والسندات التى وقعت الحجوز بمقتضاها والمبالغ التى حجز من اجلها . وهذا الإيداع يغنى عن التقرير بما فى الذمة إذا كان المبلغ المودع كافيا للوفاء بدين الحاجز ، وإذا وقع حجز جديد على المبلغ فاصبح غير كاف جاز للحاجز تكليف المحجوز لديه التقرير بما فى ذمته خلال خمسة عشر يوما من يوم تكليفه ذلك ."}, {"number": "338", "chapter": "الفصل الثانى", "text": "يجب على المحجوز لديه رغم الحجز أن يفى للمحجوز عليه بما لا يجوز حجزه بغير حاجة إلى حكم بذلك ."}, {"number": "339", "chapter": "الفصل الثانى", "text": "إذا لم يحصل الإيداع طبقا للمادتين 203 ، 303 وجب على المحجوز لديه أن يقرر بما فى ذمته فى قلم كتاب محكمة المواد الجزئية التابع هو لها خلال الخمسة عشر يوما التالية لإعلانه بالحجز ويذكر فى التقرير مقدار الدين وسببه وأسباب انقضائه أن كان قد النقض ، ويبين جميع الحجوز الموقعة تحت يده ويودع الأوراق المؤيدة لتقريره أو صورا منها مصدقا عليها . وإذا كان تحت يد المحجوز لديه منقولات وجب عليه أن يرفق بالتقرير بيانا مفصلا بها . ولا يعفيه من واجب التقرير أن يكون غير مدين للمحجوز عليه"}, {"number": "340", "chapter": "الفصل الثانى", "text": "إذا كان الحجز تحت يد احدى المصالح الحكومية أو وحدات الإدارة المحلية أو الهشات العامة أو المؤسسات العامة والشركات والجمعيات التابعة وجب عليها أن تعطى الحاجز بناء على طلبه شهادة تقوم مقام التقرير ."}, {"number": "341", "chapter": "الفصل الثانى", "text": "إذا توفى المحجوز لديه أو فقد أهليته أو زالت صفته أو صفة بن يمثله كان للحاجز أن يعلن ورثة ، المحجوز لديه أو من يقوم مقامه بصورة من ورقة الحجز ويكلفه التقرير بما فى الذمة خلال خمسة عشر يوما."}, {"number": "342", "chapter": "الفصل الثانى", "text": "ترفع دعوى المنازعة فى تقرير المحجوز لديه أمام قاضى التنفيذ الذى يتبعه ."}, {"number": "343", "chapter": "الفصل الثانى", "text": "إذا لم يقرر المحجوز لديه بما فى ذمته على الوجه وفى الميعاد المبينين فى المادة 339 أو قرر غير الحقيقة أو اخفى الأوراق الواجب عليه إيداعها لتأييد التقرير جاز الحكم عليه للدائن الذى حصل على سند تنفيذى بدينه بالمبلغ المحجوز من اجله وذلك بدعوى ترفع بالأوضاع المعتادة . ويجب فى جميع الأحوال إلزام المحجوز لديه بمصاريف الدعوى والتعويضات المترتبة على تقصيره أو تأخيره ."}, {"number": "344", "chapter": "الفصل الثانى", "text": "يجب على المحجوز لديه بعد خمسة عشر كوما من تاريخ تقريره أن يدفع إلى الحاجز المبلغ الذى أقر به أو ما يفى منه بحق الحاجز وذلك متى كان حقه وقت الدفع ثابتا بسند تنفيذى وكانت الإجراءات المنصوص عليها فى المادة 285 قد روعيت ."}, {"number": "345", "chapter": "الفصل الثانى", "text": "للمحجوز لديه فى جميع الأحوال أن يخصم مما فى ذمته قدر ما انفقه من المصاريف بعد تقديرها من القاضى ."}, {"number": "346", "chapter": "الفصل الثانى", "text": "إذا لم يحصل الوفاء ولا الإيداع كان للحاجز أن ينفذ على أموال المحجوز لديه بموجب سنده التنفيذى مرفقا به صورة رسمية من تقرير المحجوز لديه ."}, {"number": "347", "chapter": "الفصل الثانى", "text": "إذا كان الحجز على المنقولات ، بيعت بالإجراءات المقررة لبيع المنقول المحجوز لدى المدين دون حاجة إلى حجز جديد . وفى الأحوال التى يكون فيها الحجز على المنقولات ، بيعت بالإجراءات المقرر لبيع المنقول المحجوز لدى المدين دون حاجة إلى حجز جديد ."}, {"number": "348", "chapter": "الفصل الثانى", "text": "إذا كان المحجوز دينا غير مستحق الأداء ، بيع وفقا لما تنص عليه المادة 400. ومع ذلك يجوز للحاجز إذا لم يوجد حاجزون غيره أن لطلب اختط صه بالدين كله أو بقدر حقه منه بحسب لأحوال ، ويكون ذلك بدعوى ترفع على المحجوز عليه والمحجوز لديه أمام قاضى التنفيذ التابع له المحجوز لديه ويعتبر الحكم باختصاص الحاجز بمثابة حوالة نافذ ، ولا يجوز الطعن فى هذا الحكم بأى طريق ."}, {"number": "349", "chapter": "الفصل الثانى", "text": "يجوز للدائن أن يوقع الحجز تحت يد نفسه على ما يكون مدينا به لمدينة ، ويكون الحجز بإعلان إلى المدين يشتمل على البيانات الواجب ذكرها فى ورقة إبلاغ لحجز . وفى الأحوال التى يكون فيها الحجز بأمر من قاضى التنفيذ يجب على الحاجز خلال ثمانية الأيام التالية لإعلان المدين بالحجز أن يرفع أمام المحكمة المختصة الدعوى بثبوت الحق وصحة الحجز ، والا اعتبر الحجز كان لم يكن ."}, {"number": "350", "chapter": "الفصل الثانى", "text": "الحجز الواقع تحت يد احدى المصالح الحكومية أو وحدات الإدارة المحلية أو الهيئات العامة أو المؤسسات العامة والشركات والجمعيات التابعة لها لا يكون له أثر الا لمدة ثلاث سنوات من تاريخ إعلانه ما لم كعلن الحاجز المحجوز لديه فى هذه المدة باستيفاء الحجز فإن لم يحصل هذا الإعلان أو لم يحصل تجديده كل ثلاث سنوات اعتبر الحجز كان لم يكن مهما كانت الإجراءات أو الاتفاقات أو الأحكام التى تكون قد تمت أو صدرت فى شأنه . ولا تبدأ مدة الثلاث سنوات المذكورة بالنسبة إلى خزانة المحكمة الا من تاريخ إيداع المبالغ المحجوز عليها ."}, {"number": "351", "chapter": "الفصل الثانى", "text": "يجوز لقاضى التنفيذ فى أية حالة تكون عليها الإجراءات أن يحكم بصفة مستعجلة فى مواجهة الحاجز بالأذن للمحجوز عليه فى قبض دينه من المحجوز لديه رغم الحجز وذلك فى الحالات الآتية : 1 - إذا وقع الحجز بغير سند تنفيذى أو حكم أو أمر. 2 - إذا لم يبلغ الحجز إلى المحجوز عليه فى الميعاد ، المنصوص عليه فى المادة 332 أو لم ترفع الدعوى بصحة الحجز فى الميعاد المنصوص عليه فى المادة 333. 3 - إذا كان قد حصل الإيداع والتخصيص طبقا للمادة 302 ."}, {"number": "352", "chapter": "الفصل الثانى", "text": "يعاقب المحجوز لديه بالعقوبة المنصوص عليها فى المادة 341 من قانون العقوبات إذا بدد الأسهم والسندات وغيرها من المنقولات المحجوز عليها تحت يده إضرار بالحاجز ."}, {"number": "353", "chapter": "الفصل الاول", "text": "يجرى الحجز بموجب محضر يحرر فى بكان توقعيه والا كان باطلا ويجب أن يشمل المحضر فضلا عن البيانات الواجب ذكرها فى أوراق معاونى التنفيذ على ما يأتى : 1 - ذكر السند التنفيذى . 2 - الموطن المختار الذى اتخذه الحاجز فى البلدة التى - بها مقر محكمة المواد الجزئية الواقع فى دائرتها الحجز . 3 - مكان الحجز وما قام به المحضر من الإجراءات وما لقيه من العقبات والاعتراضات اثناء الحجز وما اتخذه فى شأنها . 4 - مفردات الأشياء المحجوزة بالتفصيل مع ذكر نوعها وأوصافها ومقدارها ووزنها أو مقاسها وبيان قيمتها بالتقريب . 5 - تحديد يوم للبيع وساعته والمكان الذى يجرى فيه . ويجب أن يوقع محضر الحجز كل من المحضر والمدين أن كان حاضرا ولا يعتبر مجرد توقيع المدين رضاء منه بالحكم ."}, {"number": "354", "chapter": "الفصل الاول", "text": "لا يجوز حجز الثمار المتصلة ولا المزروعات القائمة قبل نضجها بأكثر من خمسة واربعين يوما. ويجب أن يبين فى المحضر بالدقة موضع الأرض واسم الحوض ورقم القطعة ومساحتها وحدودها ونوع المزروعات أو نوع الأشجار وعددها وما ينتظر أن يحصد أو يجنى أو ينتج منها وقيمته على وجه التقريب ."}, {"number": "355", "chapter": "الفصل الاول", "text": "لا يجوز توقيع الحجز فى حضور طالب التنفيذ ."}, {"number": "356", "chapter": "الفصل الاول", "text": "لا يجوز لمعاون التنفيذ كسر الأبواب أو فض الأقفال بالقوة لتوقيع الحجز الا بحضور أحد مأمورى الضبط القضائى ويجب أن يوقع هذه المأمور على محضر الحجز والا كان باطلا . ولا يجوز لمعاون التنفيذ أن يجرى تفتيش المدين لتوقيع الحجز على ما فى جيبه الا بإذن سابق من إدارة التنفيذ ."}, {"number": "357", "chapter": "الفصل الاول", "text": "لا يقتضى الحجز نقل الأشياء المحجوزة من موضعها ."}, {"number": "358", "chapter": "الفصل الاول", "text": "نفيس آخر أو على مجوهرات أو أحجار كريمة فتوزن وتبين أوصافها بالدقة فى محضر الحجز. وتقوم هذه الأشياء بمعرفة خبير يعينه إدارة التنفيذ التابع له مكان التنفيذ بناء على طلب معاون التنفيذ . ويجوز بهذه الطريقة تقويم الأشياء الفنية الأخرى بناء على طلب الحاجز أو المحجوز عليه . وفى جميع الأحوال يرفق تقرير الخبير بمحضر الحجز . ويجب إذا اقتضى الحال نقلها لوزنها أو تقويمها أن توضع فى حرز مختوم وان يذكر ذلك فى المحضر مع وصف الأختام ."}, {"number": "359", "chapter": "الفصل الاول", "text": "إذا وقع الحجز على نقود أو عملة ورقية وجب على المحضر أن يبين ذلك فى المحضر ويودعها خزانة المحكمة ."}, {"number": "360", "chapter": "الفصل الاول", "text": "إذا لم يتم الحجز فى يوم واحد جاز إتمامه فى يوم أو أيام تالية بشرط أن تتابع وعلى معاون الحجز أن يتخذ ما يلزم للمحافظة على الأشياء المحجوزة والمطلوب حجزها إلى أن يتم المحضر ويجب التوقيع على المحضر كلما توقفت إجراءات الحجز . ومع ذلك إذا اقتضى الحال استمرار معاون التنفيذ فى إجراءات الحجز بعد المواعيد المقررة فى ال مادة 7 من هذا القانون أو فى أيام العطلات الرسمية جاز له إتمام محضره دون حاجة إلى استصدار إذن من القضاء ."}, {"number": "361", "chapter": "الفصل الاول", "text": "تصبح الأشياء محجوزة بمجرد ذكرها فى محضر الحجز ولو لم يعين عليها حارس ."}, {"number": "362", "chapter": "الفصل الاول", "text": "إذا حصل الحجز بحضور المدين أو فى موطنه ، تسلم له صورة من المحضر على الوجه المبين فى ال مادة 10 فإن كان الحجز قد حصل فى غير موطنه وفى غيبته وجب إعلانه بالمحضر فى اليوم التالى على أكثر."}, {"number": "363", "chapter": "الفصل الاول", "text": "يجب على معاون التنفيذ عقب اقفال محضر الحجز مباشرة أن يلصق على باب المكان الذى وجد به الأشياء المحجوزة وعلى باب العمدة أو الشيخ أو المتر الإدارى التابع له المكان وفى اللوحة المعدة لذلك بمحكمة المواد الجزئية إعلانات موقعا عليها منه يبين فيها يوم البيع وساعته ونوع الأشياء المحجوزة ووصفها بالإجمالى ويذكر حصول ذلك فى محضر يلحق بمحضر الحجز ."}, {"number": "364", "chapter": "الفصل الاول", "text": "يعين المحضر حارسا على الأشياء المحجوزة ويختار هو هذا الحارس إذا لم يأت الحاجز أو المحجوز عليه بشخص مقتدر . ويجب تعيين المحجوز عليه إذا طلب ذلك الا إذا خيف التبديد وكان لذلك أسباب معقولة تذكر فى المحضر. ولا يجوز أن يكون الحارس ممن يعملون فى خدمة الحاجز أو المحضر ولا أن يكون زوجة أو قريبا أو صهر لأيهما إلى الدرجة الرابعة ."}, {"number": "365", "chapter": "الفصل الاول", "text": "إذا لم يجد معاون التنفيذ فى مكان الحجز من يقبل الحراسة وكان المدين حاضرا كلفه الحراسة ولا يعتد برفضه إياها ، اما إذا يكن حاضرا وجب على معاون التنفيذ أن يتخذ جميع التدابير الممكنة للمحافظة على الأشياء المحجوزة وان يرفع الأمر على الفور لإدارة التنفيذ ليأمر اما بنقلها وإيداعها عند أين يقبل الحراسة يختاره الحاجز أو معاون التنفيذ واما بتكليف أحد رجال الإدارة بالمنطقة ، الحراسة مؤقتا"}, {"number": "366", "chapter": "الفصل الاول", "text": "يوقع الحارس على محضر الحجز وتسلم له صورة منه فإن امتنع عن التوقيع على محضر الحجز أو رفض الحجز أو رفض استلام صورته وجب على معاون التنفيذ أن يسلم صورة محضر الحجز فى اليوم ذاته إلى الادارة وان يخطر الحارس بذلك خلال أربع وعشرين ساعة بكتاب مسجل ، وعلى معاون التنفيذ إثبات كل ذلك فى المحضر ."}, {"number": "367", "chapter": "الفصل الاول", "text": "يستحق الحارس غير المدين أو الحائز أجرا عن حراسته ويكون لهذا الأجر امتياز المصروفات القضائية على المنقولات المحجوز عليها . ويقدر أجر الحارس بأمر يصدره إدارة التنفيذ بناء على عريضة تقدم إليه."}, {"number": "368", "chapter": "الفصل الاول", "text": "لا يجوز أن يستعمل الحارس الأشياء المحجوز عليها ولا أن يستغلها أو يغيرها والا حرم من أجرة الحراسة فضلا عن إلزامه بالتعويضات . انما يجوز إذا كان مالكا لها أو صاحب حق فى الانتفاع بها أن يستعملها فيما خصصت له . وإذا كان الحجز على ماشية أو عروض أو آلات لازمة لإدارة أو استغلال أرض أو مصنع أو مشغل أو مؤسسة جاز لقاضى التنفيذ بناء على طلب أحد ذوى الشأن أن يكلف الحارس الإدارة ، أو الاستغلال ، أو يستبدل به حارس آخر يقوم بذلك ."}, {"number": "369", "chapter": "الفصل الاول", "text": "لا يجوز للحارس أن يطلب إعفاءه من الحراسة قبل اليوم المحدد للبيع الا لأسباب توجب ذلك ولرفع هذا الطلب بتكليف المحجوز عليه والحاجز الحضور أمام قاضى التنفيذ بميعاد يوم واحد ولا يجوز الطعن فى الحكم الذى يصدر ويجرد المحضر الأشياء المحجوزة عند تسليم الحارس الجديد مهمته ويثبت هذا الجرد فى محضر يوقع عليه هذا الحارس ويسلم صورة منه."}, {"number": "370", "chapter": "الفصل الاول", "text": "يجوز طلب الاذن بالجنى أو الحصاد من قاضى التنفيذ بعريضة تقدم إليه من الحارس أو من أحد ذوى الشأن ."}, {"number": "371", "chapter": "الفصل الاول", "text": "إذا انتقل المحضر لتوقيع الحجز على أشياء كان قد سبق حجزها وجب على الحارس عليها أن يبرز له صورة محضر الحجز ويقدم الأشياء المحجوزة وعلى المحضر أن يجرد هذه الأشياء فى محضر ويحجز على ما لم يسبق حجزه ويجعل حارس الحجز الأول حارسا عليها أن كانت فى نفس المحل . ويعلن هذا المحضر خلال اليوم التالى على أكثر إلى الحاجز الأول والمدين والحارس إذا لم يكن حاضرا والمحضر الذى أوقع الحجز الأول . ويترتب على هذا الإعلان بقاء الحجز لمصلحة الحاجز الثانى ولو نزل عنه الحاجز الأول كما يعتبر حجزا تحت يد المحضر على المبالغ المتحصلة من البيع ."}, {"number": "372", "chapter": "الفصل الاول", "text": "إذا وقع الحجز على المنقولات باطلا فلا يؤثر ذلك على الحجوز اللاحقة على نفس المنقولات إذا وقعت صحيحة فى ذاتها ."}, {"number": "373", "chapter": "الفصل الاول", "text": "يعاقب الحارس بعقوبة التبديد إذا تعمد عدم إبراز صورة محضر الحجز السابق للمحضر وترتب على ذلك الإضرار المادى بأى من الحاجزين ."}, {"number": "374", "chapter": "الفصل الاول", "text": "للدائن الذى ليس بيده سند تنفيذى أن يحجز تحت يد المحضر على الثمن المتحصل من البيع بغير حاجة إلى طلب الحكم بصحة الحجز ."}, {"number": "375", "chapter": "الفصل الاول", "text": "يعتبر الحجز كان لم يكن اذا لم يتم البيع خلال ثلاثة اشهر من تاريخ توقيعه الا إذا كان البيع قد وقف باتفاق الخصوم أو بحكم المحكمة أو بمقتضى القانون . ومع ذلك لا يجوز الاتفاق على تأجيل البيع لمدة تزيد على ثلاثة اشهر من تاريخ الاتفاق . ولقاضى التنفيذ عند الاقتضاء أن يأمر بمد الميعاد لمدة لا تزيد على ثلاثة اشهر."}, {"number": "376", "chapter": "الفصل الاول", "text": "لا يجوز أجراء البيع الا بعد مضى ثمانية أيام على الأقل من تاريخ تسليم صورة محضر الحجز للمدين أو إعلانه به ولا يجوز أجراؤه الا بعد مضى يوم على الأقل من تاريخ إتمام إجراءات اللصق والنشر . ومع ذلك إذا كانت الأشياء المحجوزة عرضة للتلف أو بضائع عرضه لتقلب الأسعار فلإدارة التنفيذ أن يأمر بإجراء البيع من ساعة لساعة بناء على عريضة تقدم من الحارس أو أحد ذوى الشأن ."}, {"number": "377", "chapter": "الفصل الاول", "text": "يجرى البيع فى المكان الذى توجد فيه الأشياء المحجوزة أو فى أقرب سوق . ولقاض التنفيذ مع ذلك أن يأمر بإجراء البيع - بعد الإعلان عنه - فى مكان آخر بناء على عريضة تقدم له من أحد ذوى الشأن ."}, {"number": "378", "chapter": "الفصل الاول", "text": "\" إذا كانت قيمة الأشياء المطلوب بيعها بحسب ما هى مقدرة به فى محضر الحجز تزيد على عشرة آلاف جنيه وجب الإعلان عن البيع بالنشر فم إحدى الصحف اليومية المقررة لنشر الإعلانات القضائية ويذكر فى الاعلان يوم البيع وساعته ومكانه ونوع الأشياء المحجوزة ووصفها بالإجمالى . ويجوز للدائن الحاجز أو المدين المحجوز عليه ، إذا كان المبلغ المطلوب يزيد على خمسة آلاف جنيه ، أن يطلب من قلم الكتاب النشر على نفقته الخاصة \" ."}, {"number": "379", "chapter": "الفصل الاول", "text": "لكل من الحاجز والمحجوز عليه فى جميع الأحوال أن يطلب بعريضة تقدم لإدارة التنفيذ لصق عدد أكبر من الإعلانات او زيادة النشر فى الصحف أو غيرها من وسائل الإعلان أو بيان الأشياء المطلوب بيعها فى الإعلانات بالتفضيل ."}, {"number": "380", "chapter": "الفصل الاول", "text": "\" يجب قبل بيع مصوغات أو سبائك من الذهب أو الفضة أو من اى معدن نفيس وبيع المجوهرات والأحجار الكريمة إذا زادت القيمة المقدرة لها على عشرين ألف جنيه أن يحصل الإعلان عن البيع بالنشر فى إحدى الصحف اليومية المقررة لنشر الإعلانات القضائية قبل يوم البيع \" ."}, {"number": "381", "chapter": "الفصل الاول", "text": "يجوز أن يعهد إلى رجال الإدارة المحليين كلصق الإعلانات فيما عدا ما يجب وضعه منها فى لوحة المحكمة ."}, {"number": "382", "chapter": "الفصل الاول", "text": "يثبت اللصق بشهادة من المحضر أو من وبال الإدارة مصحوبة بنسخة من الإعلان ويثبت تعليق الإعلان بالمحكمة بذكره فى سجل خاص يعد لذلك ويثبت النشر بتقديم نسخة من الصحيفة او شهادة من جهة الإعلام."}, {"number": "383", "chapter": "الفصل الاول", "text": "إذا لم يحصل البيع فى اليوم المعين فى محضر الحجز أعيد اللصق والنشر على الوجه المبين فى المواد السابقة وأعلن المحجوز عليه بالشهادة المثبتة للصق تهل البيع بيوم واحد على الأقل ."}, {"number": "384", "chapter": "الفصل الاول", "text": "يجرى البيع بالمزاد العلنى بمناداة المحضر كشرط دفع الثمن فورا . ويجب الا يبدأ المحضر فى البيع الا بعد أن تجرد الأشياء المحجوزة ويحرر محضرا بذلك يبين فيه ما يكون قد نقص منها ."}, {"number": "385", "chapter": "الفصل الاول", "text": "لا يجوز بيع مصوغات أو سبائك من الذهب أو الفضة بثمن أقل من قيمتها الذاتية بحسب تقدير أهل الخبرة . فإن لم يتقدم أحد لشرائها حفظت فى خزانة المحكمة كما تحفظ النقود ليوفى منها عينا دين الحاجز وديون غيره من الدائنين ."}, {"number": "386", "chapter": "الفصل الاول", "text": "إذا لم يتقدم أحد لشراء الحلى والمجوهرات والأحجار الكريمة والأشياء المقومة امتد أجل بيعها إلى اليوم التالى إذا لم يكن يوم عطلة فإذا لم يتقدم مشتر بالقيمة المقدرة أجل البيع إلى يوم آخر وأعيد النشر واللصق . على الوجه المبين فى المواد السابقة وعندئذ تباع لمن يرسو عليه المزاد ولو بثمن أقل مما قومت به ."}, {"number": "387", "chapter": "الفصل الاول", "text": "الأشياء التى لم تقوم يؤجل بيعها لليوم التالى أن لم يتقدم أحد للشراء ولم يقبل الحاجز أخذها استيفاء لدينه بالقيمة التى يقدرها أهل خبرة يعينه المحضر ويذكر اسمه فى محضر البيع ."}, {"number": "388", "chapter": "الفصل الاول", "text": "يكفى لإعلان استمرار البيع أو تأجيله أن يذكر المحضر ذلك علانية ويثبته فى محضر البيع ."}, {"number": "389", "chapter": "الفصل الاول", "text": "أن لم يدفع الراسى عليه المزاد الثمن فورا وجبت إعادة البيع على ذمته بالطريقة المتقدمة بأى ثمن كان ويعتبر محضر البيع سندا تنفيذيا بفرق الثمن بالنسبة إليه . ويكون المحضر ملزما بالثمن أن لم يستوفه من المشترى فورا ولم يبادر بإعادة البيع على ذمته ويعتبر محضر البيع سندا بالنسبة إليه كذلك ."}, {"number": "390", "chapter": "الفصل الاول", "text": "يكف المحضر عن المضى فى البيع إذا نتج منه مبلغ كاف لرفاء الديون المحجوز من اجلها هى والمصاريف ، وما يوقع بعد ذلك من الحجوز تحت يد المحضر أو غيره ممن يكون تحت يده الثمن لا يتناول الا ما زاد على وفاء ما ذكر ."}, {"number": "391", "chapter": "الفصل الاول", "text": "يشتمل محضر البيع على ذكر جميع إجراءات البيع وما لقيه المحضر أثناءها من الاعتراضات والعقبات وما اتخذه فى شأنها وحضور المحجوز عليه أو غيابه والثمن الذى رسا وعلى أسم من رسا عليه وتوقيعه."}, {"number": "392", "chapter": "الفصل الاول", "text": "إذا لم يطلب الدائن المباشر للإجراءات البيع فى التاريخ المحدد فى محضر الحجز جاز للحاجزين الآخرين طبقا للمادة 371 أن يطلبوا أجراء البيع بعد أتخاذ إجراءات اللصق والنشر المنصوص عليها فى المواد السابقة وجب فى إعلان الشهادة المثبتة للصق إلى المدين المحجوز عليه وإلى الدائن الذى كان يباشر الإجراءات وذلك قبل البيع بيوم واحد على الأقل ."}, {"number": "393", "chapter": "الفصل الاول", "text": "إذا رفعت دعوى استرداد الأشياء المحجوزة وجب وقف البيع الا إذا حكم قاض التنفيذ باستمرار التنفيذ بشرط إيداع الثمن أو بدونه ."}, {"number": "394", "chapter": "الفصل الاول", "text": "يجب أن ترفع دعوى الاسترداد على الدائن الحاجز والمحجوز دليه والحاجزين المتدخلين وان تشتمل صحيفتها على بيان واف لأدلة الملكية ويجب على المدعى أن يودع عند تقديم الصحيفة لقلم الكتاب ما لديه من المستندات والا وجب الحكم بناء على طلب الحاجز بالاستمرار فى التنفيذ دون انتظار الفصل فى الدعوى ولا يجوز الطعن فى هذا الحكم ."}, {"number": "395", "chapter": "الفصل الاول", "text": "يحق للحاجز أن يمضى فى التنفيذ إذا حكمت المحكمة بشطب الدعوى أو بوقفها عملا بالمادة 99 أو إذا اعتبرت كان لم تكن أو حكم بإعتبارها كذلك كما يحق له أن يمضى فى التنفيذ إذا حكم فى الدعوى برفضها أو بعدم الاختصاص أو بعدم قبولها أو ببطلان صحيفتها أو بسقوط الخصومة فيها أو بقبول تركها ولو كان هذا الحكم قابلا للإستئناف ."}, {"number": "396", "chapter": "الفصل الاول", "text": "إذا رفعت دعوى استرداد ثانية من مسترد آخر أو كان قد سبق رفعها من المسترد نفسه واعتبرت كأن لم تكن أو حكم بإعتبارها كذلك أو شطبها أو بعدم قبولها أو بعدم اختصاص المحكمة أو ببطلان صحيفتها أو بسقوط الخصومة فيها أو بقبول تركها فلا يوقف البيع الا إذا حكم قاضى التنفيذ بوقفه لأسباب هامة ."}, {"number": "397", "chapter": "الفصل الاول", "text": "إذا خسر المسترد دعواه جاز الحكم بغرامة لا تقل عن مائتى جنيها ولا تزيد على ثمانمائة جنيه تمنح كلها أو بعضها للدائن وذلك مع عدم الإخلال بالتعويضات أن كان لها وجه."}, {"number": "398", "chapter": "الفصل الثانى", "text": "الأسهم والسندات إذا كانت لحاملها أو قابلة للتظهير يكون حجزها بالأوضاع المقررة لحجز المنقول ."}, {"number": "399", "chapter": "الفصل الثانى", "text": "الايرادات المرتبة والأسهم الاسمية وحصص الأرباح المستحقة فى ذمة الأشخاص المعنوية وحقوق الموصيين تحجز بالأوضاع المقررة لحجز ما للمدين لدى الغير. ويترتب على حجز الحقوق المشار إليها بالفقرة السابقة حجز ثمراتها وفوائدها ما استحق منها وما يستحق إلى يوم البيع ."}, {"number": "400", "chapter": "الفصل الثانى", "text": "تباع الأسهم والسندات وغيرها مما نص عليه فى المادتين السابقتين بوساطة أحد البنوك أو السماسرة أو الصيارف يعينه قاضى التنفيذ بناء على طلب يقدمه إليه الحاجز ويبين القاضى فى أمره ما يلزم أتخاذه من إجراءات الإعلان ."}, {"number": "401", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يبدأ التنفيذ بإعلان التنبيه بنزع ملكيه العض وإلى المدين لشخصه أو لموطنه مشتملا على البيانات الآتية : 1 - بيان نوع السند التنفيذى وتاريخه ومقدار الدين المطلوب الوفاء به وتاريخ إعلان السند. 2 - إعذار المدين بأنه إذا لم يدفع الدين يسجل التنبيه ويباع عليه العقار جبرا . 3 - وصف العقار مع بيان موقعه ومساحته وحدوده وأرقام القطع وأسماء الأحواض وأرقامها التى يقع فيها وغير ذلك مما يفيد فى تعيينه وذلك بالتطبيق لقانون الشهر العقارى . وللدائن أن يستصدر بعريضة أمرا بالترخيص للمحضر بدخول العقار للحصول على البيانات اللازمة لوصف العقار ومشتملاته . وله أن يستصحب من يعاونه فى ذلك ولا يجوز التظلم من هذا الأمر. 4 - تعيين موطن مختار للدائن المباشر للإجراءات فى البلدة التى بها مقر محكمة التنفيذ . وإذا لم تشتمل ورقة التنبيه على البيانين 1 ، 3 من هذه المادة كانت باطلة . فإذا كان التنفيذ على عقار مرهون من غير المدين أعلن التنبيه إلى الراهن بعد تكليف المدين بالوفاء وفقا للمادة 281."}, {"number": "402", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يسجل تنبيه نزع الملكية فى مكتب من مكاتب الشهر التى تقع فى دائرتها العقارات المبنية فى التنبيه . وإذا قبل سبق تسجيل تنبيه آخر فلا يجوز المضى فى الإجراءات على سبيل التعدد على العقار الواحد وتكون الملوية فى المضى فى الإجراءات لمن أعلن التنبيه الأسبق فى التسجيل . ومع ذلك يجوز لمن أعلن تنبيها لاحقا فى التسجيل أن يطلب من قاضى التنفيذ أن يأذن له فى الحلول محله فى السير بالإجراءات ."}, {"number": "403", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا تبين سبق تسجيل تنبيه عن العقار ذات قام مكتب الشهر بالتأشير بالتنبيه الجديد على هامش تسجيل التنبيه الأول مبينة تاريخ التنبيه الجديد واسم من أعلنه وسند تنفيذه واشر كذلك على أصل التنبيه الجديد بعد تسجيله بما يفيد وجرد التنبيه الأول وبتاريخ تسجيله واسم من أعلنه وسند تنفيذه . ويحصل التأشير بأمر القاضى بالحلول على هامش تسجيل التنبيه السابق والتنبيه اللاحق وذلك بمجرد طلبه بعريضة تقدم إلى مكتب الشهر ."}, {"number": "404", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يترتب على تسجيل التنبيه إعتبار العقار محجوزا ."}, {"number": "405", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "لا ينفذ تصرف المدين أو الحائز أو الكفيل العينى فى العقار ولا ينفذ كذلك ما يترتب عليه من ومن أو اختصاص أو امتياز فى حق الحاجزين ولو كانوا دائنين عاديين ولا فى حق الدائنين المشار إليهم فى المادة 417 ولا من حكم بإيقاع البيع عليه إذا كان التصرف أو الرهن أو الاختصاص أو الامتياز قد حصل شهره بعد تسجيل تنبيه نزع الملكية ."}, {"number": "406", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "تلحق بالعقار ثماره وإيراداته عن المدة التالية لتسجيل التنبيه ، وللمدين أن يبيع ثمار العقار الملحقة به متى كان ذلك من أعمال الإدارة الحسنة . ولكل دائن بيده سند تنفيذى بأن يطلب بعريضة من قاض التنفيذ أمرا بتكليف أحد المحضرين أو الدائنين أو غيرهم حصاد المحصولات وجنى الثمار وبيعها . وتباع الثمار والمحصولات فى كلتا الحالتين بالمزاد أو بأية طريقة اخرى يأذن بها القاضى ويردع الثمن خزانة المحكمة ."}, {"number": "407", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا لم يكن العقار مؤجرا اعتبر المدين حارسا إلى أن يتم البيع ما لم يحكم قاضى التنفيذ بعقله من الحراسة أو بتحديد سلطته ، وذلك بناء على طلب الدائن الحاجز أو أى دائن بيده سند تنفيذى . وللمدين الساكن فى العقار أن يبقى ساكنا فيه بلون اجز إلى أن يتم البيع . وإذا كان العقار مؤجرا اعتبرت الأجرة المستحقة عن المدة التالية لتسجيل التنبيه محجوزة تحت يد المستأجر وذلك بمجرد تكليفه من الحاجز أو أى دائن بيده سند تنفيذى بعدم دفعها للمدين . وإذا وفى المستأجر الأجرة قبل هذا التكليف صح وفاؤه وسئل عنها المدين بوصفه حارسا ."}, {"number": "408", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "مع مراعاة أحكام القوانين الأخرى فى شأن إيجار العقارات تنفذ عقود الإيجار الثابتة التاريخ قبل تسجيل التنبيه فى حق الحاجزين والدائنين المشار إليهم فى المادة 417 ومن حكم بإيقاع البيع عليه وذلك بغير إخلال بأحكام القانون المتعلقة بعقود الإيجار الواجبة الشهر اما عقود الإيجار غير ثابتة التاريخ قبل تسجيل التنبيه فلا تنفيذ فى حق من ذكروا الا إذا كانت من أعمال الإدارة لحسنة ."}, {"number": "409", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "المخالصات عن الأجرة المعجلة والحوالة بها يحتج بها على الحاجزين والدائنين المشار إليهم فى ال مادة 417 ومن حكم بإيقاع البيع عليه متى كانت ثابتة التاريخ قبل تسجيل التنبيه وذلك بغير إخلال بأحكام القانون لمتعلقة بالمخالصات الواجبة الشهر فإذا لم تكن ثابتة لتاريخ قبل تسجيل التنبيه فلا يحتج بها الا لمدة سنة ."}, {"number": "410", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "تطبق العقوبات المنصوص عليها فى المواد 341 ، 342 ، 361 من قانون العقوبات على المدين إذا اختلس الثمرات أو الايرادات التى تلحق بالعقار المحجوز أو إذا اتلف هذا العقار أو اتلف الثمرات ."}, {"number": "411", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا كان العقار مثقلا بتأمين عينى وآل إلى حائز بعقد مسجل قبل تسجيل التنبيه وجب إنذاره بدفع الدين أو تخليته العقار والا جرى التنفيذ فى مواجهته. ويجب أن يكون الانذار مصحوبا بتبليغ التنبيه إليه والا كان باطلا . يترتب على إعلان الإنذار فى حق الحائز جميع الأحكام المنصوص عليها فى المواد من 406 إلى 410."}, {"number": "412", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يجب أن يسجل الإنذار وان يؤشر بتسجيله على هامش تسجيل التنبيه خلال خمسة عشر يوما من تاريخ تسجيل التنبيه والا سقط تسجيل التنبيه ."}, {"number": "413", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا تبين سقط تسجيل إنذار للحائز على العقار ذاته طبقت أحكام المادتين 402 ، 403 وإذا سقط تسجيل التنبيه سقط تبعا له تسجيل الإنذار . الفرع الثانى قائمة شروط البيع والاعتراض عليها"}, {"number": "414", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يودع من يباشر الإجراءات قلم كتاب محكمة التنفيذ قائمة شروط البيع خلال تسعين يوما من تاريخ تسجيل تنبيه نزع الملكية والا اعتبر تسجيل التنبيه كان لم يكن . ويجب أن تشتمل تلك القائمة على البيانات الآتية : 1 - بيان السند التنفيذى الذى حصل التنبيه بمقتضاه . 2 - تاريخ التنبيه وتاريخ إنذار الحائز أن وجد ورقمى تسجيلهما وتاريخه . 3 - تعيين العقارات المبينة فى التنبيه مع بيان موقعها وحدودها ومساحتها ورقم القطعة واسم الحوض ورقمه وغير ذلك من البيانات التى تفيد فى تعيينها . 4 - شروط البيع والثمن الأساسى . ولكون تحديد هذا الثمن وفقا للفقرة الأولى من المادة 37. 5 - تجزئة العقار إلى صفقات أن كان لذلك محل مع ذكر الثمن الأساسى لكل صفقة . ويحدد فى محضر الإيداع تاريخ جلسة الاعتراضات وتاريخ جلسة البيع."}, {"number": "415", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "ترفق بقائمة شروط البيع المستندات الآتية : 1 - شهادة بيان الضريبة العقارية أو عوائد المبانى المقررة على العقار المحجوز . 2 - السند الذى يباشر التنفيذ بمقتضاه . 3 - التنبيه بنزع الملكية . 4 - إنذار الحائز أن كان . 5 - شهادة عقارية بالقيود لغاية تسجيل التنبيه وذلك عن مدة عشر سنوات سابقة ."}, {"number": "416", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا استحق المبيع كان للمشترى الرجوع بالثمن وبالتعويضات أن كان لها وجه ، ولا يجوز أن تتضمن قائمة شروط البيع الإعفاء من رد الثمن ."}, {"number": "417", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يجب على قلم الكتاب خلال الخمسة يوما التالية لإيداع قائمة شروط البيع أن يخبر به المدين والحائز والكفيل العينى والدائنين الذين سجلوا تنبيهاتهم والدائنين أصحاب الحقوق المقيدة قبل تسجيل التنبيه ويكون الأخبار عند وفاة أحد هؤلاء الدائنين لورثته جملة فى الموطن المعين فى القيد. وعلى المحضر الذى قام بإعلان ورقة الأخبار وأخطأ ، مكتب الشهر بحصوله خلال ثمانية الأيام التالية وذلك للتأشير به على هامش تسجيل التنبيه ويصبح الدائنون المشار إليهم فى الفقرة السابقة طرفا فى الإجراءات من تاريخ هذا التأشير . ولا يجوز بعد ذلك شطب التسجيلات والتأشيرات المتعلقة بالإجراءات الا برضاء هؤلاء الدائنين جميعا او بمقتضى أحكام نهاية عليهم ."}, {"number": "418", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "تشمل ورقة الأخبار على البيانات الآتية : 1 - تاريخ إيداع قائمة شروط البيع . 2 - تعيين العقارات المحجوزة على وجه الإجمالى . 3 - بيان الثمن الأساسى المحدد لكل صفقة . 4 - تاريخ الجلسة المحددة للنظر فيما يحتمل تقديمه من الاعتراضات على القائمة وبيان ساعة انعقادها وتاريخ جلسة البيع وساعة انعقادها فى حالة عدم تقديم اعتراضات على القائمة . 5 - إنذار المعلن إليه بالاطلاع على القائمة وإبداء ما قد يكون لديه من أوجه البطلان أو الملاحظات بطريق الاعتراض عليها قبل الجلسة المشار إليها فى الفقرة السابقة بثلاثة أيام على الأقل والا سقط حقه فى ذلك . وكذلك تشتمل ورقة الأخبار على إنذار بائع العقار أو المقايض به بسقوط حقه فى فسخ البيع أو المقايضة إذا لم يتبع أحكام المادة 425."}, {"number": "419", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "تحدد فى محضر إيداع قائمة شروط البيع لنظر الاعتراضات أول جلسة تحل بعد انقضاء ثلاثين يوما من تاريخ انقضاء الميعاد المشار إليه فى المادة 417 ولا تقل المدة بين هذه الجلسة وجلسة البيع عن ثلاثين يوما ولا تزيد على ستين يوما ، فإذا لم تبد اعتراضات اعتبر تحديد أولى هاتين الجلستين كان لم يكن وسير فى إجراءات الإعلان عن البيع ."}, {"number": "420", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يرتب البطلان على مخالفة أحكام المواد 414 ، 415 ، 418."}, {"number": "421", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يعلن قلم الكتاب عن إيداع القائمة بالنشر فى احدى الصحف اليومية المقررة للإعلانات القضائية وبالتعليق فى اللوحة المعدة للإعلانات بالمحكمة وذلك خلال ثمانية الأيام التالية لآخر أخبار بإيداع القائمة . ويودع محضر التعليق ونسخة من الصحيفة ملف التنفيذ فى ثمانية الأيام التالية للإعلان عن الإيداع . ولكل شخص أن يطلع على قائمة شروط البيع فى قلم الكتاب دون أن ينقلها منه ."}, {"number": "422", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "أوجه البطلان فى الإجراءات السابقة على الجلسة المحددة لنظر الأعتراضات و كذلك جميع الملاحظات على شروط البيع يجب على المدين و الحاجز و الكفيل العينى و الدائنين المشار إليهم فى المادة 417 إبداؤها بطريق الأعتراض على قائمة شروط البيع و ذلك بالتقرير بها فى قلم كتاب محكمة التنفيذ قبل الجلسة المشار إليها بثلاثة أيام على الأقل و إلا سقط حقهم فى التمسك بها .و لكل ذى مصلحة غير من ورد ذكرهم فى الفقرة السابقة أبداء ما لديه من أوجه البطلان أو من الملاحظات بطريق الأعتراض على القائمة أو بطريق التدخل عند نظر الأعتراض ."}, {"number": "423", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا كان التنفيذ على حصة شائعة فى عقار فلكل دائن ذى حق مقيد رتب على أعيان مفرزة تدخل ضمنها تلك الحصة الشائعة أن يعرض رغبته فى التنفيذ على تلك الأعيان المفرزة و يطلب بطريق الأعتراض على قائمة شروط البيع وقف إجراءات التنفيذ الخاصة بهذه الحصة . و يحدد الحكم القاضى بوقف الإجراءات المدة التى يجب أن تبدأ خلالها إجراءات التنفيذ على الأعيان المفرزة ."}, {"number": "424", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "لكل من المدين أو الحائز أو الكفيل العينى أن يطلب بطريق الأعتراض على قائمة شروط البيع وقف إجراءات التنفيذ على عقار أو أكثر من العقارات المعينة فى التنبيه إذا أثبت أن قيمة العقار الذى تظل الإجراءات مستمرة بالنسبة إليه تكفى للوفاء بحقوق الدائنين الحاجزين و جميع الدائنين الذين صاروا طرفا فيها وفقا لأحكام المادة 417 و يعين الحكم الصادر فى هذا الأعتراض العقارات التى تقف الإجراءات مؤقتا بالنسبة إليها .و لكل دائن بعد الحكم بإيقاع البيع أن يمضى فى التنفيذ على تلك العقارات إذا لم يكف ثمن ما بيع للوفاء بحقه .و يجوز كذلك للمدين أن يطلب بالطريق ذاته تأجيل إجراءات بيع العقار إذا أثبت أن صافى ما تغله أمواله فى سنة واحدة يكفى لوفاء حقوق الدائنين الحاجزين و جميع الدائنين الذين صاروا طرفا فى الإجراءات و يعين الحكم الصادر بالتأجيل الموعد الذى تبدأ فيه إجراءات البيع فى حالة عدم الوفاء مراعيا فى ذلك المهلة اللازمة للمدين ليستطيع وفاء هذه الديون . و يجوز إبداء الطلبات المتقدمة إذا طرأت ظروف تبرر ذلك فى أية حالة تكون عليها الإجراءات إلى ما قبل أعتماد العطاء ."}, {"number": "425", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "على بائع العقار أو المقايض به أذا أراد أثناء إجراءات التنفيذ رفع دعوى الفسخ لعدم دفع الثمن أو الفرق أن يرفعها بالطرق المعتادة و يدون ذلك فى ذيل قائمة شروط البيع قبل الجلسة المحددة للنظر فى الأعتراضات بثلاثة أيام على الأقل ، و إلا سقط حقه فى الأحتجاج بالفسخ على من حكم بإيقاع البيع عليه . و إذا رفعت دعوى الفسخ و أثبت ذلك فى ذيل قائمة شروط البيع فى الميعاد المشار إليه فى الفقرة السابقة وقفت إجراءات التنفيذ على العقار . الفرع الثالث إجراءات البيع"}, {"number": "426", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "للدائن الذى يباشر الإجراءات و لكل دائن أصبح طرفا فيها وفقا للمادة 417 أن يستصدر أمرا من قاضى التنفيذ بتحديد جلسة البيع . و يصدر القاضى أمره بعد التحقق من الفصل فى جميع الأعتراضات المقدمة فى الميعاد بأحكام واجبة النفاذ و بعد التحقق من أن الحكم المنفذ به أصبح نهائيا .و يخبر قلم الكتاب بخطاب مسجل مصحوب بعلم الوصول الأشخاص الوارد ذكرهم فى المادة 417 بتاريخ جلسة البيع و مكانه و ذلك قبل الجلسة بثمانية أيام على الأقل ."}, {"number": "427", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يحصل البيع فى المحكمة ، و يجوز لمن يباشر الإجراءات و المدين و الحائز و الكفيل العينى و كل ذى مصلحة أن يستصدر إذنا من قاضى التنفيذ بإجراء البيع فى نفس العقار أو فى مكان غيره ."}, {"number": "428", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يعلن قلم الكتاب عن البيع قبل اليوم المحدد لإجرائه بمدة لا تزيد على ثلاثين يوما و لا تقل عن خمسة عشر يوما و ذلك بلصق إعلانات تشتمل على البيانات الآتية : 1 - أسم كل من مباشر الإجراءات و المدين و الحائز و الكفيل العينى و لقبه و مهنته و موطنه أو الموطن المختار . 2 - بيان العقار وفق ما ورد فى قائمة شروط البيع . 3 - تاريخ محضر إيداع شروط البيع . 4 - الثمن الأساسى لكل صفقة . 5 - بيان المحكمة أو المكان الذى يكون فيه البيع و بيان يوم المزايدة و ساعتها ."}, {"number": "429", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "تلصق الإعلانات فى الأمكنة الآتى بيانها : 1 - باب كل عقار من العقارات المطلوب بيعها إذا كانت مسورة أو كانت من المبانى . 2 - باب مقر العمدة فى القرية التى تقع فيها الأعيان و الباب الرئيسى للمركز أو القسم الذى تقع فى دائرته . 3 - اللوحة المعدة للإعلانات بمحكمة التنفيذ .و إذا تناول التنفيذ عقارات تقع فى دوائر محاكم أخرى تلصق الإعلانات أيضا فى لوحات هذه المحاكم .و يثبت المحضر فى ظهر صور الإعلان أنه أجرى اللصق فى الأمكنة المتقدمة الذكر و يقدم هذه الصورة لقلم الكتاب لإيداعها ملف التنفيذ ."}, {"number": "430", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يقوم قلم الكتاب فى الميعاد المنصوص عليه فى المادة 428 بنشر نص الإعلان عن البيع فى إحدى الصحف اليومية المقررة للإعلانات القضائية ،و لا يذكر فى هذا الإعلان حدود العقار . و تودع ملف التنفيذ نسخة من الصحيفة التى حصل فيها النشر مؤشرا عليها من قلم الكتاب بتاريخ تقديمها إليه ."}, {"number": "431", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يجوز للحاجز و المدين و الحائز و الكفيل العينى و كل ذى مصلحة أن يستصدر إذنا من قاضى التنفيذ بنشر إعلانات أخرى عن البيع فى الصحف و غيرها من وسائل الإعلام أو بلصق عدد أخر من الإعلانات بسبب أهمية العقار أو طبيعنه أو لغير ذلك من الظروف و ىلا يترتب على طلب زيادة النشر تأخير البيع بأى حال و يجوز كذلك عند الإقتضاء الإقتصار فى الإعلان عن البيع بإذن من القاضى . و لا يجوز التظلم من الأمر الصادر بزيادة الإعلان أو نقصه ."}, {"number": "432", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يجب على ذوى الشأن إبداء أوجه البطلان فى الإعلان بتقرير فى قلم الكتاب قبل الجلسة المحددة للبيع بثلاثة أيام على الأقل و إلا سقط الحق فيها . و يحكم قاضى التنفيذ فى اليوم المحدد للبيع قبل إفتتاح المزايدة و لا يقبل الطعن فى حكمه بأى طريق . و إذ حكم ببطلان إجراءات الإعلان أجل القاضى البيع إلى يوم يحدده و أمر بإعادة هذه الإجراءات. و إذا حكم برفض طلب البطلان أمر القاضى بإجراء المزايدة على الفور ."}, {"number": "433", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا أمر قاضى التنفيذ بتأجيل البيع و إعادة الإعلان وفقا للمادة السابقة تكون مصاريف إعادة الإجراءات فى هذه الحالة على حساب كاتب المحكمة أو المحضر المتسبب فيها حسب الأحوال ."}, {"number": "434", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يقدر قاضى التنفيذ مصاريف إجراءات التنفيذ بما فيها مقابل أتعاب المحاماه و يعلن هذا التقرير فى الجلسة قبل أفتتاح المزايدة و يذكر فى حكم إيقاع البيع . و لا تجوز المطالبة بأكثر مما ورد فى أمر تقدير المصاريف و لا يصح على أية صورة أشتراط ما يخالف ذلك ."}, {"number": "435", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يتولى قاضى التنفيذ فى اليوم المعين للبيع إجراء المزايدة بناء على طلب من يباشر التنفيذ أو المدين أو الحائز أو الكفيل العينى أو أى دائن أصبح طرفا فى الإجراءات وفقا للمادة 417 و ذلك بعد التحقق من إعلانهم بإيداع قائمة شروط البيع و بجلسة البيع . و إذا جرت المزايدة بدون طلب أحد من هؤلاء كان البيع باطلا ."}, {"number": "436", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يجوز تأجيل المزايدة بذات الثمن الأساسى بناء على طلب كل ذى مصلحة إذا كان للتأجيل أسباب قوية . و لا يجوز الطعن بأى طريق فى الحكم الصادر فى طلب تأجيل البيع ."}, {"number": "437", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "تبدأ المزايدة فى جلسة البيع بمناداة المحضر على الثمن الأساسى و المصاريف . و يعين القاضى قبل بدء المزايدة مقادير التدرج فى العروض فى كل حالة بخصوصها مراعيا فى ذلك مقدار الثمن الأساسى ."}, {"number": "438", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا لم يتقدم مشتر فى جلسة البيع يحكم القاضى بتأجيل البيع مع نقص عشر الثمن الأساسى مرة بعد مرة كلما أقتضت الحال ذلك ."}, {"number": "439", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا تقدم مشتر أو أكثر فى جلسة البيع يعتمد القاضى العطاء فى الجلسة فورا لمن تقدم بأكبر عرض ، و يعتبر العرض الذى لا يزاد عليه خلال ثلاث دقائق منهيا للمزايدة ."}, {"number": "440", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يجب على من يعتمد القاضى عطاءه أن يودع حال إنعقاد الجلسة كامل الثمن الذى أعتمد و المصاريف و رسوم التسجيل ، و فى هذه الحالة تحكم المحكمة بإيقاع البيع عليه . فإن لم يودع الثمن كاملا وجب عليه إيداع خمس الثمن على الأقل و إلا أعيدت المزايدة على ذمته فى نفس الجلسة . و فى حالة عدم إيداع الثمن كاملا يؤجل البيع . و إذا أودع المزايد الثمن فى الجلسة التالية حكم بإيقاع البيع عليه إلا إذا تقدم فى هذه الجلسة من يقبل الشراء مع زيادة العشر مصحوبا بكامل الثمن المزاد ، ففى هذه الحالة تعاد المزايدة فى نفس الجلسة على أساس هذا الثمن . فإذا لم يتقدم أحد للزيادة بالعشر و لم يقم المزايد الأول بإيداع الثمن كاملا وجبت إعادة المزايدة فورا على ذمته ، و لا يعتد فى هذه الجلسة بأى عطاء غير مصحوب بكامل قيمته . و لا يجوز بأى حال من الأحوال أن تشتمل قائمة شروط البيع على ما يخالف ذلك"}, {"number": "441", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "كل حكم يصدر بتأجيل البيع يجب أن يشتمل على تحديد جلسة لإجرائه فى تاريخ يقع بعد ثلاثين يوما و قبل ستين يوما من يوم الحكم .و يعاد الإعلان عن البيع فى الميعاد و بالإجراءات المنصوص عليها فى المواد 428 ، 429 ، 430 .فإذا كان تأجيل البيع قد سبقه أعتماد عطاء وجب أن يشتمل الإعلان أيضا على البيانات الآتى ذكرها: 1 - بيان إجمالى بالعقارات التى أعتمد عطاؤها . 2 - أسم من اعتمد عطاؤه و مهنته و موطنه الأصلى أو المختار . 3 - الثمن الذى أعتمد به العطاء ."}, {"number": "442", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا كان من حكم بإيقاع البيع عليه دائنا و كان مقدار دينه و مرتبته يبرران إعفاؤه من الإيداع أعفاه القاضى ."}, {"number": "443", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يلزم المزايد المتخلف بما ينقص من ثمن العقار و بالفوائد . و يتضمن الحكم بإيقاع البيع إلزام المزايد المتخلف بفرق الثمن إن وجد و لا يكون له حق فى الزيادة بل يستحقها المدين أو الحائز أو الكفيل العينى بحسب الأحوال ."}, {"number": "444", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يجوز لمن حكم بإيقاع البيع عليه أن يقرر فى قلم كتاب المحكمة قبل إنقضاء الثلاثة الأيام التالية ليوم البيع أنه أشترى بالتوكيل عن شخص معين إذا وافقه الموكل على ذلك ."}, {"number": "445", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "على المشترى ان يتخذ موطنا مختارا فى البلدة الاتى بها مقر المحكمة إذا لم يكن ساكنا بها . فإن كان ساكنا وجب أن يبين عنوانه على وجه الدقة . الفرع الرابع الحكم بإيقاع البيع"}, {"number": "446", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يصدر حكم إيقاع البيع بديباجة الأحكام و يشتمل على صورة من قائمة شروط البيع و بيان الإجراءات التى أتبعت فى تحديد يوم البيع و الإعلان عنه و صورة من محضر الجلسة و يشتمل منطوقه على أمر المدين أو الحائز أو الكفيل العينى بتسليم العقار لمن حكم بإيقاع البيع عليه . و يجب إيداع نسخة الحكم الأصلية ملف التنفيذ فى اليوم التالى لصدوره ."}, {"number": "447", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يقوم قلم الكتاب بالنيابة عن ذوى الشأن بطلب تسجيل الحكم بإيقاع البيع خلال ثلاثة الأيام التالية لصدوره . و يكون الحكم المسجل سندا بملكية من أوقع البيع عليه . على انه لا ينقل إليه سوى ما كان للمدين أو للحائز أو الكفيل العينى من حقوق فى العقار المبيع ."}, {"number": "448", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا حكم بإيقاع بيع العقار على حائزه لا يكون تسجيل هذا الحكم واجبا و يؤشر به فى هامش تسجيل السند الذى تملك بمقتضاه العقار أصلا و هامش تسجيل إنذار الحائز ."}, {"number": "449", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "لا يعلن حكم إيقاع البيع و يجرى تنفيذه جبرا بأن يكلف المدين أو الحائز أو الكفيل أو الحارس على حسب الأحوال الحضور فى مكان التسليم فى اليوم و الساعة المحددين لإجرائه على أن يحصل الإعلان بذلك قبل اليوم المعين للتسليم بيومين على الأقل . و إذا كان فى العقار منقولات متعلق بها حق لغير المحجوز عليه وجب على طالب التسليم أن يطلب من قاضى التنفيذ بصفة مستعجلة أتخاذ التدابير اللازمة للمحافظة على حقوق أصحاب الشأن ."}, {"number": "450", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يترتب على تسجيل حكم إيقاع البيع أو التأشير به وفقا لحكم المادة 448 تطهير العقار المبيع من حقوق الأمتياز و الأختصاص و الرهون الرسمية و الحيازية التى أعلن أصحابها بإيداع قائمة شروط البيع و أخبروا بتاريخ جلسته طبقا للمادتين 417 ، 426 و لا يبقى لهم إلا حقهم فى الثمن ."}, {"number": "451", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "لا يجوز أستئناف حكم إيقاع البيع إلا لعيب فى إجراءات المزايدة أو فى شكل الحكم أو فى لصدوره بعد رفض طلب وقف الإجراءات فى حالة يكون وقفها واجبا قانونا . و يرفع الأستئناف بالأوضاع المعتادة خلال خمسة الأيام التالية لتاريخ النطق بالحكم . الفرع الخامس إنقطاع الإجراءات و الحلول"}, {"number": "452", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا لم يودع من يباشر الإجراءات قائمة شروط البيع خلال الخمسة و الأربعين يوما التالية لتسجيل أخر تنبيه قام هو بإجرائه جاز للدائن اللاحق فى التسجيل أن يقوم بإيداع القائمة و يحل محله فى متابعة الإجراءات .و على من يباشر الإجراءات أن يودع قلم الكتاب أوراق الإجراءات خلال ثلاثة الأيام التالية لإنذاره على يد محضر و إلا كان مسئولا عن التعويضات و لا تزد لمن يباشر الإجراءات مصاريف ما باشره منها إلا بعد إيقاع البيع ."}, {"number": "453", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا شطب تسجيل تنبيه الدائن المباشر للإجراءات برضائه أو أعتبر هذا التسجيل كأن لم يكن وفقا لحكم المادة 414 أو بمقتضى حكم صدر بذلك فعلى مكتب الشهر عند التأشير بهذا الشطب أن يؤشر به من تلقاء نفسه على هامش تسجيل كل تنبيه أخر يتناول ذات العقار ، و عليه خلال ثمانية الأيام التالية أن يخبر به الدائنين الذين سجلوا تلك التنبيهات . و للدائن الأسبق فى تسجيل التنبيه أن يسير فى إجراءات التنفيذ من أخر إجراء صحيح على أن يحصل التأشير على هامش تسجيل التنبيه بما يفيد الإخبار بإيداع قائمة شروط البيع خلال تسعين يوما من تاريخ التأشير عليه وفقا لحكم الفقرة السابقة و إلا أعتبر تسجيل تنبيهه كأن لم يكن . الفرع السادس دعوى الأستحقاق الفرعية"}, {"number": "454", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يجوز للغير طلب بطلان إجراءات التنفيذ مع طلب أستحقاق العقار المحجوز عليه أو بعضه و لو بعد إنتهاء الميعاد المقرر للإعتراض على قائمة شروط البيع و ذلك بدعوى ترفع بالأوضاع المعتادة أمام قاضى التنفيذ و يختصم فيها من يباشر الإجراءات و المدين أو الحائز أو الكفيل العينى و أول الدائنين المقيدين ."}, {"number": "455", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يحكم القاضى فى أول جلسة بوقف إجراءات البيع إذا أودع الطالب خزانة المحكمة بالإضافة إلى مصاريف الدعوى المبلغ الذى يقدره قلم الكتاب للوفاء بمقابل أتعاب المحاماه و المصاريف اللازمة لإعادة الإجراءات عند الإقتضاء و كانت صحيفة الدعوى قد أشتملت على بيان المستندات المؤيدة لها و على بيان دقيق لأدلة الملكية أو وقائع الحيازة التى تستند إليها الدعوى و إذا حل اليوم المعين للبيع قبل أن يقضى القاضى بالإيقاف فلرافع الدعوى أن يطلب منه وقف البيع . و ذلك قبل الجلسة المحددة للبيع بثلاثة أيام على الأقل ."}, {"number": "456", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "لا يجوز الطعن بأى طريق فى الأحكام الصادرة وفقا للمادة السابقة بإيقاف البيع أو المضى فيه ."}, {"number": "457", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "إذا لم تتناول دعوى الأستحقاق إلا جزءا من العقارات يوقف البيع بالنسبة إلى باقيها . و مع ذلك يجوز للقاضى أن يأمر بناء على طلب ذى الشان بإيقاع البيع بالنسبة إلى كل الأعيان إذا دعت إلى ذلك اسباب قوية ."}, {"number": "458", "chapter": "الفصل الثالث التنفيذ على العقار", "text": "يعدل القاضى الثمن الأساسى إذا كان المقتضى بيعه جزءا من صفقة واحدة ، و كذلك يكون الشأن عند أستئناف إجراءات البيع بعد الفصل فى دعوى الأستحقاق و ذلك مع مراعاة حكم الفقرة الأولى من المادة 37 ."}, {"number": "459", "chapter": "الفصل الرابع", "text": "بيع عقار المفلس و عقار عديم الأهلية المأذون ببيعه و عقار الغائب بطريق المزايدة يجرى بناء على قائمة شروط البيع التى يودعها قلم كتاب المحكمة المختصة وكيل الدائنين أو النائب عن عديم الأهلية أو الغائب ."}, {"number": "460", "chapter": "الفصل الرابع", "text": "تشتمل قائمة شروط البيع المشار إليها فى المادة السابقة على البيانات الآتية : ( 1 ) الإذن الصادر بالبيع . ( 2 ) تعيين العقار على الوجه المبين بالمادة 401 . ( 3 ) شروط البيع و الثمن الأساسى و يكون تحديد هذا الثمن وفقا للفقرة الأولى من المادة 37 . ( 4 ) تجزئة العقار إلى صفقات إذا اقتضت الحال مع ذكر الثمن الأساسى لكل صفقة . ( 5 ) بيان سندات الملكية ."}, {"number": "461", "chapter": "الفصل الرابع", "text": "ترفق بقائمة شروط البيع المستندات لآتية : ( 1 ) شهادة ببيان الضريبة العقارية أو عوائد المبانى المقررة على العقار . ( 2 ) سندات الملكية و الإذن الصادر بالبيع . ( 3 ) شهادة عقارية عن مدة العشر السنوات السابقة على إيداع القائمة ."}, {"number": "462", "chapter": "الفصل الرابع", "text": "يخبر قلم الكتاب بإيداع قائمة شروط البيع كلا من الدائنين المرتهنين و هذا حيازيا أو رسميا و أصحاب حقوق الأختصاص و الأمتياز و النيابة العامة و ذلك بالأوضاع و فى المواعيد المنصوص عليها فى المادة 417 ، و يكون لهؤلاء إبداء ما لديهم من أوجه البطلان و الملاحظات على شروط البيع بطريق الأعتراض على القائمة ، و تطبق فى هذا الشأن أحكام المادتين 422 ، 425 ."}, {"number": "463", "chapter": "الفصل الرابع", "text": "تطبق على البيوع المشار إليها فى المادة 459 القواعد المتعلقة بإجراءات بيع العقار بناء على طلب الدائنين المنصوص عليها فى الفرعين الثالث و الرابع من الفصل الثالث ."}, {"number": "464", "chapter": "الفصل الرابع", "text": "إذا أمرت المحكمة ببيع العقار المملوك على الشيوع لعدم إمكان القسمة بغير ضرر يجرى بيعه بطريق المزايدة بناء على قائمة بشروط البيع يودعها قلم كتاب المحكمة الجزئية المختصة من يعنيه التعجيل من الشركاء ."}, {"number": "465", "chapter": "الفصل الرابع", "text": "تشتمل قائمة شروط البيع المشار إليها فى المادة السابقة فضلا عن البيانات المذكورة فى المادة 460 على بيان جميع الشركاء و موطن كل منهم كما يرفق بها فضلا عن الأوراق المذكورة فى المادة 461 صورة من الحكم الصادر بإجراء البيع ."}, {"number": "466", "chapter": "الفصل الرابع", "text": "يخبر قلم الكتاب بإيداع قائمة شروط البيع المشار إليها فى المادة السابقة الدائنين المذكورين فى المادة 462 و جميع الشركاء ، و يكون لهؤلاء إبداء ما لديهم من أوجه البطلان و الملاحظات على شروط البيع بطريق الأعتراض على القائمة ."}, {"number": "467", "chapter": "الفصل الرابع", "text": "يجوز لمن يملك عقارا مقررا عليه حق أمتياز أو أختصاص أو رهن رسمى أو حيازى لم يحصل تسجيل تنبيه بنزع ملكيته أن يبيعه أمام القضاء بناء على قائمة بشروط البيع يودعها قلم كتاب المحكمة المختصة ."}, {"number": "468", "chapter": "الفصل الرابع", "text": "تطبق على بيع عقار لعدم إمكان قسمته و على بيعه أختيارا المقررة لبيع عقار المفلس و عديم الأهلية و الغائب فيما عدا اخبار النيابة العامة بإيداع قائمة شروط البيع ."}, {"number": "469", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "متى تم الحجز على نقود لدى المدين أو تم بيع المال المحجوز أو أنقضت خمسة عشر يوماً من تاريخ التقرير بما فى الذمة فى حجز ما للمدين لدى الغير ، أختص الدائنون الحاجزون و من اعتبر طرفاً فى الإجراءات بحصيلة التنفيذ دون أى إجراء أخر ."}, {"number": "470", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "إذا كانت حصيلة التنفيذ كافية للوفاء بجميع حقوق الدائنين الحاجزين و من اعتبر طرفا فى الإجراءات وجب على من تكون لديه هذه المبالغ أن يؤدى لكل من الدائنين دينه بعد تقديم سنده التنفيذى أو بعد موافقة المدين ."}, {"number": "471", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "إذا تعدد الحاجزون و من فى حكمهم و كانت حصيلة التنفيذ غير كافية للوفاء بحقوقهم وجب على من تكون لديه هذه الحصيلة أن يودعها خزينة المحكمة التى يتبعها المحجوز لديه أو التى يقع فى دائرتها مكان البيع حسب الأحوال و على المودع أن يسلم قلم كتاب المحكمة بيان بالحجوز الموقعة تحت يده ."}, {"number": "472", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "إذا أمتنع من عليه الإيداع جاز لكل ذى شأن أن يطلب من قاضى التنفيذ بصفة مستعجلة اللازمة به مع تحديد موعد للإيداع فإذا لم يتم الإيداع خلال هذا الموعد جاز التنفيذ الجبرى على الممتنع فى أمواله الشخصية ."}, {"number": "473", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "إذا لم تكف حصيلة التنفيذ للوفاء بحقوق الحاجزين و من اعتبر طرفا فى الإجراءات و لم يتفقوا و المدين و الحاجزون على توزيعها بينهما خلال الخمسة عشرة يوماً التالية ليوم إيداع هذه الحصيلة خزانة المحكمة قام قلم كتابها بعرض الأمر على إدارة التنفيذ خلال ثلاثة أيام ليجرى توزيع حصيلة التنفيذ وفقاً للأوضاع الآتية ."}, {"number": "474", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "تقوم إدارة التنفيذ خلال خمسة عشرة يوماً من عرض الأمر عليه بإعداد قائمة توزيع مؤقتة يودعها قلم كتاب المحكمة و على قلم الكتاب بمجرد إيداع هذه القائمة أن يقوم بإعلان المدين و الحائز و الدائنين الحاجزين و من أعتبر طرفاً فى الإجراءات إلى جلسة يحدد تاريخها بحيث لا يجاوز ثلاثين يوماً من إيداع القائمة المؤقتة و بميعاد حضور عشرة أيام بقصد الوصول إلى تسوية ودية ."}, {"number": "475", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "فى الجلسة المحددة للتسوية الودية يتناقش ذوو الشأن المشار إليهم فى المادة السابقة فى القائمة المؤقتة و تأمر إدارة التنفيذ بإثبات ملاحظاتهم فى المحضر ولإدارة التنفيذ السلطة التامة فى تحقيق صحة الإعلانات و التوكيلات و قبول التدخل من كل ذى شأن لم يعلن أو يصح إعلانه و ضم توزيع إلى أخر أو تعيين خبراء لتقدير ثمن إحاد مبيع من العقارات جملة و له فضلا عن ذلك إتخاذ أى تدبير أخر يقتضيه حسن سير الإجراءات ."}, {"number": "476", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "إذا حضر ذوو الشأن و إنتهوا إلى إتفاق على التوزيع بتسوية أثبت إدارة التنفيذ أتفاقهم فى محضره و وقعه و كاتب الجلسة و الحاضرون و تكون لهذا المحضر قوة السند التنفيذى ."}, {"number": "477", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "تخلف أحد ذوو الشأن عن الحضور فى الجلسة لا يمنع من إجراء التسوية الودية بشرط عدم المساس بما أثبت للدائن المتخلف فى القائمة المؤقتة . و لا يجوز لمن يتخلف أن يطعن فى التسوية الودية التى أثبتها القاضى بناء على اتفاق الخصوم ."}, {"number": "478", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "إذا تمت التسوية تعد إدارة التنفيذ خلال خمسة الأيام التالية قائمة التوزيع النهائية بما يستحقه كل دائن من أصل و فوائد و مصاريف . و إذا تخلف جميع ذوو الشأن عن حضور الجلسة المحددة للتسوية الودية أعتبر إدارة التنفيذ القائمة المؤقتة قائمة نهائية . و فى كلتا الحالتين تأمر إدرة التنفيذ بتسليم أوامر الصرف على الخزانة و بشطب القيود سواء تعلقت بديون أدركت فى القائمة أو بديون لم يدركها التوزيع ."}, {"number": "479", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "إذا لم تتيسر التسوية الودية لأعتراض بعض ذوى الشأن يأمر مدير إدارة التنفيذ بإثبات مناقضاتهم فى المحضر ويحيل الإعترا ض إلى قاضى التنفيذ الذى ينظر فيه على الفور و لا يجوز إبداء مناقضات جديدة بعد هذه الجلسة ."}, {"number": "480", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "الحكم في المناقضة لا يقبل الطعن بالاستئناف إلا إذا كان المبلغ المتنازع فيه يزيد على ثلاثين ألف جنيه وذلك مهما كانت قيمة حق الدائن المناقض أو قيمة حصيلة التنفيذ. ويكون ميعاد استئناف هذا الحكم عشرة أيام."}, {"number": "481", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "يجب فى أستئناف الحكم الصادر فى المناقضة أختصام جميع ذوى الشأن و يقوم قلم كتاب المحكمة الأستئنافية خلال ثلاثة أيام من صدور الحكم الأستثنائى بإخبار قلم كتاب محكمة التنفيذ المستئنف حكمها بمنطوق الحكم الأستئنافى ."}, {"number": "482", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "تقوم إدارة التنفيذ خلال سبعة أيام من الأخبار المشار إليه فى المادة السابقة أو من الفصل فى المناقضات إذا كان حكمه فيها نهائياً أو من إنقضاء ميعاد أستئنافه بإيداع القائمة النهائية محررة على أساس القائمة المؤقتة و مقتضى الحكم الصادر فى المناقضة إن كان و يمضى فى الإجراءات وفقاً للمادة 478 ."}, {"number": "483", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "المناقضات فى القائمة المؤقتة لا تمنع إدارة التنفيذ من الأمر بتسليم أوامر الصرف لمستحقيها من الدائنين المتقدمين فى الدرجة الأولى على الدائنين المتنازع فى ديونهم ."}, {"number": "484", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "لكل من يكلف من ذوى الشأن الحضور امام قاضى التنفيذ أن يطلب إلى وقت تسليم أوامر الصرف إبطال الإجراءات و ذلك إما بطريق التدخل فى جلسة التسوية أو بدعوى أصلية يرفعها بالطرق المعتادة و لا يحكم بالإبطال إلا لضرر يكون قد لحق بحقوق مدعيه . فإذا حكم به أعيدت الإجراءات على نفقة المتسبب فيه من العاملين بالمحكمة و ألزم بالتعويضات إن كان لها وجه ."}, {"number": "485", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "لا يترتب على إفلاس المدين المحجوز عليه بعد مضى الميعاد المشار عليه فى المادة 469 وقف إجراءات التوزيع و لو حدد للتوقف على الدفع تاريخ سابق على الشروع فى التوزيع ."}, {"number": "486", "chapter": "الباب الرابع توزيع حصيلة التنفيذ", "text": "بعد تسليم أوامر الصرف لمستحقيها لا يكون لمن لم يعلن أو يختصم حق إبطال إجراءات التوزيع و إنما يكون له الرجوع على المتسبب من العاملين بالمحكمة بالتعويضات إن كان لها وجه ."}, {"number": "487", "chapter": "الباب الأول", "text": "يحصل العرض الحقيقى بإعلان الدائن على يد محضر ويشتمل محضر العرض على بيان الشئ المعروض وشروط العرض وقبول المعروض أو رفضه . ويحصل عرض ما لا يمكن تسليمه من الأعيان فى موطن الدائن بمجرد تكليفه على يد محضر بتسليمه."}, {"number": "488", "chapter": "الباب الأول", "text": "إذا رفض العرض وكان المعروض نقودا قام المحضر بإيداعها خزانة المحكمة فى اليوم التالى لتاريخ المحضر على الأكثر ، وعلى المحضر أن يعلن الدائن بصورة من محضر الإيداع خلال ثلاثة أيام من تاريخه. وإذا كان المعرض شيئا غير النقود جاز للمدين الذى رفض عرضه أن يطلب من قاضى الأمور المستعجلة الترخيص فى إيداعه بالمكان الذى يعينه القاضى إذا كان الشئ مما يمكن نقله اما إذا كان الشى معدا للبقاء حيث وجد جاز للمدين أن يطلب وضعة تحت الحراسة ."}, {"number": "489", "chapter": "الباب الأول", "text": "يجوز العرض الحقيقى فى الجلسة امام المحكمة بدون إجراءات إذا كان يوجه إليه العرض حاضرا . وتسلم النقود المعروضة عند رفضها لكاتب الجلسة لإيداعها خزانة المحكمة وينبت فى محضر الإيداع ما أثبت فى محضر الجلسة خاصة بالعرض ورفضه. وإذا كان المعروض فى الجلسة من غير النقود تعين على العارض أن يطلب إلى المحكمة تعيين حارس عليه ولا يقبل الطعن فى الحكم الصادر بتعين الحارس . وللعارض أن يطلب على الفور الحكم بصحة العرض ."}, {"number": "490", "chapter": "الباب الأول", "text": "لا يحكم بصحة العرض الذى لم يعقبه إيداع الا إذا تم إيداع المعروض مع فوائده التى استحقت لغاية يوم الإيداع ، وتحكم المحكمة مع صحة العرض ببراءة ذمة المدين من يوم العرض ."}, {"number": "491", "chapter": "الباب الأول", "text": "إذا لم يكن المدين قد رجع فى عرضة ، يجوز للدائن أن يقبل عرضا سبق له رفضه وان يتسلم ما أودع على ذمته ، متى اثبت للمودع لديه انه اخبر المدين على يد محضر بعزمه على التسليم قبل حصوله بثلاثة أيام على الأقل . وسلم الدائن المودع لديه صورة محضر الإيداع المسلمة ليه مع مخالصة بما قبضه."}, {"number": "492", "chapter": "الباب الأول", "text": "يجوز للمدين أن يرجع عن عرض لم يقبله دائنه وان يسترد من خزانة المحكمة ما أودعه متى اثبت انه اخبر دائنه على يد محضر برجوعه عن العرض وكان قد مضى على إخباره بذلك ثلاثة أيام ."}, {"number": "493", "chapter": "الباب الأول", "text": "لا يجوز الرجوع عن العرض ولا استرداد المودع بعد قبول الدائن لهذا العرض أو بعد صدور الحكم بصحة العرض وصيرورته نهائيا ."}, {"number": "501", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "502", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "503", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "504", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "505", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "506", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "507", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "508", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "509", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "510", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "511", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "512", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "513", "chapter": "الباب الثالث التحكيم", "text": "0000000000000 ملغاة بالـ قانون رقم 27 لسنة 1994 فى شأن التحكيم"}, {"number": "494", "chapter": "الباب الثانى", "text": "تجوز مخاصمة القضاة وأعضاء النيابة فى الأحوال الآتية : 1 - إذا وقع من القاضى أو عضو النيابة فى عملهما غش أو تدليس أو غدر أو خطأ مهنى جسيم . 2 - إذا امتنع القاضى من الاجابة على عريضة قدمت له أو من الفصل فى قضية صالحة للحكم وذلك بعد اعذاره مرتين على يد محضر يتخللهما ميعاد أربع وعشرين ساعة بالنسبة إلى الأوامر على العرائض وثلاثة أيام بالنسبة للأحكام فى الدعاوى الجزئية والمستعجلة والتجارية وثمانية أيام فى الدعاوى الأخرى . ولا يجوز رفع دعوى المخاصمة فى هذه الحالة قبل مضى ثمانية أيام على آخر أعذار . 3 - فى الأحوال الأخرى التى يقضى فيها القانون بمسئولية القاضى والحكم عليه بالتعويضات ."}, {"number": "495", "chapter": "الباب الثانى", "text": "ترفع دعوى المخاصمة بتقرير فى قلم كتاب محكمة الاستئناف التابع لها القاضى أو عضو النيابة يوقعه الطالب أو من يوكله فى ذلك توكيلا خاصا ، وعلى الطالب عند التقرير أن يودع خمسمائة جنيه على سبيل الكفالة ويجب أن يشتمل التقرير على بيان أوجه المخاصمة وأدلتها وان تودع معه الأوراق المؤدية لها . وتعرض الدعوى على احدى دوائر محكمة الاستئناف بأمر من رئيسها بعد تبليغ صورة التقرير إلى القاضى أو عضو النيابة وتنظر فى غرفة المشورة فى أول جلسة تعقد أول بعد ثمانية الأيام التالية للتبليغ . ويقوم قلم الكتاب بإخطار الطالب بالجلسة."}, {"number": "496", "chapter": "الباب الثانى", "text": "تحكم المحكمة فى تعلق أوجه المخاصمة بالدعوى وجواز قبولها وذلك بعد سماع الطالب أو وكيله والقاضى أو عضو النيابة المخاصم حسب الأحوال وأقوال النيابة العامة إذا تدخلت فى الدعوى . وإذا كان القاضى المخاصم مستشارا بمحكمة النقض تولت الفصل فى جواز قبول المخاصمة احدى دوائر هذه المحكمة فى غرفة المشورة ."}, {"number": "497", "chapter": "الباب الثانى", "text": "إذا حكم بجواز قبول المخاصمة وكان المخاصم أحد قضاة المحكمة الابتدائية أو أحد أعضاء النيابة لديها حدد الحكم جلسة لنظر موضوع المخاصمة فى جلسة علنية أمام فى دوائر اخرى من دوائر محكمة الإستئناف ولحكم فيه بعد سماع الطالب والقاضى أو عضو النيابة المخاصم واقوال النيابة العامة إذا تدخلت فى الدعوى . وإذا كان المخاصم مستشارا فى احدى محاكم الإستئناف أو النائب العام أو المحامى العام فتكون الإحالة على دائرة خاصة مؤلفة من سبعة من المستشارين بحسب ترتيب أقدميتهم . اما إذا كان المخاصم مستشارا بمحكمة النقض فتكون الإحالة إلى دوائر المحكمة مجتمعه ."}, {"number": "498", "chapter": "الباب الثانى", "text": "يكون القاضى غير صالح لنظر الدعوى من تاريخ الحكم بجواز قبول المخاصمة ."}, {"number": "499", "chapter": "الباب الثانى", "text": "\" إذا قضت المحكمة بعدم جواز المخاصمة أو برفض حكمت على الطالب بغرامة لا تقل عن ربعمائة جنيه ولا تزيد على أربعة آلاف جنيه وبمصادرة الكفالة مع التعويضات أن كان لها وجه ، وإذا قضت بصحة المخاصمة حكمت على القاضى أو عضو النيابة المخاصم ببطلان تصرفه وبالتعويضات و المصاريف \" . ومع ذلك لا تحكم المحكمة ببطلان الحكم الصادر لمصلحة خصم آخر غير المدعى فى الدعوى المخاصمة الا بعد اعلانه لإبداء أقواله ويجوز للمحكمة فى هذه الحالة أن تحكم فى الدعوى الأصلية إذا رأت انها صالحة للحكم وذلك بعد سماع أقوال الخصوم ."}, {"number": "500", "chapter": "الباب الثانى", "text": "لا يجوز الطعن فى الحكم الصادر فى دعوى المخاصمة الا بطريق النقص ."}]};